-- SRS review-card backfill — BATCH 5 of 10 (628 rows).
-- Run each batch on its own in the Supabase SQL Editor; order does not matter and
-- each is idempotent. Together the 10 batches equal backfill_srs_payload.sql.
-- Covers Top 2 preboards/mocks/reviewer + main-app banks + Top 2 banks.
WITH d(qid, patch) AS (
  VALUES
  ('341fbafc-2c','{"options": ["Retinoscope", "Perimeter", "Slit lamp", "Lensometer"], "correct": 2, "decode": "The FIT and MOVEMENT of a lens on the eye are assessed with the SLIT LAMP.", "ow": ["A retinoscope determines refraction.", "A perimeter maps fields.", "Correct. The slit lamp assesses fit and movement.", "A lensometer reads lens power."]}'),
  ('ac698a92-1t','{"options": ["Retinoscope", "Thickness gauge", "Keratometer", "Tonometer"], "correct": 1, "decode": "A THICKNESS GAUGE measures the thickness of a soft contact lens.", "ow": ["A retinoscope determines refraction.", "Correct. A thickness gauge measures lens thickness.", "A keratometer measures corneal curvature.", "A tonometer measures pressure."]}'),
  ('7e48528f-2d','{"options": ["Perimeter", "Slit lamp", "Tonometer", "Retinoscope"], "correct": 1, "decode": "A SLIT LAMP inspects a contact lens for deposits, scratches, and defects.", "ow": ["A perimeter maps fields.", "Correct. The slit lamp inspects lens deposits and defects.", "A tonometer measures pressure.", "A retinoscope determines refraction."]}'),
  ('bd169cb7-29','{"options": ["Sagittometer", "Retinoscope", "Tonometer", "Lensometer"], "correct": 0, "decode": "A SAGITTOMETER measures the sagittal depth of some contact lenses.", "ow": ["Correct. A sagittometer measures sagittal depth.", "A retinoscope determines refraction.", "A tonometer measures pressure.", "A lensometer reads lens power."]}'),
  ('7df1152a-1k','{"options": ["Flatter", "Steeper", "Thinner", "More opaque"], "correct": 1, "decode": "A SMALLER corneal radius means a tighter curve, so a STEEPER cornea.", "ow": ["A smaller radius is steeper, not flatter.", "Correct. Smaller radius = steeper cornea.", "Radius reflects curvature, not thickness.", "Radius reflects curvature, not opacity."]}'),
  ('49bd7f41-1j','{"options": ["More curved", "More powerful", "Steeper", "Flatter"], "correct": 3, "decode": "A LARGER corneal radius means a gentler curve, so a FLATTER cornea.", "ow": ["A larger radius is flatter, not more curved.", "A larger radius is flatter, so less powerful, not more.", "A larger radius is flatter, not steeper.", "Correct. Larger radius = flatter cornea."]}'),
  ('a4fdd064-z','{"options": ["Different curvature between principal meridians", "A complete absence of any corneal reflection", "Exactly equal right and left pupil sizes", "Perfectly equal curvature in all meridians"], "correct": 0, "decode": "Corneal astigmatism shows as DIFFERENT curvature between the two principal meridians.", "ow": ["Correct. Different curvature between meridians indicates astigmatism.", "Absent reflection does not indicate astigmatism.", "Equal pupils are unrelated to corneal astigmatism.", "Perfectly equal curvature is the opposite of astigmatism."]}'),
  ('2cbc19d3-1o','{"options": ["Entire retina", "Entire posterior segment", "Central anterior cornea", "Entire lens"], "correct": 2, "decode": "The keratometer''s limitation is that it samples only the CENTRAL ANTERIOR cornea.", "ow": ["It does not read the retina.", "It does not read the posterior segment.", "Correct. It samples only the central anterior cornea.", "It does not read the lens."]}'),
  ('f44f828c-1o','{"options": ["Covered with debris", "Smooth and regular", "Severely irregular", "Completely opaque"], "correct": 1, "decode": "The keratometer is most accurate on a SMOOTH, REGULAR corneal surface.", "ow": ["Debris distorts the mires.", "Correct. A smooth, regular surface gives clean mires.", "A severely irregular cornea gives unreliable readings.", "An opaque cornea does not reflect clean mires."]}'),
  ('9c57319f-1j','{"options": ["6 meters only", "Pupil diameter", "Accommodation amplitude", "Angular resolution"], "correct": 3, "decode": "Snellen notation is based on ANGULAR RESOLUTION (the visual angle the detail subtends).", "ow": ["The 6-meter distance is a testing convention, not the basis of the notation.", "Pupil diameter is not the basis.", "Accommodation amplitude is not the basis.", "Correct. Snellen is based on angular resolution."]}'),
  ('44e27035-1s','{"options": ["Lensometer", "Keratometer", "Retinoscope", "Slit lamp"], "correct": 1, "decode": "Central corneal curvature is best measured with a KERATOMETER.", "ow": ["A lensometer reads lens power.", "Correct. A keratometer measures central corneal curvature.", "A retinoscope determines refraction.", "A slit lamp examines structures, not curvature."]}'),
  ('85d58a20-1f','{"options": ["Keeping both eyes tightly closed throughout", "Deliberately looking away from the instrument", "Properly positioned and fixating on the target", "Continuously moving the head during the reading"], "correct": 2, "decode": "Before keratometry the patient should be PROPERLY POSITIONED and FIXATING on the target.", "ow": ["Closing both eyes prevents the reading.", "Looking away prevents the reading.", "Correct. Properly positioned and fixating.", "Moving the head ruins the reading."]}'),
  ('2c36a221-24','{"options": ["Ear", "Patient''s corneal apex", "Forehead only", "Chin only"], "correct": 1, "decode": "The keratometer must be aligned with the patient''s CORNEAL APEX.", "ow": ["The ear is not the alignment target.", "Correct. Align to the corneal apex.", "The forehead is not the alignment target.", "The chin is not the alignment target."]}'),
  ('913fea1a-1x','{"options": ["Unreliable", "More accurate", "Automatically corrected", "Unchanged"], "correct": 0, "decode": "If the mires are misaligned, the keratometric reading is UNRELIABLE.", "ow": ["Correct. Misaligned mires give an unreliable reading.", "Misalignment makes it less, not more, accurate.", "It is not automatically corrected.", "Misalignment changes the reading, so ''unchanged'' is wrong."]}'),
  ('19be46d4-1q','{"options": ["Eyeglass temple length", "Initial base curve selection", "Color vision", "Retinal circulation"], "correct": 1, "decode": "In fitting, keratometry helps determine the INITIAL BASE CURVE selection.", "ow": ["It does not determine spectacle temple length.", "Correct. Keratometry guides initial base curve selection.", "It does not test color vision.", "It does not assess retinal circulation."]}'),
  ('548c583f-p','{"options": ["Always spherical", "Thicker only at the center", "Thinner in the center", "Thicker in the center"], "correct": 2, "decode": "A minus (diverging) lens is THINNER in the CENTER.", "ow": ["It is not always spherical.", "It is thicker at the edge, not only the center.", "Correct. A minus lens is thinner in the center.", "Thicker in the center describes a plus lens."]}'),
  ('02b7ba9c-w','{"options": ["Plane lens", "Cylindrical mirror", "Diverging lens", "Converging lens"], "correct": 3, "decode": "A convex lens is a CONVERGING lens.", "ow": ["A plane lens has no power.", "A cylindrical mirror is not a convex lens.", "Diverging is a concave lens.", "Correct. Convex = converging."]}'),
  ('06ad2c06-x','{"options": ["Converging lens", "Diverging lens", "Magnifying lens", "Prism lens"], "correct": 1, "decode": "A concave lens is a DIVERGING lens.", "ow": ["Converging is a convex lens.", "Correct. Concave = diverging.", "A magnifying lens is a plus (converging) lens.", "A ''prism lens'' is not the concave-lens synonym."]}'),
  ('bc2033bd-20','{"options": ["Become polarized", "Reflect backward", "Converge", "Diverge"], "correct": 2, "decode": "The focal point of a plus lens is where parallel incident rays CONVERGE.", "ow": ["They are not polarized there.", "They are refracted, not reflected backward.", "Correct. Parallel rays converge at the focus.", "They converge, not diverge, at a plus-lens focus."]}'),
  ('630c9a5f-32','{"options": ["Interference", "Diffraction", "Reflection", "Refraction"], "correct": 3, "decode": "The apparent displacement of an object through a prism is due to REFRACTION.", "ow": ["Interference is wave superposition, not the prism shift.", "Diffraction is edge spreading, not the prism shift.", "Reflection bounces light; the prism shift is by bending.", "Correct. Refraction at the angled surfaces displaces the image."]}'),
  ('7cae5e39-28','{"options": ["Anophthalmos", "Phthisis bulbi", "Microphthalmos", "Buphthalmos"], "correct": 3, "decode": "Infant + cloudy cornea + tearing + big eye is congenital glaucoma, and the question wants the name for the enlarged globe. Bous means ox, so buphthalmos is the ox-eye. Every distractor here is a SMALL or shrunken eye, the opposite of enlarged.", "ow": ["Wrong direction: anophthalmos means no eye forms at all.", "Opposite state: phthisis bulbi is a shrunken end-stage eye.", "Micro means small, but the stem says the eye is enlarged.", "Correct. Bu- (ox) eye is the enlarged globe of congenital glaucoma."]}'),
  ('6c54cce5-1a','{"options": ["Dental infection", "Ethmoiditis", "Trauma", "Frontal sinusitis"], "correct": 1, "decode": "Orbital cellulitis almost always tracks in from the adjacent ethmoid sinus, held off the orbit by the paper-thin lamina papyracea. When sinus and non-sinus causes are mixed, choose the ethmoid.", "ow": ["A rare route into the orbit, not the usual source.", "Correct. The ethmoid sinus abuts the thin medial wall, the classic spread path.", "Can seed infection but is not the most common cause.", "A sinus source, but the ethmoid sits closer and is the usual culprit."]}'),
  ('f34c76a4-1l','{"options": ["Cavernous hemangioma", "Lymphoma", "Rhabdomyosarcoma", "Retinoblastoma"], "correct": 2, "decode": "Child plus PRIMARY ORBITAL malignancy is the rhabdomyosarcoma trigger. Retinoblastoma is intraocular, not orbital; hemangioma and lymphoma are adult patterns.", "ow": ["The commonest BENIGN orbital tumor in adults, not a childhood malignancy.", "An adult orbital tumor, not the pediatric answer.", "Correct. The most common primary orbital malignancy of childhood.", "Intraocular, not a primary ORBITAL tumor."]}'),
  ('3e0c10cc-22','{"options": ["Horner''s syndrome", "Myasthenia gravis", "CN3 palsy", "Aponeurotic ptosis"], "correct": 1, "decode": "Two buzzwords decide it: ''fatiguable'' and ''improves with Tensilon (edrophonium).'' Both are myasthenia signatures. A fixed structural ptosis would not fluctuate or respond to edrophonium.", "ow": ["Its ptosis is mild and steady, and Tensilon does nothing.", "Correct. Fatiguable ptosis improving with edrophonium is classic myasthenia.", "Ptosis is present but fixed, often down-and-out; no Tensilon response.", "A stretched-tendon ptosis, steady all day, unaffected by Tensilon."]}'),
  ('269a3a67-13','{"options": ["Aponeurotic", "Neurogenic", "Myogenic", "Mechanical"], "correct": 0, "decode": "''Most common adult ptosis'' is aponeurotic (involutional): the levator tendon stretches with age. The other types are real but far less common, so default to aponeurotic for the typical older adult.", "ow": ["Correct. Age-related levator aponeurosis stretching is the commonest adult ptosis.", "From a nerve palsy (CN3, Horner); less common than involutional.", "From muscle disease like myasthenia or dystrophy; uncommon.", "From a lid mass or scarring; not the usual cause."]}'),
  ('0fc4a868-z','{"options": ["Ptosis, miosis, anhidrosis", "Ptosis, mydriasis, anhidrosis", "Ptosis, miosis, exophthalmos", "Proptosis, mydriasis, tearing"], "correct": 0, "decode": "Horner''s is SYMPATHETIC failure, so everything is ''less'': droopy lid, small pupil, dry skin (ptosis, miosis, anhidrosis). Any option with mydriasis or proptosis breaks the sympathetic-loss pattern.", "ow": ["Correct. The sympathetic-loss triad: small pupil, mild droop, dry face.", "Mydriasis is wrong; sympathetic loss gives a SMALL pupil.", "Horner causes mild enophthalmos, not exophthalmos.", "None of these fit underactive sympathetics."]}'),
  ('5796d1e4-15','{"options": ["Hordeolum", "Basal cell carcinoma", "Chalazion", "Dacryocystitis"], "correct": 2, "decode": "Chronic + non-tender + firm is a chalazion, a cold lipogranuloma of a meibomian gland. Contrast the acute, tender hordeolum. ''Painless and firm'' is the chalazion tell.", "ow": ["Acute and tender, the opposite of this chronic painless nodule.", "Possible for a chronic lump, but not the classic firm painless nodule answer.", "Correct. A chronic, firm, painless meibomian lipogranuloma.", "A tender medial-canthus tear-sac swelling, not a lid-margin nodule."]}'),
  ('965244f6-1g','{"options": ["Distichiasis", "Trichiasis", "Ectropion", "Entropion"], "correct": 2, "decode": "CN VII palsy weakens orbicularis, so the lid sags OUTWARD: ectropion (ec = out). Entropion is the inward opposite, and the lash options do not describe lid turning.", "ow": ["An extra lash row, not a turning of the lid.", "Misdirected lashes, not lid eversion.", "Correct. Orbicularis weakness from CN VII palsy everts the lid.", "Inward turning, the opposite of what facial palsy causes."]}'),
  ('97eb00c6-15','{"options": ["Basal cell carcinoma", "Sebaceous carcinoma", "Melanoma", "Squamous cell carcinoma"], "correct": 0, "decode": "''Most common malignant eyelid tumor'' is basal cell carcinoma, usually lower lid or medial canthus in sun-exposed skin. The others are real lid cancers but far rarer.", "ow": ["Correct. By far the commonest malignant lid tumor.", "Aggressive but uncommon; can masquerade as a chalazion.", "Rare on the eyelid.", "Less common than basal cell on the lid."]}'),
  ('2d8e95f3-1d','{"options": ["Squamous cell carcinoma", "Lymphoma", "Pleomorphic adenoma", "Adenoid cystic carcinoma"], "correct": 3, "decode": "Split the lacrimal gland tumors: pleomorphic adenoma is the commonest BENIGN one; adenoid cystic carcinoma is the commonest MALIGNANT one (painful, perineural spread). The stem says malignant.", "ow": ["Not a typical lacrimal gland malignancy.", "Occurs in the gland but is not the classic most-common-malignant answer.", "This is the benign one; the stem asks for malignant.", "Correct. The commonest malignant lacrimal gland tumor, notorious for pain."]}'),
  ('18d88f4e-2e','{"options": ["DCR", "Probing", "Massage", "Antibiotic drops only"], "correct": 0, "decode": "Chronic dacryocystitis is a blocked, infected tear sac. ''Definitively'' rules out temporizing steps (massage, drops, probing); the cure surgically bypasses the block with a DCR.", "ow": ["Correct. Dacryocystorhinostomy bypasses the blocked duct, the definitive fix.", "Used for congenital duct obstruction, not adult chronic dacryocystitis.", "A temporizing measure, not definitive.", "Treats infection briefly but leaves the block."]}'),
  ('3f3e1675-1q','{"options": ["A simple sac infection", "Carcinoma of the sac", "Canalicular stenosis", "An allergic reaction"], "correct": 1, "decode": "Regurgitation of BLOOD (not just mucopus) from the sac is a red flag for a lacrimal sac tumor. Ordinary infection refluxes mucopurulent material, not blood.", "ow": ["Yields mucopus, not blood.", "Correct. Bloody regurgitation signals a sac malignancy.", "Blocks tears but does not cause bloody reflux.", "Not a cause of blood from the sac."]}'),
  ('118eff4e-1j','{"options": ["Thyroid eye disease", "Cellulitis", "Trauma", "Orbital tumor"], "correct": 0, "decode": "''Most common cause of proptosis in adults,'' unilateral or bilateral, is thyroid eye disease. Cellulitis, trauma, and tumors cause proptosis too but are less common overall.", "ow": ["Correct. The commonest adult proptosis cause overall.", "Acute proptosis with infection signs, less common overall.", "Causes proptosis via hemorrhage but is not the leading cause.", "A cause, but rarer than thyroid disease."]}'),
  ('79172061-v','{"options": ["Cellulitis", "Orbital varices", "Thyroid disease", "Carotid-cavernous fistula"], "correct": 3, "decode": "''Pulsating'' is the keyword. A pulse plus a bruit means arterial flow into orbital veins: a carotid-cavernous fistula. Static causes (thyroid, tumor, cellulitis) do not pulsate.", "ow": ["Proptosis with infection, but no pulsation.", "Proptosis worse on straining, not a true arterial pulse.", "Common proptosis, but non-pulsatile.", "Correct. Arterialized orbital veins give pulsating exophthalmos with a bruit."]}'),
  ('c7469d1c-1x','{"options": ["Acute dacryoadenitis", "Sjogren''s syndrome", "Mikulicz syndrome", "Mumps"], "correct": 2, "decode": "Bilateral, painless, BOTH lacrimal and salivary glands enlarged is Mikulicz. Acute dacryoadenitis is painful and unilateral; mumps hits parotid glands mainly.", "ow": ["Painful and usually unilateral, not this painless bilateral picture.", "Causes dry eye and mouth from gland destruction, not painless enlargement of both.", "Correct. Painless bilateral lacrimal and salivary gland enlargement.", "Mainly parotid (salivary) swelling, and usually painful."]}'),
  ('4e65d867-1j','{"options": ["Ectropion of the lower lid", "Lagophthalmos on closure", "Complete mechanical ptosis", "S-shaped ptosis of the lid"], "correct": 3, "decode": "Dacryoadenitis swells the lacrimal gland in the superolateral lid, dropping that outer corner and bending the lid margin into an S. That S-shape is the specific tell.", "ow": ["Not a feature of lacrimal gland inflammation.", "A closure problem, not the dacryoadenitis sign.", "The ptosis is partial and S-shaped, not complete.", "Correct. Superolateral gland swelling gives the classic S-shaped lid."]}'),
  ('45a748bd-24','{"options": ["Hyperlipidemia", "Thyroid disease", "Anemia", "Diabetes"], "correct": 0, "decode": "Xanthelasma means yellow LIPID plaques, so the screen is for a lipid problem: hyperlipidemia. The other systemic diseases are not what lipid plaques flag.", "ow": ["Correct. Lipid plaques prompt a cholesterol and lipid screen.", "Not signaled by xanthelasma.", "Unrelated to lid lipid deposits.", "Not the direct association of xanthelasma."]}'),
  ('ba488180-1l','{"options": ["Ptosis", "Lagophthalmos", "Blepharospasm", "Entropion"], "correct": 1, "decode": "''Cannot fully close'' the eye is lagophthalmos (lagos = hare, sleeping with eyes open). Ptosis is a droop, blepharospasm is forced closure, entropion is inturning.", "ow": ["A drooping lid, not a failure to close.", "Correct. Incomplete lid closure, classically from facial palsy.", "Excess forced closure, the opposite problem.", "Inward lid turning, not a closure failure."]}'),
  ('faf030a1-1d','{"options": ["Lymphoma", "Glioma", "Rhabdomyosarcoma", "Cavernous hemangioma"], "correct": 3, "decode": "''Most common BENIGN orbital tumor in adults'' is cavernous hemangioma (slow, painless proptosis). Rhabdomyosarcoma and glioma are pediatric; lymphoma is not benign.", "ow": ["A malignant lymphoid orbital lesion, not benign.", "Optic nerve glioma is a childhood tumor.", "The malignant childhood orbital tumor.", "Correct. The commonest benign adult orbital tumor."]}'),
  ('406f7564-22','{"options": ["Essential blepharospasm", "Myokymia", "Blepharoclonus", "Hemifacial spasm"], "correct": 0, "decode": "Bilateral, involuntary, forceful lid closure treated with botulinum toxin is essential blepharospasm. Myokymia is a fine twitch; hemifacial spasm is unilateral.", "ow": ["Correct. Bilateral involuntary lid closure, treated with botulinum toxin.", "A fine, benign lid twitch, not forceful closure.", "Exaggerated blinking, not sustained spasm.", "Unilateral facial spasm, not bilateral lid closure."]}'),
  ('db9af78c-1v','{"options": ["Trichiasis", "Madarosis", "Poliosis", "Distichiasis"], "correct": 3, "decode": "An EXTRA row of lashes emerging from the meibomian orifices is distichiasis (di = two rows). Trichiasis is misdirected normal lashes; madarosis and poliosis are loss and whitening.", "ow": ["Normal lashes misdirected inward, not an extra row.", "Loss of lashes, the opposite.", "Whitening of lashes, not an extra row.", "Correct. A second lash row from the meibomian gland orifices."]}'),
  ('39e47673-1t','{"options": ["Pseudomonas", "Chlamydia", "Staphylococcus", "Pneumococcus"], "correct": 3, "decode": "Newborn dacryocystitis follows a blocked nasolacrimal duct; the organism named in boards is pneumococcus (Streptococcus pneumoniae). The others are less typical for the neonatal sac.", "ow": ["Not the classic neonatal dacryocystitis organism.", "Causes neonatal conjunctivitis, not the sac infection here.", "Skin flora, but not the classic answer.", "Correct. The classic organism in congenital dacryocystitis."]}'),
  ('d6c015fd-2h','{"options": ["Pannus", "Pinguecula", "Pterygium", "Phlyctenule"], "correct": 2, "decode": "Two clues nail it: ''wing-shaped'' (pteryx = wing) and ''crosses the limbus onto the cornea.'' A pinguecula never crosses the limbus; pannus is vascular but not wing-shaped.", "ow": ["Vascular corneal ingrowth, but not a wing-shaped limbal lesion.", "Stays on the conjunctiva and does NOT cross the limbus.", "Correct. A wing-shaped growth crossing the limbus, destroying Bowman''s layer.", "A small hypersensitivity nodule, not a wing crossing the cornea."]}'),
  ('3a3a0f0e-1i','{"options": ["Bacterial conjunctivitis", "Trachoma", "Herpes keratitis", "Onchocerciasis"], "correct": 1, "decode": "''Leading INFECTIOUS cause of blindness worldwide'' is trachoma (Chlamydia trachomatis). Onchocerciasis is second; herpes and bacterial conjunctivitis are not the global leader.", "ow": ["Common but not a leading blinding infection.", "Correct. Chlamydial trachoma is the top infectious cause of blindness worldwide.", "A leading cause in developed countries, not worldwide.", "River blindness, the second infectious cause, not the first."]}'),
  ('d4756503-2k','{"options": ["An inflamed pinguecula", "Subconjunctival hemorrhage", "A deep intraocular process", "Allergic conjunctivitis"], "correct": 2, "decode": "Circumcorneal (ciliary) injection is violet, deep, and does NOT blanch with topical epinephrine, marking a serious deep process (iritis, keratitis, glaucoma). Superficial conjunctival redness would blanch and be brick-red.", "ow": ["A superficial focal lesion whose vessels blanch.", "A flat patch of blood, not a vascular ring around the cornea.", "Correct. Non-blanching violet ciliary flush signals deep intraocular inflammation.", "Superficial, itchy, blanching redness, not a deep flush."]}'),
  ('569e48c9-z','{"options": ["Vogt''s striae", "Hydrops", "Fleischer ring", "Munson''s sign"], "correct": 2, "decode": "Keratoconus signs in order: Fleischer ring (iron at the cone base) is EARLIEST, then Vogt''s striae, then Munson''s sign, with hydrops late. The stem asks earliest.", "ow": ["Stress lines, but they appear after the Fleischer ring.", "A late complication (Descemet rupture), not earliest.", "Correct. The iron ring at the cone base is the earliest sign.", "V-shaped lower-lid bulge on downgaze, a later sign."]}'),
  ('3aa4f6ee-20','{"options": ["Hemochromatosis", "Diabetes", "Wilson''s disease", "Gout"], "correct": 2, "decode": "A green-gold ring in Descemet''s is the Kayser-Fleischer ring, meaning copper, meaning Wilson''s disease. The other metabolic diseases do not deposit copper in Descemet''s.", "ow": ["Iron overload, not the copper ring.", "No corneal copper ring.", "Correct. Copper deposition in Descemet''s gives the K-F ring.", "A urate disease, not corneal copper."]}'),
  ('0a9e7784-12','{"options": ["Pannus", "Pinguecula", "Phlyctenule migrating onto cornea", "Pterygium"], "correct": 1, "decode": "This is a ''which does NOT cross the limbus'' item. Pterygium, pannus, and a migrating phlyctenule all reach the cornea; only the pinguecula stays on the conjunctival side.", "ow": ["Vascular tissue that DOES creep onto the cornea.", "Correct. It stays on the conjunctiva and does not cross the limbus.", "By definition here it migrates onto the cornea.", "Crosses the limbus onto the cornea."]}'),
  ('839b5f1d-27','{"options": ["Giant papillary conjunctivitis", "Phlyctenular keratoconjunctivitis", "Trachoma", "Vernal keratoconjunctivitis"], "correct": 3, "decode": "Young male + giant cobblestone papillae on the upper tarsus + shield ulcer is vernal keratoconjunctivitis (seasonal atopy). GPC is contact-lens related; trachoma scars; phlyctenular is nodular.", "ow": ["Contact-lens or prosthesis related, without a shield ulcer in a young atopic boy.", "Small limbal nodules, not giant tarsal cobblestones.", "Chlamydial follicles and scarring, not seasonal cobblestone papillae.", "Correct. Cobblestone papillae and shield ulcer in a young atopic male."]}'),
  ('48c78799-1i','{"options": ["Allergy to pollen", "Contact lens wear", "Bacterial infection", "Dry eye"], "correct": 1, "decode": "Giant papillary conjunctivitis is a mechanical-allergic response, classically to contact lenses (or sutures, prostheses). Pollen allergy and infection are different mechanisms.", "ow": ["Causes seasonal allergic conjunctivitis, not mechanical GPC.", "Correct. GPC is classically triggered by contact lens or foreign-body wear.", "Produces mucopurulent conjunctivitis, not giant papillae.", "Not the cause of GPC."]}'),
  ('44e66a69-1v','{"options": ["Plasma cells, serous", "Lymphocytes, watery", "Neutrophils, mucopurulent", "Eosinophils, stringy"], "correct": 2, "decode": "Match cell to cause: bacteria give neutrophils and mucopurulent discharge; virus gives lymphocytes and watery; allergy gives eosinophils and stringy. The stem says bacterial.", "ow": ["Plasma cells suggest chlamydia or trachoma, not acute bacterial.", "That is the VIRAL pattern.", "Correct. Bacteria draw neutrophils with thick pus.", "That is the ALLERGIC pattern."]}'),
  ('db9393a7-2f','{"options": ["A bacterial corneal ulcer", "Filamentary fungal keratitis", "Acanthamoeba keratitis", "Herpes simplex keratitis"], "correct": 3, "decode": "A branching (dendritic) ulcer with terminal end-bulbs that stains with fluorescein is herpes simplex keratitis. Bacterial and fungal ulcers are not dendritic; Acanthamoeba gives a ring.", "ow": ["Round suppurative ulcer, not a branching dendrite.", "Feathery infiltrate with satellites, not a dendrite with bulbs.", "Ring infiltrate and severe pain, not a dendrite.", "Correct. Dendritic ulcer with terminal bulbs, the HSV signature."]}'),
  ('ddd4e13d-2g','{"options": ["Mild, self-limiting disease", "An allergic skin reaction", "Bacterial superinfection", "Nasociliary nerve involvement"], "correct": 3, "decode": "Hutchinson''s sign, zoster vesicles on the nose TIP, follows the nasociliary branch that also supplies the eye, warning of ocular involvement. It is a bad sign, not benign.", "ow": ["Opposite; it warns of likely ocular involvement.", "It is viral zoster, not allergy.", "Not what the nose-tip vesicles indicate.", "Correct. Nose-tip vesicles flag nasociliary (ocular) involvement."]}'),
  ('5f8d3247-1m','{"options": ["Marcus Gunn", "Adie''s pupil", "Argyll-Robertson", "Horner''s"], "correct": 1, "decode": "A tonic (large, sluggish) pupil that constricts to DILUTE 0.1% pilocarpine shows denervation supersensitivity, which is Adie''s pupil. A normal pupil ignores such a weak dose.", "ow": ["That is an afferent defect (RAPD), not a tonic pupil.", "Correct. Denervation supersensitivity constricts it to dilute pilocarpine.", "Small pupils with light-near dissociation, tested differently.", "A small pupil from sympathetic loss, not a tonic dilated one."]}'),
  ('8782ccf0-2i','{"options": ["Argyll-Robertson pupils", "Horner''s pupils", "Marcus Gunn pupils", "Adie''s pupils"], "correct": 0, "decode": "Small, irregular pupils that ACCOMMODATE but do not REACT to light, from neurosyphilis, are Argyll-Robertson pupils. Light-near dissociation is the tell.", "ow": ["Correct. Light-near dissociation from neurosyphilis.", "Small from sympathetic loss but react normally to light.", "An afferent defect, not light-near dissociation.", "A large tonic pupil, the opposite of small and irregular."]}'),
  ('7a7394c8-1i','{"options": ["A mid-dilated, fixed pupil", "A normal pupil, clear cornea", "A small pinpoint pupil", "Bilateral gradual field loss"], "correct": 0, "decode": "Acute angle closure is a pressure spike; the pupil is stuck MID-DILATED and fixed, the cornea hazy, with pain. A pinpoint or normal pupil argues against it.", "ow": ["Correct. The non-reactive mid-dilated pupil of acute angle closure.", "Angle closure gives a hazy cornea and abnormal pupil.", "Miosis is not the angle-closure pattern.", "That is chronic open-angle glaucoma, not an acute attack."]}'),
  ('1f904c18-2n','{"options": ["Neovascular", "Phacomorphic", "Phacolytic", "Pupillary block"], "correct": 2, "decode": "Match the phaco- glaucomas: phacoLYTIC means leaked LENS protein clogs the meshwork (hypermature cataract); phacoMORPHIC means a swollen lens pushes the iris forward. The stem says leaking protein.", "ow": ["New vessels over the angle, not lens protein.", "A swollen lens causing angle closure, not protein leak.", "Correct. Leaked lens protein clogs the trabecular meshwork.", "Aqueous blocked at the pupil, not protein clogging."]}'),
  ('8da3e21e-1e','{"options": ["Posteriorly", "Superotemporally", "It does not dislocate", "Inferiorly"], "correct": 1, "decode": "Remember the pair: Marfan dislocates the lens UP and OUT (superotemporal); homocystinuria dislocates it DOWN and IN. The stem is Marfan.", "ow": ["Not the Marfan direction.", "Correct. Marfan lens subluxates up and out.", "It does dislocate; ectopia lentis is a Marfan feature.", "Down-and-in is homocystinuria, not Marfan."]}'),
  ('121079bb-21','{"options": ["Second sight", "Sudden blindness", "Hypermetropic shift", "No refractive change"], "correct": 0, "decode": "A nuclear cataract adds lens power, causing a MYOPIC shift, so presbyopes briefly read without glasses: second sight. It is a myopic, not hypermetropic, shift and is temporary.", "ow": ["Correct. The myopic shift of nuclear sclerosis briefly improves near vision.", "Nuclear cataract progresses slowly, not suddenly.", "Wrong direction; nuclear sclerosis is a MYOPIC shift.", "There is a change, toward myopia."]}'),
  ('b783b6e5-30','{"options": ["Posterior subcapsular", "Cortical", "Anterior subcapsular", "Nuclear"], "correct": 0, "decode": "Posterior subcapsular cataract sits on the visual axis, so it disables early (glare, near vision) and is steroid- and diabetes-linked. Its axial location explains the outsized disability.", "ow": ["Correct. Axial location makes it most visually disabling, and it is steroid-linked.", "Spoke opacities, less axial, less disabling early.", "Less common and less visually disabling.", "Central sclerosis, but not the steroid-linked disabling type described."]}'),
  ('5903cbc4-1s','{"options": ["Galactosemia", "Wilson''s disease", "Diabetes mellitus", "Hypocalcemia"], "correct": 2, "decode": "A true snowflake cataract that can progress in days is the classic osmotic cataract of young diabetics. Galactosemia gives oil-droplet; Wilson gives sunflower; hypocalcemia gives punctate.", "ow": ["Gives an oil-droplet cataract, not a snowflake.", "Sunflower cataract, not snowflake.", "Correct. The rapid snowflake cataract of young diabetics.", "Punctate lens opacities, not the snowflake."]}'),
  ('04ddb66e-1v','{"options": ["Granulomatous", "Viral", "Fuchs heterochromic", "Allergic"], "correct": 0, "decode": "Large, greasy mutton-fat keratic precipitates mean GRANULOMATOUS uveitis (TB, sarcoid, VKH). Fine or stellate KPs are non-granulomatous. The word ''mutton-fat'' is the tell.", "ow": ["Correct. Mutton-fat KPs are the granulomatous signature.", "Tends to give fine or stellate KPs, not mutton-fat.", "Stellate KPs over the endothelium, not greasy mutton-fat.", "Not a keratic-precipitate disease."]}'),
  ('989ed363-1o','{"options": ["Allergic eye disease", "Uncorrected refractive error", "Evaporative dry eye", "HLA-B27 disease or Behcet''s"], "correct": 3, "decode": "A hypopyon (layered pus) in acute anterior uveitis points to HLA-B27 associated disease or Behcet''s. Refractive error, allergy, and dry eye do not cause hypopyon.", "ow": ["Surface allergy, no anterior-chamber pus.", "Not an inflammatory cause.", "A surface disorder, not hypopyon uveitis.", "Correct. Classic causes of hypopyon anterior uveitis."]}'),
  ('fd7f6a17-1f','{"options": ["Anti-VEGF", "Topical steroid + cycloplegic", "Topical antibiotic only", "Laser iridotomy"], "correct": 1, "decode": "Anterior uveitis treatment has two jobs: quiet inflammation with a topical steroid and prevent synechiae and pain with a cycloplegic. Antibiotics, anti-VEGF, and iridotomy treat other diseases.", "ow": ["For neovascular retinal disease, not uveitis.", "Correct. Steroid calms inflammation; cycloplegic prevents synechiae and eases pain.", "Uveitis is inflammatory, not primarily bacterial surface disease.", "A treatment for angle closure, not uveitis."]}'),
  ('ac381ae9-1h','{"options": ["Mutton-fat keratic precipitates", "A lighter iris, no synechiae", "A darker iris with synechiae", "A dense hypopyon"], "correct": 1, "decode": "Fuchs heterochromic cyclitis is low-grade with iris HETEROCHROMIA (lighter affected iris), stellate KPs, and characteristically NO posterior synechiae. ''No synechiae plus heterochromia'' is the tell.", "ow": ["Those are granulomatous; Fuchs shows fine stellate KPs.", "Correct. Heterochromia with a notable absence of synechiae.", "Wrong; the affected iris is lighter and synechiae are absent.", "Not a feature of Fuchs cyclitis."]}'),
  ('204ba123-29','{"options": ["Pinguecula", "Episcleritis", "Conjunctivitis", "Scleritis"], "correct": 3, "decode": "Severe, boring, radiating pain plus a systemic autoimmune link (RA, TB) is scleritis, not the mild episcleritis. Deep pain and systemic association separate it from surface disease.", "ow": ["A painless surface deposit.", "Mild, often painless; not deep boring pain.", "Surface irritation, not deep pain.", "Correct. Deep boring pain with systemic disease is scleritis."]}'),
  ('7ab4e254-1m','{"options": ["Anti-VEGF", "EDTA chelation", "Laser iridotomy", "Antiviral drops"], "correct": 1, "decode": "Band keratopathy is CALCIUM in Bowman''s layer, so treatment chelates calcium: EDTA. Anti-VEGF, iridotomy, and antivirals treat unrelated conditions.", "ow": ["For neovascular disease, not calcium.", "Correct. EDTA chelates the calcium deposit.", "For angle closure, not band keratopathy.", "For herpetic disease, not calcium."]}'),
  ('90dcdee9-1g','{"options": ["+10 to +12 D hyperopia", "−3 D myopia", "−10 D myopia", "Emmetropia"], "correct": 0, "decode": "Removing the lens removes about +10 to +12 D of converging power, so the eye becomes very HYPEROPIC (aphakic hyperopia). The minus and emmetropia options ignore the lost lens power.", "ow": ["Correct. Losing the lens leaves high hyperopia.", "Wrong sign; aphakia is hyperopic.", "Wrong sign and cause.", "The eye is far from emmetropic without its lens."]}'),
  ('d3be4317-2k','{"options": ["Wilson''s disease", "Fuchs dystrophy", "Keratoconus", "Pigment dispersion syndrome"], "correct": 3, "decode": "A vertical pigment spindle on the corneal endothelium (Krukenberg spindle), with mid-peripheral iris transillumination, is pigment dispersion syndrome. The other diseases do not shed iris pigment this way.", "ow": ["Copper K-F ring, not a pigment spindle.", "Endothelial guttata, not pigment.", "A shape disorder, no pigment spindle.", "Correct. Krukenberg spindle is its endothelial pigment sign."]}'),
  ('0685fa9c-s','{"options": ["Schirmer <5 mm only", "Schirmer <25 mm and TBUT <30 sec", "Schirmer <10 mm and TBUT <10 sec", "TBUT <2 sec only"], "correct": 2, "decode": "Use the ''both under 10'' rule: dry eye is suggested by Schirmer under 10 mm and TBUT under 10 seconds. The 25/30 and single-value options are distractors.", "ow": ["Too strict and ignores TBUT.", "Far too lenient; those are near-normal values.", "Correct. The standard ''both under 10'' dry-eye cutoffs.", "One value alone is not the standard pair."]}'),
  ('1b94248e-1w','{"options": ["Pterygium", "Vitamin A deficiency", "Meibomian gland dysfunction", "Sjogren''s syndrome"], "correct": 3, "decode": "Split dry eye: AQUEOUS-deficient means the lacrimal gland fails, classically Sjogren''s; EVAPORATIVE means meibomian gland dysfunction. The stem says aqueous deficiency.", "ow": ["A surface growth, not a tear-production failure.", "Causes xerophthalmia and keratinization, not the autoimmune aqueous-deficient type.", "That is the EVAPORATIVE type, not aqueous deficiency.", "Correct. Autoimmune lacrimal destruction is the classic aqueous-deficient dry eye."]}'),
  ('0e4b202f-2m','{"options": ["Repeat cataract surgery", "Anti-VEGF", "Steroid drops", "YAG laser capsulotomy"], "correct": 3, "decode": "Posterior capsule opacification after ECCE is ''after-cataract.'' You do not re-operate; a YAG laser simply opens the cloudy capsule. That non-surgical laser opening is the tell.", "ow": ["Unnecessary; the lens is already out.", "For neovascular disease, not a cloudy capsule.", "Do not clear an opacified capsule.", "Correct. A YAG capsulotomy opens the opacified posterior capsule."]}'),
  ('1d96caed-2a','{"options": ["Retinal detachment", "CRVO", "Optic neuritis", "CRAO"], "correct": 3, "decode": "Sudden painless monocular loss + PALE ischemic retina + cherry-red fovea is central retinal ARTERY occlusion. The cherry-red spot is the thin fovea showing choroid through pale swollen retina.", "ow": ["Gives a curtain and flashes, not a pale retina with cherry spot.", "Blood-and-thunder hemorrhages, not a pale retina.", "Pain on movement and an RAPD, retina not pale.", "Correct. Pale retina with cherry-red fovea is arterial occlusion."]}'),
  ('bc73e4e1-29','{"options": ["Diabetic macular edema", "CRVO", "CRAO", "ARMD"], "correct": 1, "decode": "''Blood and thunder'' with diffuse four-quadrant hemorrhages and engorged tortuous VEINS is central retinal VEIN occlusion. Arterial occlusion gives a pale retina, the opposite look.", "ow": ["Focal leakage, not diffuse four-quadrant hemorrhage.", "Correct. Diffuse hemorrhages with dilated tortuous veins is venous occlusion.", "Pale retina, not a hemorrhagic fundus.", "Macular drusen or neovascular change, not diffuse hemorrhage."]}'),
  ('5d524be3-18','{"options": ["Hard exudates", "Neovascularization", "Cotton-wool spots", "Microaneurysm"], "correct": 3, "decode": "The EARLIEST visible diabetic lesion is the microaneurysm, a tiny capillary outpouching. Hard exudates, cotton-wool spots, and neovascularization all come later.", "ow": ["Later lipid leakage, not the earliest sign.", "A late, proliferative sign.", "Ischemic infarcts appearing after microaneurysms.", "Correct. The earliest ophthalmoscopic sign of diabetic retinopathy."]}'),
  ('9d09cead-1r','{"options": ["4-2-1 rule", "1-2-3 rule", "ABCD rule", "ISNT rule"], "correct": 0, "decode": "Severe NPDR is defined by the 4-2-1 rule: hemorrhages in 4 quadrants, OR venous beading in 2, OR IRMA in 1. ISNT is a disc rule; ABCD is for moles.", "ow": ["Correct. Hemorrhages in 4 quadrants, beading in 2, or IRMA in 1.", "Not a retinopathy grading rule.", "A melanoma and mole rule.", "A rule for the normal optic disc rim."]}'),
  ('a0cfbd92-r','{"options": ["Drusen", "Hemorrhages", "Nerve fiber layer infarcts", "Lipid exudates"], "correct": 2, "decode": "Cotton-wool spots are fluffy white patches, which are NERVE FIBER LAYER infarcts from ischemia. Hard exudates are lipid, drusen are deposits, hemorrhages are blood.", "ow": ["Yellow deposits under the RPE, not ischemic infarcts.", "Blood, not the fluffy infarct.", "Correct. Cotton-wool spots are ischemic nerve fiber layer infarcts.", "Those are hard exudates, waxy and yellow."]}'),
  ('9ad2b970-1e','{"options": ["Observation", "Topical steroids", "Cycloplegics", "Panretinal photocoagulation"], "correct": 3, "decode": "Proliferative DR (new vessels) is treated by PANretinal photocoagulation to ablate ischemic retina and cut the VEGF drive. Observation, steroids, and cycloplegics do not treat neovascularization.", "ow": ["Unsafe once neovascularization is present.", "Do not regress retinal new vessels.", "Irrelevant to proliferative disease.", "Correct. Panretinal photocoagulation is standard for proliferative DR."]}'),
  ('31d6f550-1m','{"options": ["Age-related macular degeneration", "Central retinal artery occlusion", "Hypertensive retinopathy", "Diabetic retinopathy"], "correct": 2, "decode": "A macular STAR of hard exudates plus disc swelling is malignant HYPERTENSIVE retinopathy. Diabetes lacks the star-plus-swelling pattern; ARMD and CRAO differ.", "ow": ["Drusen and degeneration, not a star with papilledema.", "Pale retina, not an exudative star.", "Correct. Macular star with disc swelling is malignant hypertension.", "Microaneurysms and exudates, not the star-plus-papilledema picture."]}'),
  ('c8e8f47f-1n','{"options": ["Mixed", "Wet", "Myopic", "Dry"], "correct": 3, "decode": "''Most common'' ARMD is the DRY (non-exudative, drusen) type, about 90%. Wet is less common but more sight-threatening. The stem asks most common.", "ow": ["Not the standard most-common answer.", "Less common though more severe.", "A different degeneration, not the age-related type.", "Correct. Dry (drusen) ARMD is the most common form."]}'),
  ('91eaaccf-1c','{"options": ["Observation", "Laser only", "AREDS2 vitamins only", "Intravitreal anti-VEGF"], "correct": 3, "decode": "Wet ARMD is driven by VEGF-fueled choroidal new vessels, so first-line is intravitreal anti-VEGF. Observation, laser alone, and vitamins do not stop active neovascular leakage.", "ow": ["Unsafe for active neovascular disease.", "Largely replaced by anti-VEGF.", "Slows DRY progression; does not treat active wet disease.", "Correct. Intravitreal anti-VEGF is first-line for wet ARMD."]}'),
  ('2f16d2cc-1z','{"options": ["Retinitis pigmentosa", "Diabetic retinopathy", "ARMD", "CRVO"], "correct": 0, "decode": "The triad night blindness + bone-spicule pigment + waxy pale disc (with attenuated vessels) is retinitis pigmentosa. The other retinopathies lack bone-spicule pigment.", "ow": ["Correct. Night blindness, bone-spicule pigment, and a waxy disc.", "Microaneurysms and exudates, no bone spicules.", "Macular drusen, not peripheral bone spicules.", "A hemorrhagic fundus, not pigmentary."]}'),
  ('ed351139-22','{"options": ["CMV retinitis", "VKH", "Toxoplasmosis", "Toxocariasis"], "correct": 2, "decode": "''Headlight in the fog'' is an active focal chorioretinitis glowing through vitreous haze beside an OLD pigmented scar, which is reactivated toxoplasmosis. CMV gives pizza-pie; VKH is panuveitis.", "ow": ["Pizza-pie hemorrhagic retinitis in AIDS, not a focal scar lesion.", "Bilateral panuveitis with systemic signs.", "Correct. Focal chorioretinitis beside an old scar, the headlight-in-fog look.", "A peripheral granuloma with leukocoria, not satellite reactivation."]}'),
  ('91b97683-1x','{"options": ["Histoplasmosis", "ARMD", "CMV retinitis", "Toxoplasmosis"], "correct": 2, "decode": "''Pizza-pie'' hemorrhagic retinitis in advanced HIV (CD4 under 50) is CMV retinitis. The very low CD4 plus hemorrhage-and-necrosis pattern is the tell.", "ow": ["Punched-out scars, not hemorrhagic pizza-pie.", "An age-related macular disease.", "Correct. Pizza-pie retinitis with very low CD4.", "Focal scar reactivation, not diffuse hemorrhagic necrosis."]}'),
  ('018982d3-1l','{"options": ["Serous", "Rhegmatogenous", "Tractional", "Exudative"], "correct": 1, "decode": "''Rhegma'' means break, so a RHEGMATOGENOUS detachment is the one with an actual retinal tear. Serous, exudative, and tractional detachments have no break.", "ow": ["Fluid under the retina without a break.", "Correct. ''Rhegma'' means break, a true retinal tear.", "A membrane pulls the retina, no break.", "Fluid leakage, no break."]}'),
  ('0d486d00-22','{"options": ["A retinal break", "An early cataract", "A vitreous hemorrhage", "Normal vitreous aging"], "correct": 0, "decode": "Pigment cells in the anterior vitreous (''tobacco dust,'' Shafer''s sign) are liberated by a retinal break, warning of a tear or detachment. Not cataract or normal aging.", "ow": ["Correct. Tobacco dust means pigment from a retinal tear.", "A lens change, unrelated to vitreous pigment.", "That is red blood, not pigment cells.", "Aging gives floaters, not pigment (Shafer''s) cells."]}'),
  ('fa1878f4-2i','{"options": ["CRAO", "Optic neuritis", "Papilledema", "NAION"], "correct": 1, "decode": "Young woman + subacute vision loss + pain on eye movement + RAPD is optic neuritis (often MS). CRAO is sudden and painless; NAION and papilledema differ.", "ow": ["Sudden, painless, with a pale retina.", "Correct. Painful subacute loss with an RAPD in a young woman.", "Bilateral, painless, from raised ICP.", "Painless altitudinal loss in an older disc at risk."]}'),
  ('5662373a-1q','{"options": ["Associated with sclerosis", "Bilateral and painless", "Unilateral with early loss", "Painful, with an RAPD"], "correct": 1, "decode": "Papilledema is raised-ICP disc swelling: BILATERAL and painless, with preserved acuity early. Optic neuritis is unilateral, painful, with early acuity loss and an RAPD.", "ow": ["Optic neuritis links to MS, not papilledema.", "Correct. Raised ICP swells both discs painlessly.", "That describes optic neuritis.", "Also optic neuritis, not papilledema."]}'),
  ('e694aa53-2a','{"options": ["Giant cell arteritis", "Optic neuritis", "Papilledema", "NAION"], "correct": 0, "decode": "Elderly + jaw claudication + very high ESR + a chalky-white swollen disc is arteritic AION from giant cell arteritis. Systemic symptoms and ESR separate it from the non-arteritic type.", "ow": ["Correct. Jaw claudication, high ESR, pallid disc swelling, an emergency.", "Young patient, painful movement, no jaw claudication.", "Bilateral, from raised ICP.", "Non-arteritic, normal ESR, no jaw claudication."]}'),
  ('7720cc7f-2d','{"options": ["Optic neuritis", "Arteritic AION", "CRAO", "Non-arteritic AION"], "correct": 3, "decode": "Painless loss noticed on waking + altitudinal field defect + a small crowded ''disc at risk'' with NORMAL ESR is NON-arteritic AION. The arteritic type has systemic signs and high ESR.", "ow": ["Painful, in younger patients.", "Has jaw claudication and a high ESR.", "Whole-field loss with a pale retina, not altitudinal.", "Correct. Painless altitudinal loss with a crowded disc at risk."]}'),
  ('a2a3ac32-1p','{"options": ["Sarcoidosis", "Sympathetic ophthalmia", "Vogt-Koyanagi-Harada", "Behcet''s"], "correct": 2, "decode": "Panuveitis PLUS skin and hair signs (vitiligo, poliosis, alopecia) and meningismus is VKH, an autoimmune attack on melanocytes. Sarcoid and Behcet''s lack the poliosis-vitiligo cluster.", "ow": ["Granulomatous uveitis, but not the vitiligo and poliosis cluster.", "Follows trauma to the other eye; trauma is required.", "Correct. Panuveitis with vitiligo, poliosis, alopecia, and meningismus.", "Hypopyon uveitis with oral and genital ulcers, not poliosis."]}'),
  ('37ba17da-31','{"options": ["Exciting eye", "Sympathizing eye", "Amblyopic eye", "Dominant eye"], "correct": 0, "decode": "In sympathetic ophthalmia the INJURED eye that triggers the reaction is the ''exciting'' eye; the fellow eye that becomes inflamed is the ''sympathizing'' eye. The stem asks for the injured one.", "ow": ["Correct. The injured, triggering eye is the exciting eye.", "That is the uninjured fellow eye that becomes inflamed.", "An unrelated concept.", "An unrelated concept."]}'),
  ('3ed743f8-1v','{"options": ["Scattered macular drusen", "Bone spicule pigmentation", "Dilated, tortuous vessels", "A macular cherry-red spot"], "correct": 2, "decode": "''Plus disease'' in retinopathy of prematurity names active disease: dilated, tortuous posterior vessels. Drusen, bone spicules, and cherry-red spots belong to other diseases.", "ow": ["An age-related sign, not ROP.", "That is retinitis pigmentosa.", "Correct. Plus disease is dilated, tortuous vessels signaling activity.", "That is CRAO or a storage disease."]}'),
  ('cc23c40c-1g','{"options": ["At an arteriovenous crossing", "At the optic disc margin", "At the ora serrata", "Within the fovea itself"], "correct": 0, "decode": "Branch retinal vein occlusions happen where a stiff artery crosses and compresses the vein at an arteriovenous crossing, since they share a sheath. Not the disc, ora, or fovea.", "ow": ["Correct. The artery compresses the vein where they cross.", "That is where CENTRAL vein occlusion occurs.", "The peripheral retinal edge, not a BRVO site.", "The fovea is avascular; no vein to occlude."]}'),
  ('c14f4661-21','{"options": ["Atrophic round hole", "Horseshoe tear", "Drusen", "Lattice without holes"], "correct": 1, "decode": "Among breaks, a horseshoe (flap) tear carries the highest detachment risk because vitreous still pulls on the flap. Atrophic holes and lattice without holes are lower risk.", "ow": ["Lower risk, often stable.", "Correct. Ongoing vitreous traction on the flap gives the highest risk.", "A deposit, not a retinal break.", "Lower risk unless a hole forms."]}'),
  ('120de044-29','{"options": ["ROP", "Retinoblastoma", "Coats disease", "Ocular toxocariasis"], "correct": 3, "decode": "Child + leukocoria + a peripheral granuloma from dog/cat ROUNDWORM is ocular toxocariasis. The roundworm clue rules out the non-parasitic causes of a white pupil.", "ow": ["A premature-infant vascular disease, no roundworm.", "A malignant white-pupil cause, but not roundworm-related.", "Retinal telangiectasia with exudate, not a parasite.", "Correct. Roundworm (Toxocara) granuloma causing leukocoria."]}'),
  ('e69c8181-1m','{"options": ["KWB rule", "4-2-1 rule", "Roper-Hall rule", "ISNT rule"], "correct": 3, "decode": "Glaucomatous cupping thins the disc rim, breaking the ISNT rule (normal rim thickest Inferior > Superior > Nasal > Temporal). KWB grades hypertension; 4-2-1 grades diabetes; Roper-Hall grades burns.", "ow": ["A hypertensive retinopathy grading, not a disc rule.", "A diabetic retinopathy severity rule.", "A chemical-burn severity scale.", "Correct. Glaucoma violates the ISNT rim-thickness rule."]}'),
  ('d1c3a8a9-36','{"options": ["Drusen", "Roth spot", "Cotton-wool spot", "Weiss ring"], "correct": 3, "decode": "A single large floater after acute posterior vitreous detachment is a Weiss ring, the peripapillary vitreous condensation torn free of the disc. Drusen, Roth, and cotton-wool are retinal, not floaters.", "ow": ["A sub-RPE deposit, not a floater.", "A white-centered hemorrhage, not a PVD floater.", "An ischemic NFL infarct, not a floater.", "Correct. The Weiss ring is the peripapillary vitreous ring seen after PVD."]}'),
  ('eea8efb5-29','{"options": ["Early open-angle glaucoma", "Retrobulbar optic neuritis", "A nuclear cataract", "Choroidal neovascularization"], "correct": 3, "decode": "Metamorphopsia (wavy lines) on the Amsler grid signals a MACULAR problem, classically choroidal neovascularization in wet ARMD. Glaucoma, optic neuritis, and cataract do not distort central lines this way.", "ow": ["Affects peripheral field first, not central distortion.", "Causes central scotoma and dyschromatopsia, not wavy lines.", "Blurs and shifts refraction, but does not distort lines.", "Correct. Macular neovascularization distorts straight lines early."]}'),
  ('757e3d12-1t','{"options": ["Instill antibiotic ointment", "Take a full history first", "Begin copious irrigation immediately", "Pad the eye and refer"], "correct": 2, "decode": "For any chemical splash, irrigation comes FIRST, before history, drops, or referral. Time on the ocular surface is the enemy, so ''irrigate immediately'' beats every other step.", "ow": ["Delays irrigation; wrong first move.", "History waits; the eye must be irrigated now.", "Correct. Immediate copious irrigation is always the first step in a chemical burn.", "Padding traps the chemical and delays irrigation."]}'),
  ('719f57f5-17','{"options": ["Less dangerous", "More dangerous, penetrating deeply", "Limited to the conjunctiva", "Identical"], "correct": 1, "decode": "Alkali burns are MORE dangerous than acid because they saponify membranes and penetrate deeply, while acid coagulates protein and limits its own spread. ''Deep penetration'' is the alkali tell.", "ow": ["Opposite; alkali is more dangerous.", "Correct. Alkali penetrates deeply via liquefactive necrosis.", "It penetrates well beyond the conjunctiva.", "Acid and alkali differ; alkali is worse."]}'),
  ('41c4ddb8-1p','{"options": ["7.0–7.4", "8.5", "Any time after 1 minute", "5.0"], "correct": 0, "decode": "Irrigate a chemical burn until the tear-film pH normalizes to about 7.0 to 7.4. A fixed time or an off-neutral pH target is wrong; you titrate to a neutral pH.", "ow": ["Correct. Irrigate until pH returns to a neutral 7.0 to 7.4.", "Still alkaline; keep irrigating.", "Time is not the endpoint; pH is.", "Acidic; keep irrigating to neutral."]}'),
  ('bee3c049-1n','{"options": ["IOP", "The degree of limbal ischemia", "Corneal diameter", "Eyelid involvement"], "correct": 1, "decode": "In the Roper-Hall grading, prognosis hinges on LIMBAL ISCHEMIA, because limbal stem cells regenerate the cornea. More limbal blanching means worse prognosis.", "ow": ["Not the main prognostic factor in burns.", "Correct. Limbal stem-cell ischemia drives the prognosis.", "Not a Roper-Hall prognostic factor.", "Not the key prognostic determinant."]}'),
  ('fa7129e9-2d','{"options": ["Lowering IOP, then iridotomy", "Pressure patching the eye", "Topical steroids alone", "Broad-spectrum antibiotics"], "correct": 0, "decode": "Hard painful eye + mid-dilated fixed pupil + cloudy cornea is acute angle closure: lower the IOP medically first, then definitively open the block with a laser iridotomy.", "ow": ["Correct. Lower IOP first, then iridotomy to relieve the block.", "Patching does nothing for a pressure spike.", "Steroids alone miss the mechanical block.", "Antibiotics treat infection, not angle closure."]}'),
  ('53435467-1r','{"options": ["No window", "1 week", "24 hours", "4–6 hours"], "correct": 3, "decode": "CRAO is retinal stroke; the salvage window is only about 4 to 6 hours before irreversible infarction. Longer windows are too optimistic.", "ow": ["There is a short window; act fast.", "Far too long; the retina infarcts within hours.", "Beyond the realistic salvage window.", "Correct. Roughly 4 to 6 hours before irreversible retinal damage."]}'),
  ('d2aabb04-1w','{"options": ["Start high-dose corticosteroids immediately", "Give anti-VEGF", "Wait for temporal artery biopsy before treating", "Observe"], "correct": 0, "decode": "Suspected giant cell arteritis with vision loss is a ''treat first, biopsy later'' emergency: start high-dose steroids immediately to protect the other eye. Waiting for biopsy risks blindness.", "ow": ["Correct. High-dose steroids at once; do not wait for biopsy.", "Anti-VEGF has no role in GCA.", "Waiting risks the fellow eye; treat now.", "Observation risks bilateral blindness."]}'),
  ('2c973336-15','{"options": ["Pressed to measure IOP", "Shielded and referred, NPO", "Irrigated forcefully", "Firmly pressure patched"], "correct": 1, "decode": "A suspected ruptured globe must be SHIELDED (not pressed or patched), the patient kept NPO for surgery, and referred. Any pressure or irrigation could extrude intraocular contents.", "ow": ["Pressing can extrude ocular contents; never do it.", "Correct. Shield, keep NPO, and refer for surgical repair.", "Forceful irrigation can worsen the rupture.", "Pressure patching risks extruding contents."]}'),
  ('a455dd0a-2e','{"options": ["CT", "MRI", "Plain X-ray", "Ultrasound"], "correct": 1, "decode": "MRI is CONTRAINDICATED with a ferrous intraocular foreign body because the magnet can move the metal and damage the eye. CT, X-ray, and ultrasound are safer for localization.", "ow": ["Safe and preferred for a metallic foreign body.", "Correct. The magnet can move ferrous metal; MRI is contraindicated.", "Safe for screening a metallic foreign body.", "Safe, non-magnetic imaging."]}'),
  ('2300687d-1o','{"options": ["Siderosis", "Chalcosis", "Argyrosis", "Chrysiasis"], "correct": 0, "decode": "An IRON intraocular foreign body causes siderosis (iron toxicity). Copper gives chalcosis, silver argyrosis, gold chrysiasis. Match the metal to the -osis.", "ow": ["Correct. Iron toxicity in the eye is siderosis.", "That is copper toxicity.", "That is silver deposition.", "That is gold deposition."]}'),
  ('5c2fbdb0-1x','{"options": ["Allergic reaction", "Endophthalmitis", "GPC", "Dry eye"], "correct": 1, "decode": "Hypopyon with falling vision a few days AFTER cataract surgery is postoperative endophthalmitis until proven otherwise, an emergency. Allergy, GPC, and dry eye do not cause hypopyon.", "ow": ["Allergy does not produce a hypopyon.", "Correct. Post-op hypopyon with vision loss is endophthalmitis until proven otherwise.", "A papillary contact-lens reaction, not intraocular pus.", "A surface disorder, no hypopyon."]}'),
  ('ec5642a3-1p','{"options": ["Marked redness of the eyelid", "Proptosis and restricted gaze", "Fever with general malaise", "Swelling of the entire eyelid"], "correct": 1, "decode": "The line between orbital and preseptal cellulitis is behind the septum: proptosis, painful/restricted eye movement, and optic-nerve signs mean ORBITAL. Lid redness and fever occur in both.", "ow": ["Lid redness occurs in both types.", "Correct. Proptosis and restricted gaze signal orbital (post-septal) spread.", "Fever occurs in both.", "Lid swelling occurs in both."]}'),
  ('f9e46705-1n','{"options": ["A macular cherry-red spot", "A layered hypopyon", "Pulsating axial proptosis", "Numbness and vertical diplopia"], "correct": 3, "decode": "An orbital FLOOR blow-out traps the inferior rectus (vertical diplopia) and bruises the infraorbital nerve (cheek numbness). That numbness-plus-vertical-diplopia pair is the tell.", "ow": ["That is CRAO, not a fracture.", "That is uveitis, not a fracture.", "That is a carotid-cavernous fistula.", "Correct. Infraorbital numbness with vertical diplopia from a floor fracture."]}'),
  ('b5f60726-28','{"options": ["Bend forward often", "Apply heat", "Blow the nose to clear pressure", "Avoid blowing the nose"], "correct": 3, "decode": "After an orbital floor fracture, tell the patient NOT to blow the nose: nose-blowing forces sinus air into the orbit (orbital emphysema). Anything that raises sinus pressure is wrong.", "ow": ["Bending does not protect the orbit and may raise pressure.", "Heat does not prevent orbital emphysema.", "This is exactly what to avoid; it forces air into the orbit.", "Correct. Avoid nose-blowing to prevent orbital emphysema."]}'),
  ('add5ade1-21','{"options": ["Days 3–5", "Day 14", "Day 30", "Days 1–2"], "correct": 0, "decode": "Traumatic hyphema rebleeds most on DAYS 3 to 5, as the initial clot retracts and lyses. Day 1 to 2 is the fresh bleed; days 14 and 30 are past the risk window.", "ow": ["Correct. Clot lysis makes days 3 to 5 the peak rebleed risk.", "Past the high-risk window.", "Well past the rebleed window.", "That is the initial bleed, not the rebleed peak."]}'),
  ('3db641e7-2b','{"options": ["Shaken baby syndrome", "ROP", "Birth trauma only", "Congenital glaucoma"], "correct": 0, "decode": "Infant + bilateral retinal hemorrhages + subdural hemorrhage is shaken baby syndrome (abusive head trauma) until proven otherwise. ROP, birth trauma, and congenital glaucoma do not give this combination.", "ow": ["Correct. Retinal plus subdural hemorrhage in an infant signals shaken baby syndrome.", "A vascular disease of prematurity, not this hemorrhage pattern.", "Birth trauma alone does not give subdural plus diffuse retinal hemorrhage.", "Causes an enlarged cloudy eye, not hemorrhages."]}'),
  ('dc43dac2-34','{"options": ["Pinguecula", "Dry eye", "Microbial keratitis", "Allergic conjunctivitis"], "correct": 2, "decode": "Contact-lens wearer + painful white corneal infiltrate that STAINS is microbial keratitis until proven otherwise, an emergency (think Pseudomonas, Acanthamoeba). Benign surface conditions do not infiltrate and stain.", "ow": ["A painless surface deposit, not an infiltrate.", "Does not produce a staining corneal infiltrate.", "Correct. In a lens wearer, a staining infiltrate is microbial keratitis until proven otherwise.", "Itchy and papillary, not an ulcerating infiltrate."]}'),
  ('e2bcbc63-1o','{"options": ["Requires urgent surgery", "Causes secondary glaucoma", "Causes permanent scarring", "Heals in 24–48 hours"], "correct": 3, "decode": "UV photokeratitis (welder''s flash, snow blindness) is a superficial epithelial burn that is very painful but self-limited, healing in about 24 to 48 hours. It does not scar, cause glaucoma, or need surgery.", "ow": ["No surgery; it is superficial and self-limited.", "It does not raise pressure.", "The epithelium heals without scarring.", "Correct. Painful but self-limited, healing in 24 to 48 hours."]}'),
  ('74950299-1i','{"options": ["All acids equally", "Boric and carbonic", "Hydrofluoric acid", "Acetic and citric"], "correct": 2, "decode": "Most acids coagulate and self-limit, but HYDROFLUORIC acid behaves like an alkali, penetrating deeply. It is the acid exception to remember.", "ow": ["Acids differ; most self-limit while HF penetrates.", "These are weak and do not penetrate deeply.", "Correct. Hydrofluoric acid penetrates deeply, alkali-like.", "Weak organic acids that self-limit."]}'),
  ('22f95cb2-2b','{"options": ["Weiss ring", "Vossius ring", "Fleischer ring", "Kayser-Fleischer ring"], "correct": 1, "decode": "A pigment ring on the ANTERIOR LENS after blunt trauma, imprinted by the iris pupillary margin, is a Vossius ring. A Weiss ring is vitreous; Fleischer and K-F rings are corneal.", "ow": ["That is a vitreous ring seen after PVD.", "Correct. Iris pigment imprinted on the anterior lens after blunt trauma.", "An iron ring in keratoconus, on the cornea.", "A corneal copper ring of Wilson''s disease."]}'),
  ('268b7e2c-27','{"options": ["Retinal detachment", "Commotio retinae", "CRAO", "Choroidal rupture"], "correct": 1, "decode": "Gray retinal opacification after blunt trauma that clears in weeks is commotio retinae (retinal concussion, Berlin''s edema). CRAO and detachment do not self-resolve; choroidal rupture leaves a scar.", "ow": ["Does not spontaneously resolve like commotio.", "Correct. Commotio retinae is transient traumatic retinal whitening.", "A pale retina that does not self-resolve.", "Leaves a permanent crescentic scar."]}'),
  ('49b729ed-1f','{"options": ["Buphthalmos", "Exophthalmos", "Megalocornea", "Staphyloma"], "correct": 0, "decode": "''Abnormally enlarged GLOBE in an infant'' is buphthalmos (ox-eye) from congenital glaucoma. Exophthalmos is a forward-pushed eye; megalocornea is only a big cornea; staphyloma is a bulging thin wall.", "ow": ["Correct. Buphthalmos is the enlarged infant globe of congenital glaucoma.", "Forward protrusion of a normal-sized eye, not true enlargement.", "Only the cornea is large, not the whole globe.", "A localized bulge of thinned sclera or cornea, not global enlargement."]}'),
  ('cc8496b1-1m','{"options": ["Rhabdomyosarcoma", "Optic nerve glioma", "Neuroblastoma", "Retinoblastoma"], "correct": 0, "decode": "Child + PRIMARY orbital malignancy is rhabdomyosarcoma. Glioma is benign-ish and slow, neuroblastoma is metastatic to the orbit, retinoblastoma is intraocular.", "ow": ["Correct. The most common primary orbital malignancy of childhood.", "Optic nerve glioma is low-grade, not the commonest malignancy.", "A metastasis to the orbit, not a primary orbital tumor.", "Intraocular, not a primary orbital tumor."]}'),
  ('824f5c86-1z','{"options": ["Myasthenia gravis", "CN3 palsy", "Horner''s syndrome", "Aponeurotic dehiscence"], "correct": 0, "decode": "Variable, fatiguable ptosis that improves with Tensilon (edrophonium) is myasthenia gravis. A structural ptosis would be fixed and Tensilon-negative.", "ow": ["Correct. Fatiguable ptosis improving with edrophonium is myasthenia.", "Fixed ptosis, often down-and-out, no Tensilon response.", "Mild fixed ptosis with miosis, not fatiguable.", "A stretched-tendon ptosis, steady and Tensilon-negative."]}'),
  ('9f756e42-1h','{"options": ["Myogenic", "Aponeurotic", "Mechanical", "Neurogenic"], "correct": 1, "decode": "''Most common acquired adult ptosis'' is aponeurotic (involutional) levator stretching. Myogenic, mechanical, and neurogenic causes exist but are far less common.", "ow": ["From muscle disease; uncommon.", "Correct. Age-related levator aponeurosis stretching is the commonest.", "From a lid weight or scar; not the usual cause.", "From a nerve palsy; less common than involutional."]}'),
  ('de174625-10','{"options": ["Molluscum lesion", "Hordeolum", "Chalazion", "Preseptal cellulitis"], "correct": 2, "decode": "A firm, non-tender lid granuloma is a chalazion (chronic meibomian lipogranuloma). The hordeolum is acute and tender; molluscum and cellulitis are different lesions.", "ow": ["A viral umbilicated papule, not a granuloma.", "Acute and tender, unlike this firm painless nodule.", "Correct. A chronic firm painless meibomian granuloma.", "A spreading lid infection, not a discrete nodule."]}'),
  ('3c87e136-17','{"options": ["CN3", "CN6", "CN7", "CN5"], "correct": 2, "decode": "Paralytic ectropion follows a facial (CN VII) palsy, which weakens orbicularis and lets the lid fall outward. CN3, 5, and 6 do not control lid closure this way.", "ow": ["Controls most eye movements and lid elevation, not closure.", "Moves the lateral rectus; no lid-closure role.", "Correct. CN VII palsy weakens orbicularis, causing paralytic ectropion.", "Sensory to the face; not the lid-closure motor nerve."]}'),
  ('58a09603-10','{"options": ["Squamous cell carcinoma", "Sebaceous gland carcinoma", "Basal cell carcinoma", "Malignant melanoma"], "correct": 2, "decode": "The most common eyelid malignancy is basal cell carcinoma (lower lid, sun-exposed). The others are real but far rarer lid cancers.", "ow": ["Less common than basal cell on the lid.", "Aggressive but uncommon; masquerades as chalazion.", "Correct. Basal cell carcinoma is the commonest lid malignancy.", "Rare on the eyelid."]}'),
  ('303628ab-1k','{"options": ["Basal cell carcinoma", "Pleomorphic adenoma", "Lymphoma", "Adenoid cystic carcinoma"], "correct": 3, "decode": "Pair the lacrimal gland tumors: pleomorphic adenoma is the commonest BENIGN, adenoid cystic carcinoma the commonest MALIGNANT (painful, perineural). The stem asks malignant.", "ow": ["A skin cancer, not a lacrimal gland malignancy.", "This is the benign one.", "Occurs there but is not the classic most-common-malignant answer.", "Correct. Adenoid cystic carcinoma, the commonest malignant lacrimal tumor."]}'),
  ('e6d371c0-1r','{"options": ["Dacryocystorhinostomy", "Punctal plugging", "Lateral tarsorrhaphy", "Probing and irrigation"], "correct": 0, "decode": "Chronic dacryocystitis is a blocked infected sac; the definitive surgery bypasses the block with a dacryocystorhinostomy. Plugs, tarsorrhaphy, and probing do not cure the adult block.", "ow": ["Correct. DCR bypasses the blocked duct, the definitive cure.", "Plugs retain tears; they do not treat a blocked sac.", "A lid-closure procedure, unrelated to the tear sac.", "Used in congenital, not adult chronic, obstruction."]}'),
  ('d4357513-1f','{"options": ["Pterygium", "Pinguecula", "Limbal dermoid", "Pannus"], "correct": 0, "decode": "The growth that invades and destroys Bowman''s layer is the pterygium as it crosses the limbus. Pinguecula stays off the cornea; dermoid is congenital; pannus is superficial vascular.", "ow": ["Correct. Pterygium crosses the limbus and destroys Bowman''s layer.", "Stays on the conjunctiva; does not cross the limbus.", "A congenital limbal mass, not an invasive growth.", "Superficial vascular pannus, not Bowman''s destruction."]}'),
  ('c44df5e0-1g','{"options": ["Onchocerciasis", "Gonococcal ophthalmia", "Herpes simplex keratitis", "Trachoma"], "correct": 3, "decode": "The world''s leading INFECTIOUS cause of blindness is trachoma (Chlamydia). Onchocerciasis is second; gonococcal and herpes are not the global leader.", "ow": ["River blindness, the second infectious cause.", "A cause of neonatal blindness, not the global leader.", "A leading cause in developed countries, not worldwide.", "Correct. Trachoma is the top infectious cause of blindness."]}'),
  ('e3b8ded0-18','{"options": ["Vogt''s striae", "Munson''s sign", "A Fleischer ring", "A Kayser-Fleischer ring"], "correct": 2, "decode": "Earliest keratoconus sign is the Fleischer ring (iron at the cone base). Vogt''s striae and Munson''s sign come later; the Kayser-Fleischer ring is a copper ring of Wilson''s, a distractor.", "ow": ["Stress lines appearing after the Fleischer ring.", "A late advanced sign on downgaze.", "Correct. The iron Fleischer ring is the earliest sign.", "A copper ring of Wilson''s disease, not keratoconus."]}'),
  ('15ec95bb-1m','{"options": ["Krukenberg spindle", "Kayser-Fleischer ring", "Hudson-Stahli line", "Fleischer ring"], "correct": 1, "decode": "A COPPER ring in Descemet''s is the Kayser-Fleischer ring of Wilson''s disease. Krukenberg is a pigment spindle, Hudson-Stahli is an iron line, Fleischer is an iron ring in keratoconus.", "ow": ["A vertical pigment spindle, not a copper ring.", "Correct. The copper ring in Descemet''s is the Kayser-Fleischer ring.", "A horizontal iron line, not copper.", "An iron ring in keratoconus, not copper."]}'),
  ('32d5f2f5-2i','{"options": ["Topical steroids", "Topical antivirals", "Oral acyclovir", "Lubricants"], "correct": 0, "decode": "In dendritic (epithelial) HSV keratitis, topical steroids alone are dangerous: unopposed steroid boosts viral replication and can turn a dendrite into a geographic ulcer. Antivirals and lubricants are safe.", "ow": ["Correct. Steroids alone worsen epithelial HSV, risking a geographic ulcer.", "The correct treatment for epithelial HSV.", "A safe systemic antiviral option.", "Harmless supportive care."]}'),
  ('3adc8808-1q','{"options": ["Downward and inward", "Upward and outward", "Into the anterior chamber", "Directly posteriorly"], "correct": 1, "decode": "Marfan dislocates the lens UP and OUT (superotemporal); homocystinuria goes DOWN and IN. The stem is Marfan.", "ow": ["Down-and-in is homocystinuria, not Marfan.", "Correct. Marfan subluxates the lens up and out.", "Not the classic Marfan direction.", "Not the classic Marfan direction."]}'),
  ('35a4f20f-15','{"options": ["Nuclear sclerosis", "Posterior subcapsular", "Cortical", "Congenital lamellar"], "correct": 0, "decode": "''Second sight'' comes from NUCLEAR sclerosis: added lens power shifts the eye myopic, briefly letting a presbyope read without glasses. The other cataracts do not cause a myopic shift.", "ow": ["Correct. Nuclear sclerosis myopic shift gives second sight.", "Axial opacity causing glare, not a myopic shift.", "Spoke opacities, no second sight.", "A congenital layer opacity, unrelated."]}'),
  ('ccd67d1c-34','{"options": ["Phacolytic", "Phacoantigenic", "Pupillary block", "Phacomorphic"], "correct": 0, "decode": "A hypermature cataract leaking protein through an INTACT capsule that clogs the meshwork is phacoLYTIC glaucoma (open-angle). Phacomorphic is angle-closure from a swollen lens; pupillary block is different.", "ow": ["Correct. Leaked protein clogs the open-angle meshwork: phacolytic.", "An immune lens reaction, not the protein-clogging open-angle type.", "A closed-angle mechanism, not open-angle.", "Angle closure from a swollen lens, not protein leak."]}'),
  ('ad8808e3-23','{"options": ["Purely allergic", "Non-granulomatous", "Traumatic", "Granulomatous"], "correct": 3, "decode": "Mutton-fat keratic precipitates (large, greasy) mean GRANULOMATOUS uveitis. Fine KPs are non-granulomatous. ''Mutton-fat'' is the tell.", "ow": ["Allergy is not a keratic-precipitate uveitis.", "Non-granulomatous gives fine, not mutton-fat, KPs.", "Trauma is not defined by mutton-fat KPs.", "Correct. Mutton-fat KPs are the granulomatous signature."]}'),
  ('db17fc48-10','{"options": ["Hypertensive crisis", "CRAO", "CRVO", "Advanced PDR"], "correct": 2, "decode": "A ''blood-and-thunder'' fundus (diffuse hemorrhages, engorged tortuous veins) is CRVO. Arterial occlusion gives a pale retina; hypertensive crisis and PDR look different.", "ow": ["Gives a macular star and swelling, not blood-and-thunder.", "Pale retina, the opposite look.", "Correct. Diffuse hemorrhages with tortuous veins is CRVO.", "Neovascular fronds, not diffuse four-quadrant hemorrhage."]}'),
  ('5a02bf15-1g','{"options": ["Microaneurysm", "Cotton-wool spot", "Hard exudate", "Neovascularization"], "correct": 0, "decode": "The earliest visible diabetic sign is the microaneurysm. Cotton-wool spots, exudates, and neovascularization all come later.", "ow": ["Correct. The microaneurysm is the earliest visible sign.", "An ischemic infarct appearing later.", "Later lipid leakage.", "A late proliferative sign."]}'),
  ('1cc8b7c4-w','{"options": ["The stages of ROP", "Severe non-proliferative diabetic retinopathy", "Proliferative diabetic retinopathy", "Clinically significant macular edema"], "correct": 1, "decode": "The 4-2-1 rule defines SEVERE non-proliferative diabetic retinopathy (hemorrhages in 4 quadrants, beading in 2, or IRMA in 1). It is not ROP, PDR, or CSME.", "ow": ["ROP uses its own zone and stage system.", "Correct. 4-2-1 defines severe NPDR.", "Proliferative disease is defined by new vessels, not 4-2-1.", "Macular edema has separate criteria."]}'),
  ('5dc717e9-1n','{"options": ["Wet exudative AMD", "Myopic degeneration", "Central serous retinopathy", "Dry atrophic AMD"], "correct": 3, "decode": "Most-common AMD is the DRY atrophic (drusen) type, about 90%. Wet is less common but more severe; myopic and central serous are separate entities.", "ow": ["Less common though more sight-threatening.", "A different, non-age-related degeneration.", "A separate serous maculopathy.", "Correct. Dry atrophic AMD is the commonest form."]}'),
  ('7065b2ac-z','{"options": ["Intravitreal anti-VEGF", "AREDS2 supplements", "Photodynamic therapy", "Focal laser photocoagulation"], "correct": 0, "decode": "Wet AMD is VEGF-driven, so first-line is intravitreal anti-VEGF. AREDS2 slows dry disease; PDT and focal laser are older or adjunct options.", "ow": ["Correct. Intravitreal anti-VEGF is first-line for wet AMD.", "Slows dry AMD; not a treatment for active wet disease.", "An older adjunct, not first-line.", "Not first-line for choroidal neovascularization."]}'),
  ('29e5057c-1j','{"options": ["Histoplasmosis", "Toxoplasmosis", "Toxocariasis", "CMV retinitis"], "correct": 1, "decode": "''Headlight in the fog'' (focal active chorioretinitis glowing through haze beside an old scar) is toxoplasmosis. Histoplasmosis scars are punched-out; CMV is pizza-pie; toxocara is a granuloma.", "ow": ["Punched-out scars without vitritis, not headlight-in-fog.", "Correct. Toxoplasmosis gives the headlight-in-the-fog lesion.", "A leukocoric granuloma, not satellite reactivation.", "Pizza-pie hemorrhagic retinitis in AIDS."]}'),
  ('ae23bfce-1n','{"options": ["Giant cell arteritis", "Papilledema", "Optic neuritis", "Non-arteritic AION"], "correct": 0, "decode": "Jaw claudication + a chalky-white (pallid) swollen disc is arteritic AION from giant cell arteritis, an emergency. Papilledema, optic neuritis, and NAION lack jaw claudication.", "ow": ["Correct. Jaw claudication with pallid disc swelling is giant cell arteritis.", "Bilateral, from raised ICP, no jaw claudication.", "Young, painful movement, no jaw claudication.", "Non-arteritic, normal ESR, no jaw claudication."]}'),
  ('399b85b2-1y','{"options": ["Exudative", "Rhegmatogenous", "Serous", "Tractional"], "correct": 1, "decode": "A detachment WITH a full-thickness break is rhegmatogenous (''rhegma'' = break). Exudative, serous, and tractional detachments have no break.", "ow": ["Fluid leakage, no break.", "Correct. A full-thickness break defines rhegmatogenous detachment.", "Fluid under the retina, no break.", "Membrane traction, no break."]}'),
  ('fb06e13c-1b','{"options": ["Instill a cycloplegic", "Take a full history", "Irrigate immediately", "Measure visual acuity"], "correct": 2, "decode": "For a chemical burn the very first action is to irrigate. History, cycloplegic, and acuity all wait; nothing precedes flushing the surface.", "ow": ["Comfort measure that waits until after irrigation.", "History waits; irrigate first.", "Correct. Immediate irrigation is always the first step.", "Acuity is checked after irrigation begins."]}'),
  ('3edbeb61-1t','{"options": ["High-dose antibiotics", "Ocular massage and lowering IOP", "Urgent laser retinopexy", "Immediate anti-VEGF"], "correct": 1, "decode": "Initial CRAO management tries to dislodge the embolus and lower IOP: ocular massage plus IOP-lowering measures. Antibiotics, retinopexy, and anti-VEGF do not treat an arterial occlusion.", "ow": ["Infection is not the problem in CRAO.", "Correct. Ocular massage and IOP-lowering aim to move the embolus.", "Retinopexy treats breaks, not arterial occlusion.", "Anti-VEGF is for neovascular disease, not CRAO."]}'),
  ('1098207d-1y','{"options": ["Immediately, before biopsy", "After the ESR returns", "Only if vision is already lost", "Only after a positive biopsy"], "correct": 0, "decode": "In suspected giant cell arteritis, start steroids IMMEDIATELY, before biopsy, to save the fellow eye. Biopsy stays positive for days, so treatment never waits.", "ow": ["Correct. Treat at once; do not wait for biopsy.", "Do not wait; the ESR and biopsy can follow.", "Treat before vision is lost, not after.", "Biopsy can follow; treatment comes first."]}'),
  ('cccec875-1s','{"options": ["B-scan ultrasound only", "CT", "MRI", "No imaging is needed"], "correct": 1, "decode": "A ferrous intraocular foreign body is imaged with CT (or plain X-ray/ultrasound), never MRI, whose magnet can move the metal. CT localizes safely.", "ow": ["Ultrasound can help but CT is the standard localizer.", "Correct. CT safely localizes a metallic intraocular foreign body.", "Contraindicated; the magnet can move ferrous metal.", "Imaging is needed to localize the foreign body."]}'),
  ('453f36f2-1m','{"options": ["Toxic anterior segment syndrome", "Phacolytic glaucoma", "Sympathetic ophthalmia", "Endophthalmitis"], "correct": 3, "decode": "Hypopyon days after cataract surgery is endophthalmitis until proven otherwise. TASS is early and sterile; phacolytic and sympathetic ophthalmia are different scenarios.", "ow": ["TASS appears within hours and is sterile, not days later with worsening vision.", "A lens-protein glaucoma, not post-op infection.", "A bilateral post-trauma uveitis, not this.", "Correct. Post-op hypopyon with falling vision is endophthalmitis."]}'),
  ('48a32d49-y','{"options": ["Topical antibiotics only", "Oral antibiotics and review in a week", "Intravenous antibiotics and CT", "Immediate orbital decompression"], "correct": 2, "decode": "Orbital (post-septal) cellulitis needs IV antibiotics and CT imaging to look for abscess, not topical/oral outpatient care. It is an admission-level emergency.", "ow": ["Topical drops cannot treat deep orbital infection.", "Too slow and weak for orbital cellulitis.", "Correct. IV antibiotics plus CT imaging for orbital cellulitis.", "Decompression is reserved for specific complications, not first-line."]}'),
  ('5b7cbeab-1x','{"options": ["Blow the nose", "Sleep with the head raised", "Apply a cold compress", "Take oral analgesia"], "correct": 0, "decode": "After a blow-out fracture, warn the patient NOT to blow the nose: it forces sinus air into the orbit (orbital emphysema). The other measures are fine.", "ow": ["Correct. Avoid nose-blowing to prevent orbital emphysema.", "Head elevation is fine and helps swelling.", "A cold compress is acceptable.", "Analgesia is fine."]}'),
  ('bbb2845f-1i','{"options": ["An open globe", "Acute angle-closure", "Endophthalmitis", "Anterior uveitis"], "correct": 0, "decode": "A positive Seidel test (aqueous streaming through fluorescein) with a peaked/distorted pupil signals an OPEN globe. Angle closure, endophthalmitis, and uveitis do not leak aqueous.", "ow": ["Correct. Seidel-positive leak plus a peaked pupil means an open globe.", "No aqueous leak in angle closure.", "Pus in the chamber, but no Seidel leak.", "Inflammation without a wound leak."]}'),
  ('690fce94-21','{"options": ["Cortical spoke", "Posterior subcapsular", "Nuclear sclerotic", "Anterior stellate"], "correct": 1, "decode": "The most visually disabling age-related cataract is posterior subcapsular, because it sits on the visual axis and causes glare and near-vision loss early. Cortical, nuclear, and anterior types disable less for their size.", "ow": ["Peripheral spokes, less disabling early.", "Correct. Axial location makes PSC the most visually disabling.", "Central sclerosis, but less disabling than axial PSC.", "Uncommon and less disabling."]}'),
  ('37df0f01-11','{"options": ["Iron at the cone base", "Calcium in Bowman''s", "Iron in the epithelium", "Copper in Descemet''s membrane"], "correct": 3, "decode": "The Kayser-Fleischer ring is COPPER in Descemet''s membrane (Wilson''s disease). Iron rings/lines and calcium belong to other findings.", "ow": ["That is the iron Fleischer ring of keratoconus.", "That is band keratopathy.", "That describes iron lines, not the K-F ring.", "Correct. Copper in Descemet''s membrane is the K-F ring."]}'),
  ('6bde79eb-12','{"options": ["Lipid deposition at the fovea", "Infarcted foveal tissue", "Healthy choroid seen through thin retina", "Subretinal hemorrhage"], "correct": 2, "decode": "In CRAO the cherry-red spot is normal CHOROID showing through the thin fovea, while the surrounding retina is pale and swollen. It is not lipid, infarct color, or hemorrhage.", "ow": ["Not a lipid deposit.", "The fovea is thin, so you see through it, not infarcted red tissue.", "Correct. Healthy choroid shows through the thin fovea against a pale retina.", "Not subretinal blood."]}'),
  ('74320490-1j','{"options": ["Early severe vision loss", "An enlarged blind spot", "An early dense RAPD", "Early central scotoma"], "correct": 1, "decode": "Early papilledema preserves acuity and just enlarges the blind spot (from disc swelling). Early severe loss, RAPD, and central scotoma point to optic neuritis instead.", "ow": ["Acuity is preserved early in papilledema.", "Correct. Early papilledema mainly enlarges the blind spot.", "A dense RAPD suggests optic neuritis, not bilateral papilledema.", "Central scotoma is an optic neuritis feature."]}'),
  ('c10b3477-1e','{"options": ["Rhegmatogenous", "Tractional and exudative", "All types have a break", "Only exudative has none"], "correct": 1, "decode": "The detachments with NO break are tractional and exudative (serous). Only rhegmatogenous has a break, so it is the wrong choice here.", "ow": ["This one HAS a break.", "Correct. Tractional and exudative detachments have no retinal break.", "Not all types have a break.", "Tractional also lacks a break, so ''only exudative'' is wrong."]}'),
  ('91d921f4-1q','{"options": ["Is more often concentrated", "Binds corneal collagen tightly", "Coagulates surface protein", "Liquefies and keeps going"], "correct": 3, "decode": "Alkali is worse than acid because it causes LIQUEFACTIVE necrosis and keeps penetrating, while acid coagulates protein and self-limits. ''Liquefies and keeps going'' is the alkali mechanism.", "ow": ["Concentration is not the key difference.", "Acids, not alkalis, bind and coagulate collagen.", "That describes acid, not alkali.", "Correct. Alkali liquefies tissue and penetrates deeply."]}'),
  ('4230c42a-18','{"options": ["Widely dilated and reactive", "Mid-dilated and fixed", "Normal in size", "Small and constricted"], "correct": 1, "decode": "In acute angle closure the pupil is stuck MID-DILATED and fixed (unreactive). Widely dilated-reactive, normal, or pinpoint pupils do not fit.", "ow": ["It is fixed, not reactive.", "Correct. A mid-dilated fixed pupil is classic for acute angle closure.", "The pupil is abnormal, not normal.", "Miosis is not the angle-closure pattern."]}'),
  ('807d47fa-1p','{"options": ["Best treated after imaging", "Always managed by patching", "Treated before any history is taken", "Never sight-threatening"], "correct": 2, "decode": "A chemical burn is unique because treatment (irrigation) precedes even history-taking. Imaging, patching, and ''never sight-threatening'' are all wrong.", "ow": ["Irrigation cannot wait for imaging.", "Patching traps the chemical; wrong.", "Correct. Irrigate before taking any history.", "Chemical burns can blind; they are sight-threatening."]}'),
  ('b3414b8e-28','{"options": ["Xanthelasma", "Chalazion", "Basal cell carcinoma", "Hordeolum"], "correct": 3, "decode": "A painful, tender, red nodule at the lid margin over days is a hordeolum (stye), the acute infected gland. Chalazion is chronic and painless; xanthelasma and BCC are not acute tender nodules.", "ow": ["A painless yellow lipid plaque.", "Chronic and painless, the opposite of this.", "A slow-growing tumor, not an acute tender nodule.", "Correct. Acute tender red lid-margin nodule is a hordeolum."]}'),
  ('c33e6075-2m','{"options": ["Distichiasis", "Ectropion", "Lagophthalmos only", "Entropion"], "correct": 1, "decode": "Bell''s palsy (CN VII) weakens orbicularis, so the lower lid falls away from the globe: paralytic ectropion. Lagophthalmos is incomplete closure, a related but distinct sign; entropion is inward.", "ow": ["An extra lash row, unrelated to CN VII.", "Correct. CN VII weakness everts the lid: paralytic ectropion.", "Incomplete closure is related but not the lid-eversion asked here.", "Inward turning, the opposite of eversion."]}'),
  ('653fcd86-3c','{"options": ["Partial obstruction above the sac", "Complete block below the sac", "Lacrimal gland tumor", "A fully patent system"], "correct": 0, "decode": "Dye not reaching the nose spontaneously (failed dye disappearance) but recovered on irrigation means the system is anatomically patent yet functionally slow: a partial/high obstruction above the sac. A complete block would stop irrigation too.", "ow": ["Correct. Patent to irrigation but poor spontaneous drainage means a partial obstruction above the sac.", "A complete block would stop the saline irrigation as well.", "A gland tumor affects tear production, not this drainage pattern.", "A fully patent system would pass dye spontaneously to the nose."]}'),
  ('e33ab7bc-2r','{"options": ["Canalicular stenosis", "Allergic reaction", "Squamous cell carcinoma of the sac", "Pneumococcal infection"], "correct": 2, "decode": "BLOOD regurgitating on pressure over the sac is a red flag for a lacrimal sac tumor (squamous cell carcinoma). Ordinary infection refluxes mucopus, not blood.", "ow": ["Blocks tears but does not cause bloody reflux.", "Not a cause of blood from the sac.", "Correct. Bloody regurgitation suggests sac carcinoma.", "Infection gives mucopus, not blood."]}'),
  ('ee4c9de4-33','{"options": ["Subconjunctival hemorrhage", "Allergic conjunctivitis", "Pinguecula", "A deep process"], "correct": 3, "decode": "A violet ciliary ring that does NOT blanch with epinephrine signals a deep intraocular process (iritis, keratitis, glaucoma). Superficial conjunctival causes would blanch.", "ow": ["Flat blood, not a non-blanching vascular ring.", "Superficial and blanching.", "A superficial focal lesion that blanches.", "Correct. Non-blanching ciliary flush means a deep process."]}'),
  ('b079ad2e-21','{"options": ["Diabetes", "Gout", "Wilson''s disease", "Hemochromatosis"], "correct": 2, "decode": "A green-gold ring in Descemet''s (Kayser-Fleischer) means copper, meaning Wilson''s disease. Diabetes, gout, and hemochromatosis do not deposit corneal copper.", "ow": ["No corneal copper ring.", "A urate disease, not corneal copper.", "Correct. The copper K-F ring means Wilson''s disease.", "Iron overload, not the copper ring."]}'),
  ('b7fa0ecf-3e','{"options": ["Weill-Marchesani, spherophakia", "Homocystinuria, down", "Marfan syndrome, up", "Trauma, variable"], "correct": 2, "decode": "Tall, long-fingered, aortic aneurysm plus an UP-and-OUT lens dislocation is Marfan syndrome. Homocystinuria dislocates down; Weill-Marchesani gives small round lenses.", "ow": ["Weill-Marchesani gives a small spherical lens, and a short-limbed body.", "Homocystinuria dislocates down-and-in.", "Correct. Marfan habitus with a superotemporal (up-and-out) lens.", "The systemic Marfan features point to a syndrome, not random trauma."]}'),
  ('1b13fc10-3f','{"options": ["Iris bombe", "Rubeosis iridis", "Phacomorphic glaucoma", "Phacolytic glaucoma"], "correct": 3, "decode": "Hypermature cataract + leaked lens protein + macrophages clogging an OPEN angle with raised IOP is phacolytic glaucoma. Iris bombe and rubeosis are different mechanisms; phacomorphic is angle-closure.", "ow": ["A pupillary-block angle-closure mechanism, not protein clogging.", "Neovascular angle disease, not lens protein.", "Angle closure from a swollen lens, not open-angle protein clogging.", "Correct. Leaked protein and macrophages clog the open angle: phacolytic."]}'),
  ('88d87e01-2h','{"options": ["Viral", "Granulomatous", "Allergic", "Fuchs heterochromic"], "correct": 1, "decode": "Mutton-fat (large, greasy) keratic precipitates mean GRANULOMATOUS uveitis. Viral and Fuchs give fine stellate KPs; allergy is not a KP disease.", "ow": ["Viral uveitis gives fine or stellate KPs, not mutton-fat.", "Correct. Mutton-fat KPs are the granulomatous signature.", "Allergy is not a keratic-precipitate uveitis.", "Fuchs gives fine stellate KPs, not greasy mutton-fat."]}'),
  ('24cb50ed-3i','{"options": ["Optic neuritis; IV methylprednisolone", "Retinal detachment; urgent surgery", "CRVO; observe and monitor", "CRAO; ocular massage, lower IOP"], "correct": 3, "decode": "Pale retina + cherry-red fovea + sudden painless loss + RAPD is CRAO; act fast with ocular massage and IOP-lowering. The other diagnoses do not give a pale retina with a cherry spot.", "ow": ["Optic neuritis has a normal or swollen disc, not a pale retina with cherry spot.", "Detachment gives a curtain, not a pale retina.", "CRVO is hemorrhagic, not pale, and you would not just observe an arterial occlusion.", "Correct. CRAO; ocular massage and IOP-lowering to try to dislodge the embolus."]}'),
  ('d4b95ae9-33','{"options": ["Severe NPDR", "Mild NPDR", "Proliferative DR", "Moderate NPDR"], "correct": 0, "decode": "Hemorrhages in 4 quadrants OR beading in 2 OR IRMA in 1, with NO new vessels, is SEVERE NPDR by the 4-2-1 rule. New vessels would make it proliferative.", "ow": ["Correct. Four-quadrant hemorrhage plus beading in two meets the 4-2-1 severe-NPDR rule.", "Mild NPDR is just microaneurysms.", "Proliferative requires neovascularization, which is absent here.", "Moderate is between mild and the 4-2-1 threshold."]}'),
  ('d1b5e124-3u','{"options": ["Giant cell arteritis", "Diabetes", "Multiple sclerosis", "Hypertension"], "correct": 2, "decode": "Young woman + painful subacute vision loss + red desaturation + RAPD is optic neuritis, whose key systemic link is multiple sclerosis. GCA is elderly; diabetes and hypertension are not the association.", "ow": ["Elderly disease with jaw claudication, not a young woman with optic neuritis.", "Not the classic optic neuritis association.", "Correct. Optic neuritis in a young woman links to multiple sclerosis.", "Not the association for optic neuritis."]}'),
  ('6da2daf4-39','{"options": ["Observe and repeat ESR", "Anti-VEGF injection", "Start high-dose corticosteroids immediately", "Temporal artery biopsy, then treat"], "correct": 2, "decode": "Elderly + jaw claudication + scalp tenderness + ESR 80 + vision loss is giant cell arteritis; start high-dose steroids IMMEDIATELY to protect the other eye. Do not wait for biopsy.", "ow": ["Waiting risks the fellow eye; treat now.", "Anti-VEGF has no role in GCA.", "Correct. Start high-dose steroids at once for suspected giant cell arteritis.", "Biopsy can follow; treatment comes first."]}'),
  ('807ea285-2s','{"options": ["Retinitis pigmentosa", "Diabetic retinopathy", "Age-related macular degeneration", "CRVO"], "correct": 0, "decode": "Night blindness + bone-spicule pigment + waxy disc + extinguished rod ERG is retinitis pigmentosa. The flat ERG confirms rod photoreceptor failure.", "ow": ["Correct. Bone spicules, waxy disc, and a flat rod ERG define retinitis pigmentosa.", "Microaneurysms and exudates, normal ERG pattern.", "Macular drusen, not peripheral bone spicules.", "A hemorrhagic vascular fundus, not pigmentary."]}'),
  ('ccbdb35e-3z','{"options": ["Scleritis; oral NSAID therapy", "Acute angle-closure; laser iridotomy", "Conjunctivitis; topical antibiotics", "Anterior uveitis; topical steroid"], "correct": 1, "decode": "Painful red eye + cloudy cornea + mid-dilated fixed pupil + rock-hard globe + nausea is acute angle closure; the definitive fix is a laser iridotomy after lowering IOP. NSAIDs, antibiotics, and steroids miss the block.", "ow": ["Scleritis is deep boring pain without a rock-hard pressure spike.", "Correct. Acute angle closure; iridotomy is the definitive treatment.", "Conjunctivitis has no cloudy cornea or hard globe.", "Uveitis does not give a rock-hard globe and mid-dilated fixed pupil."]}'),
  ('3a7611d6-2g','{"options": ["B-scan ultrasound", "CT scan", "Slit-lamp exam", "MRI"], "correct": 3, "decode": "With an iron intraocular foreign body, MRI is contraindicated: the magnet can move the metal. Ultrasound, CT, and slit-lamp exam are safe.", "ow": ["Safe imaging for localization.", "Safe and preferred for a metallic foreign body.", "Safe clinical exam.", "Correct. MRI is contraindicated; the magnet can move ferrous metal."]}'),
  ('29f35b60-2m','{"options": ["New chemical injury", "Spontaneous resolution", "Rebleed", "Optic neuritis"], "correct": 2, "decode": "Sudden worsening of a hyphema around day 3 is a rebleed, as the clot lyses and retracts (peak risk days 3 to 5). It is not new injury, resolution, or optic neuritis.", "ow": ["No new chemical exposure is implied.", "Worsening is the opposite of resolution.", "Correct. Day 3 to 5 is the classic hyphema rebleed window.", "Not the cause of sudden hyphema worsening."]}'),
  ('cbca91cf-3v','{"options": ["Blow-out floor fracture; CT coronal", "Retinal detachment; fundus photo", "Hyphema; ultrasound", "Open globe; MRI"], "correct": 0, "decode": "Cheek/upper-lip numbness + upgaze diplopia + orbital emphysema is a blow-out FLOOR fracture; image with coronal CT. The other pairings mismatch injury and imaging.", "ow": ["Correct. Blow-out floor fracture, best shown on coronal CT.", "No detachment features here; a fundus photo would miss the fracture.", "Ultrasound is not the imaging for a bony orbital fracture.", "MRI is not first-line, and this is not an open globe."]}'),
  ('a2ff90bd-2h','{"options": ["Ptosis", "Exophthalmos", "Ectropion", "Entropion"], "correct": 1, "decode": "''Anterior globe protrusion, Graves as the #1 cause'' is exophthalmos (proptosis). Ptosis is a droop; ectropion/entropion are lid-turning terms.", "ow": ["A drooping lid, not globe protrusion.", "Correct. Exophthalmos is forward globe protrusion, commonly from Graves.", "Outward lid turning, not protrusion.", "Inward lid turning, not protrusion."]}'),
  ('494a1a6a-1x','{"options": ["Ptosis", "Entropion", "Exophthalmos", "Ectropion"], "correct": 1, "decode": "''Lid margin turns INWARD, lashes abrade the cornea'' is entropion (en = in). Ectropion is out; ptosis and exophthalmos are unrelated.", "ow": ["A droop, not an inward turn.", "Correct. Entropion is inward lid turning with lash abrasion.", "Globe protrusion, not lid turning.", "Outward turning, the opposite."]}'),
  ('d7ae867b-22','{"options": ["Ptosis", "Entropion", "Exophthalmos", "Ectropion"], "correct": 3, "decode": "''Lid margin turns OUTWARD with exposure and epiphora'' is ectropion (ec = out). Entropion is in; the others are unrelated.", "ow": ["A droop, not lid eversion.", "Inward turning, the opposite.", "Globe protrusion, not lid turning.", "Correct. Ectropion is outward lid turning causing exposure and tearing."]}'),
  ('0cdf88eb-2c','{"options": ["Ptosis", "Entropion", "Lagophthalmos", "Exophthalmos"], "correct": 2, "decode": "''Incomplete closure, hare''s eye, exposure keratopathy'' is lagophthalmos. Ptosis is a droop; entropion is inturning; exophthalmos is protrusion.", "ow": ["A droop, not a closure failure.", "Inward turning, not a closure failure.", "Correct. Lagophthalmos is incomplete lid closure (hare''s eye).", "Globe protrusion, not closure failure."]}'),
  ('9d7713dc-1l','{"options": ["Exophthalmos", "Hordeolum", "Entropion", "Ptosis"], "correct": 1, "decode": "''Acute tender lid-margin abscess (stye)'' is a hordeolum. The others are not acute infected nodules.", "ow": ["Globe protrusion, not a lid abscess.", "Correct. Hordeolum is the acute tender stye.", "Inward lid turning, not an abscess.", "A droop, not an abscess."]}'),
  ('a96285d3-24','{"options": ["Exophthalmos", "Ptosis", "Madarosis", "Entropion"], "correct": 2, "decode": "''Loss of lashes or brows, classic for ulcerative blepharitis'' is madarosis. Ptosis, entropion, and exophthalmos are unrelated.", "ow": ["Globe protrusion, not lash loss.", "A droop, not lash loss.", "Correct. Madarosis is loss of lashes or brows.", "Inward lid turning, not lash loss."]}'),
  ('522b628d-20','{"options": ["Entropion", "Epiphora", "Ptosis", "Exophthalmos"], "correct": 1, "decode": "''Tear overflow from a drainage block or reflex tearing'' is epiphora. The lid-position and protrusion terms do not mean tearing.", "ow": ["Inward lid turning, not tearing overflow.", "Correct. Epiphora is tear overflow.", "A droop, not tearing.", "Globe protrusion, not tearing."]}'),
  ('059243b0-1s','{"options": ["Ptosis", "Exophthalmos", "Entropion", "Dacryoadenitis"], "correct": 3, "decode": "''Lacrimal GLAND inflammation with an S-shaped ptosis'' is dacryoadenitis (aden = gland). Dacryocystitis is the sac; the others are unrelated.", "ow": ["A droop, but the stem names gland inflammation.", "Globe protrusion, not gland inflammation.", "Inward lid turning, not gland inflammation.", "Correct. Dacryoadenitis is lacrimal gland inflammation with an S-shaped lid."]}'),
  ('fd191ed9-1v','{"options": ["Exophthalmos", "Dacryocystitis", "Entropion", "Ptosis"], "correct": 1, "decode": "''Lacrimal SAC infection with medial canthal swelling'' is dacryocystitis (cyst = sac). Dacryoadenitis is the gland; the others are unrelated.", "ow": ["Globe protrusion, not sac infection.", "Correct. Dacryocystitis is tear-sac infection at the medial canthus.", "Inward lid turning, not sac infection.", "A droop, not sac infection."]}'),
  ('b63ed470-1i','{"options": ["Exophthalmos", "Distichiasis", "Entropion", "Ptosis"], "correct": 1, "decode": "''Accessory second row of eyelashes'' is distichiasis (di = two rows). Trichiasis would be misdirected normal lashes; the others are unrelated.", "ow": ["Globe protrusion, not an extra lash row.", "Correct. Distichiasis is an accessory second row of lashes.", "Inward lid turning, not an extra row.", "A droop, not an extra lash row."]}'),
  ('0f280c3d-1y','{"options": ["Ptosis", "Entropion", "Exophthalmos", "Symblepharon"], "correct": 3, "decode": "''Adhesion between palpebral and bulbar conjunctiva'' is symblepharon (sym = together, blepharon = lid). The lid-position and protrusion terms do not describe adhesions.", "ow": ["A droop, not a conjunctival adhesion.", "Inward lid turning, not adhesion.", "Globe protrusion, not adhesion.", "Correct. Symblepharon is adhesion of lid to globe conjunctiva."]}'),
  ('d6b31b6f-29','{"options": ["Hypopyon", "Ciliary flush", "Pinguecula", "Keratoconus"], "correct": 2, "decode": "''Yellow degenerative limbal deposit that does NOT cross the limbus'' is a pinguecula. Hypopyon is chamber pus; ciliary flush is redness; keratoconus is a shape disorder.", "ow": ["Layered pus in the anterior chamber, not a limbal deposit.", "A pattern of redness, not a deposit.", "Correct. Pinguecula is a yellow limbal deposit that stays off the cornea.", "A corneal shape disorder, not a deposit."]}'),
  ('fa5eafcd-2h','{"options": ["Pinguecula", "Ciliary flush", "Keratoconus", "Hypopyon"], "correct": 1, "decode": "''Deep violet circumcorneal injection'' seen in keratitis, uveitis, or acute glaucoma is the ciliary flush. The others are a deposit, pus, or a shape disorder.", "ow": ["A limbal deposit, not a redness pattern.", "Correct. Ciliary flush is deep circumcorneal injection of serious disease.", "A shape disorder, not injection.", "Chamber pus, not circumcorneal redness."]}'),
  ('5f51bedc-1s','{"options": ["Ciliary flush", "Keratoconus", "Pinguecula", "Hypopyon"], "correct": 3, "decode": "''Layered white cells in the anterior chamber'' is a hypopyon. Ciliary flush is redness, pinguecula a deposit, keratoconus a shape disorder.", "ow": ["A redness pattern, not layered cells.", "A shape disorder, not chamber cells.", "A limbal deposit, not chamber cells.", "Correct. Hypopyon is layered white cells in the anterior chamber."]}'),
  ('966039b8-1z','{"options": ["Keratic precipitates", "Ciliary flush", "Pinguecula", "Keratoconus"], "correct": 0, "decode": "''Mutton-fat = granulomatous, fine stellate = viral/Fuchs'' describes keratic precipitates (cells on the endothelium). The others are unrelated signs.", "ow": ["Correct. These endothelial cell deposits are keratic precipitates.", "A redness pattern, not endothelial deposits.", "A limbal deposit, not KPs.", "A shape disorder, not KPs."]}'),
  ('75a141cf-23','{"options": ["Pinguecula", "Ciliary flush", "Synechiae", "Keratoconus"], "correct": 2, "decode": "''Iris adhesions, anterior (to cornea) or posterior (to lens)'' are synechiae. The others are a deposit, a redness pattern, or a shape disorder.", "ow": ["A limbal deposit, not an adhesion.", "A redness pattern, not an adhesion.", "Correct. Synechiae are iris adhesions, anterior or posterior.", "A corneal shape disorder, not an adhesion."]}'),
  ('64b80b86-29','{"options": ["Ciliary flush", "Pinguecula", "Rubeosis iridis", "Keratoconus"], "correct": 2, "decode": "''Iris neovascularization closing the angle without pupillary block'' is rubeosis iridis. The others are a redness pattern, a deposit, or a shape disorder.", "ow": ["A redness pattern, not new iris vessels.", "A limbal deposit, not neovascularization.", "Correct. Rubeosis iridis is iris neovascularization causing angle closure.", "A corneal shape disorder, not iris vessels."]}'),
  ('c842ed53-1v','{"options": ["Ciliary flush", "Keratoconus", "Pinguecula", "Ectopia lentis"], "correct": 3, "decode": "''Lens dislocation, Marfan up and homocystinuria down'' is ectopia lentis. The others do not describe a displaced lens.", "ow": ["A redness pattern, not lens displacement.", "A corneal shape disorder, not lens displacement.", "A limbal deposit, not lens displacement.", "Correct. Ectopia lentis is dislocation of the crystalline lens."]}'),
  ('047a9edd-25','{"options": ["Pinguecula", "Ciliary flush", "Phacolytic", "Keratoconus"], "correct": 2, "decode": "''Open-angle glaucoma from leaked hypermature lens protein'' is phacolytic. The others are unrelated surface or shape findings.", "ow": ["A limbal deposit, not a glaucoma.", "A redness pattern, not a glaucoma.", "Correct. Phacolytic glaucoma comes from leaked lens protein clogging the open angle.", "A corneal shape disorder, not a glaucoma."]}'),
  ('723c388c-23','{"options": ["Phacomorphic", "Pinguecula", "Keratoconus", "Ciliary flush"], "correct": 0, "decode": "''Closed-angle glaucoma from an intumescent swollen lens'' is phacomorphic (morph = shape/size). Phacolytic is the open-angle protein type.", "ow": ["Correct. Phacomorphic glaucoma is angle closure from a swollen lens.", "A limbal deposit, not a glaucoma.", "A corneal shape disorder, not a glaucoma.", "A redness pattern, not a glaucoma."]}'),
  ('dcdd4e71-26','{"options": ["Keratoconus", "Pinguecula", "Ciliary flush", "Arcus senilis"], "correct": 3, "decode": "''Peripheral stromal cholesterol ring with a clear lucid interval at the limbus'' is arcus senilis. The others are a shape disorder, a deposit, or a redness pattern.", "ow": ["A corneal shape disorder, not a lipid ring.", "A limbal deposit, but not the peripheral cholesterol ring.", "A redness pattern, not a lipid ring.", "Correct. Arcus senilis is a peripheral corneal cholesterol ring."]}'),
  ('1bc0d34e-2e','{"options": ["Microaneurysm", "Rhegmatogenous", "Cotton-wool spot", "Shafer''s sign"], "correct": 3, "decode": "''Pigment in the anterior vitreous, a retinal break until proven otherwise'' is Shafer''s sign (tobacco dust). The others are retinal lesions, not vitreous pigment.", "ow": ["A capillary outpouching, not vitreous pigment.", "A detachment type, not the pigment sign.", "An ischemic infarct, not vitreous pigment.", "Correct. Shafer''s sign is anterior-vitreous pigment warning of a retinal break."]}'),
  ('87639d79-20','{"options": ["Microaneurysm", "Cotton-wool spot", "Rhegmatogenous", "Shafer''s sign"], "correct": 2, "decode": "''Detachment caused by a full-thickness break'' is rhegmatogenous. The other terms are a microvascular lesion, an infarct, or a vitreous sign.", "ow": ["A capillary lesion, not a detachment.", "An ischemic infarct, not a detachment.", "Correct. A full-thickness break defines rhegmatogenous detachment.", "A vitreous pigment sign, not a detachment."]}'),
  ('3464c841-1u','{"options": ["Microaneurysm", "Shafer''s sign", "Cotton-wool spot", "Rhegmatogenous"], "correct": 0, "decode": "''Earliest visible sign of diabetic retinopathy'' is the microaneurysm. The others are later or unrelated.", "ow": ["Correct. The microaneurysm is the earliest visible diabetic sign.", "A vitreous pigment sign, not a diabetic lesion.", "A later ischemic infarct.", "A detachment type, not a diabetic sign."]}'),
  ('b7fe35a6-1q','{"options": ["Shafer''s sign", "Microaneurysm", "Cotton-wool spot", "Rhegmatogenous"], "correct": 2, "decode": "''Ischemic swelling of axons, not an exudate'' is the cotton-wool spot (nerve fiber layer infarct). Microaneurysms and Shafer''s sign are different.", "ow": ["A vitreous pigment sign, not an axonal infarct.", "A capillary outpouching, not an infarct.", "Correct. Cotton-wool spots are ischemic nerve fiber layer infarcts.", "A detachment type, not an infarct."]}'),
  ('ac61e66e-20','{"options": ["Shafer''s sign", "Microaneurysm", "IRMA", "Rhegmatogenous"], "correct": 2, "decode": "''Shunt vessels in ischemic retina, a severe-NPDR marker'' are IRMA (intraretinal microvascular abnormalities). The others are unrelated.", "ow": ["A vitreous pigment sign, not shunt vessels.", "A capillary outpouching, not shunt vessels.", "Correct. IRMA are intraretinal shunt vessels marking severe NPDR.", "A detachment type, not shunt vessels."]}'),
  ('67ace468-1m','{"options": ["Shafer''s sign", "Rhegmatogenous", "Drusen", "Microaneurysm"], "correct": 2, "decode": "''Sub-RPE deposits, the hallmark of dry ARMD'' are drusen. The others are a vitreous sign, a detachment, or a microvascular lesion.", "ow": ["A vitreous pigment sign, not sub-RPE deposits.", "A detachment type, not drusen.", "Correct. Drusen are the sub-RPE deposits of dry ARMD.", "A capillary lesion, not drusen."]}'),
  ('784edca7-1x','{"options": ["Shafer''s sign", "Metamorphopsia", "Microaneurysm", "Rhegmatogenous"], "correct": 1, "decode": "''Wavy distortion on the Amsler grid, an early CNV warning'' is metamorphopsia. The others are unrelated retinal or vitreous terms.", "ow": ["A vitreous pigment sign, not distortion.", "Correct. Metamorphopsia is wavy-line distortion warning of macular neovascularization.", "A capillary lesion, not distortion.", "A detachment type, not distortion."]}'),
  ('6f937c58-22','{"options": ["Nyctalopia", "Rhegmatogenous", "Shafer''s sign", "Microaneurysm"], "correct": 0, "decode": "''Night blindness, the first symptom of retinitis pigmentosa'' is nyctalopia (nyct = night). The others are unrelated.", "ow": ["Correct. Nyctalopia is night blindness, the first RP symptom.", "A detachment type, not night blindness.", "A vitreous pigment sign, not night blindness.", "A capillary lesion, not night blindness."]}'),
  ('f1191b3c-20','{"options": ["Microaneurysm", "Rhegmatogenous", "Bone-spicule pigment", "Shafer''s sign"], "correct": 2, "decode": "''Classic mid-peripheral sign of retinitis pigmentosa'' is bone-spicule pigment. The others are unrelated.", "ow": ["A capillary lesion, not RP pigment.", "A detachment type, not RP pigment.", "Correct. Bone-spicule pigment is the classic mid-peripheral RP sign.", "A vitreous pigment sign, not RP pigment."]}'),
  ('08f01c8d-26','{"options": ["Microaneurysm", "Papilledema", "Rhegmatogenous", "Shafer''s sign"], "correct": 1, "decode": "''Bilateral disc swelling from raised intracranial pressure'' is papilledema. The others are unrelated retinal or vitreous terms.", "ow": ["A capillary lesion, not disc swelling.", "Correct. Papilledema is bilateral disc swelling from raised ICP.", "A detachment type, not disc swelling.", "A vitreous pigment sign, not disc swelling."]}'),
  ('eeefd138-25','{"options": ["Microaneurysm", "Rhegmatogenous", "RAPD", "Shafer''s sign"], "correct": 2, "decode": "''Marcus Gunn pupil from optic nerve or massive retinal disease'' is the RAPD (relative afferent pupillary defect). The others are unrelated.", "ow": ["A capillary lesion, not a pupil defect.", "A detachment type, not a pupil defect.", "Correct. The Marcus Gunn pupil is a relative afferent pupillary defect.", "A vitreous pigment sign, not a pupil defect."]}'),
  ('aefafd77-1p','{"options": ["Seidel test", "Open globe", "Coagulative necrosis", "Hyphema"], "correct": 2, "decode": "''Acid burn whose coagulum self-limits depth'' is coagulative necrosis. Alkali, by contrast, liquefies. The others are trauma terms.", "ow": ["A wound-leak test, not a burn mechanism.", "A ruptured eye, not a burn mechanism.", "Correct. Acids cause coagulative necrosis that self-limits depth.", "Blood in the chamber, not a burn mechanism."]}'),
  ('e420dfaa-26','{"options": ["Hyphema", "Seidel test", "Open globe", "Coagulative necrosis"], "correct": 1, "decode": "''Positive means aqueous leaking from a full-thickness corneal wound'' is the Seidel test. The others are a bleed, a rupture, or a burn.", "ow": ["Blood in the chamber, not a leak test.", "Correct. A positive Seidel test shows aqueous leaking through a wound.", "The diagnosis, but Seidel is the test that reveals it.", "A burn mechanism, not a leak test."]}'),
  ('504248b0-1m','{"options": ["Coagulative necrosis", "Hyphema", "Open globe", "Seidel test"], "correct": 2, "decode": "''Shield, no pressure, NPO, urgent surgery'' is the management of an open globe. The others are a burn, a bleed, or a leak test.", "ow": ["A burn mechanism, not this management.", "Blood in the chamber, not this management.", "Correct. Open globe: shield, no pressure, NPO, urgent surgery.", "A leak test, not the management."]}'),
  ('2b43c8c1-1x','{"options": ["Seidel test", "Coagulative necrosis", "Hyphema", "Open globe"], "correct": 2, "decode": "''Blood in the anterior chamber after blunt trauma'' is a hyphema. The others are a leak test, a burn, or a rupture.", "ow": ["A wound-leak test, not blood in the chamber.", "A burn mechanism, not blood in the chamber.", "Correct. Hyphema is blood layered in the anterior chamber.", "A ruptured eye, not blood in the chamber."]}'),
  ('81ac4dc1-27','{"options": ["Seidel test", "Open globe", "Coagulative necrosis", "Hypopyon"], "correct": 3, "decode": "''Layered white cells, endophthalmitis until proven otherwise'' is a hypopyon. The others are a leak test, a rupture, or a burn.", "ow": ["A wound-leak test, not chamber pus.", "A ruptured eye, not chamber pus.", "A burn mechanism, not chamber pus.", "Correct. Hypopyon is layered white cells suggesting endophthalmitis."]}'),
  ('50df0e38-1i','{"options": ["Coagulative necrosis", "Open globe", "Siderosis", "Seidel test"], "correct": 2, "decode": "''Iron IOFB toxicity, no MRI because it is ferrous'' is siderosis. The others are trauma terms, not a metal syndrome.", "ow": ["A burn mechanism, not a metal syndrome.", "A ruptured eye, not a metal syndrome.", "Correct. Siderosis is iron intraocular foreign-body toxicity.", "A wound-leak test, not a metal syndrome."]}'),
  ('d7261af2-1n','{"options": ["Seidel test", "Coagulative necrosis", "Open globe", "Chalcosis"], "correct": 3, "decode": "''Copper IOFB with a K-F ring and sunflower cataract'' is chalcosis (copper toxicity). Iron gives siderosis; the others are trauma terms.", "ow": ["A wound-leak test, not a metal syndrome.", "A burn mechanism, not a metal syndrome.", "A ruptured eye, not a metal syndrome.", "Correct. Chalcosis is copper toxicity with a K-F ring and sunflower cataract."]}'),
  ('c24c86af-1l','{"options": ["Seidel test", "Coagulative necrosis", "Open globe", "Enophthalmos"], "correct": 3, "decode": "''Sunken globe from a blow-out floor fracture'' is enophthalmos (en = in, back). The others are trauma terms, not globe position.", "ow": ["A wound-leak test, not globe position.", "A burn mechanism, not globe position.", "A ruptured eye, not a sunken one.", "Correct. Enophthalmos is a sunken globe after a floor fracture."]}'),
  ('afc6c93c-2b','{"options": ["Commotio retinae", "Seidel test", "Coagulative necrosis", "Open globe"], "correct": 0, "decode": "''Gray retinal opacification after blunt trauma that usually resolves'' is commotio retinae (Berlin''s edema). The others are a leak test, a burn, or a rupture.", "ow": ["Correct. Commotio retinae is transient traumatic retinal whitening.", "A wound-leak test, not retinal whitening.", "A burn mechanism, not retinal whitening.", "A ruptured eye, not retinal whitening."]}'),
  ('bda7567b-20','{"options": ["Open globe", "Seidel test", "Vossius ring", "Coagulative necrosis"], "correct": 2, "decode": "''Ring of iris pigment imprinted on the lens after blunt trauma'' is the Vossius ring. The others are a rupture, a leak test, or a burn.", "ow": ["A ruptured eye, not a pigment ring.", "A wound-leak test, not a pigment ring.", "Correct. The Vossius ring is iris pigment imprinted on the anterior lens.", "A burn mechanism, not a pigment ring."]}'),
  ('072dd02a-2b','{"options": ["15 mmHg", "2 mmHg", "5 mmHg", "8 mmHg"], "correct": 3, "decode": "A positive dark-room provocative test is an IOP rise of more than about 8 mmHg after sitting in the dark (pupil dilation crowds a narrow angle). Smaller rises are normal; 15 is more than needed.", "ow": ["More than required; the threshold is about 8.", "Too small to be significant.", "Below the usual positive threshold.", "Correct. A rise over about 8 mmHg is a positive dark-room provocative test."]}'),
  ('33c77b1f-1y','{"options": ["1 L in under 5 minutes", "250 mL over 30 minutes", "500 mL over 15 minutes", "2 L over an hour"], "correct": 0, "decode": "The water-drinking test has a fasting patient drink about 1 liter in under 5 minutes to provoke an IOP rise. The slower, smaller volumes would not stress outflow.", "ow": ["Correct. Roughly 1 liter in under 5 minutes is the water-drinking test.", "Too little, too slow to provoke a rise.", "Too little, too slow.", "Too slow to stress aqueous outflow."]}'),
  ('549b7ada-1y','{"options": ["520 microns", "480 microns", "555 microns", "600 microns"], "correct": 0, "decode": "A central corneal thickness below about 520 microns is an independent POAG risk factor (thin corneas underestimate IOP). 555 is near average; 600 is thick.", "ow": ["Correct. A CCT under about 520 microns is a POAG risk factor.", "Even thinner, but 520 is the quoted cutoff.", "Near-average thickness, not a risk cutoff.", "A thick cornea, which overestimates IOP."]}'),
  ('deecb20f-2c','{"options": ["0.05", "0.1", "0.2", "0.5"], "correct": 2, "decode": "Cup-to-disc asymmetry over about 0.2 between eyes is suspicious for glaucoma, since normal discs are fairly symmetric. Smaller differences are within normal.", "ow": ["Within normal variation.", "Still within normal limits.", "Correct. Asymmetry over about 0.2 is suspicious for glaucoma.", "Well beyond the suspicion threshold, but 0.2 is the quoted cutoff."]}'),
  ('86b6e840-1i','{"options": ["Isosorbide", "Mannitol", "Glycerol", "Urea"], "correct": 0, "decode": "Among oral osmotics, isosorbide is SAFE in diabetics because it is not metabolized to sugar, unlike glycerol. Mannitol and urea are IV agents with their own cautions.", "ow": ["Correct. Isosorbide is the diabetic-safe oral osmotic (not metabolized to glucose).", "An IV osmotic, not the diabetic-safe oral choice.", "Metabolized to glucose, so it raises blood sugar in diabetics.", "An IV agent, not the safe oral osmotic here."]}'),
  ('629050d8-1a','{"options": ["Heart failure", "Renal disease", "Diabetes mellitus", "Asthma"], "correct": 0, "decode": "Mannitol expands intravascular volume, so it is contraindicated in heart failure. Diabetes, asthma, and renal disease are not its classic contraindication in this context.", "ow": ["Correct. Mannitol''s volume load is dangerous in heart failure.", "A caution, but the classic contraindication asked is heart failure.", "Glycerol, not mannitol, is the diabetes concern.", "Not the classic mannitol contraindication."]}'),
  ('4cddef33-1s','{"options": ["The epithelium", "The endothelium", "Bowman''s layer", "Descemet''s membrane"], "correct": 1, "decode": "A Krukenberg spindle is pigment on the corneal ENDOTHELIUM (inner layer), from pigment dispersion. Not epithelium, Bowman''s, or Descemet''s.", "ow": ["The outer surface layer, not where the spindle sits.", "Correct. The Krukenberg spindle is pigment on the endothelium.", "A superficial layer, not the endothelium.", "The pigment sits on the endothelium in front of Descemet''s."]}'),
  ('4f2c373e-1u','{"options": ["The endothelium", "The epithelium", "Descemet''s membrane", "The stroma"], "correct": 1, "decode": "The Fleischer ring is IRON in the corneal EPITHELIUM at the cone base. A copper ring in Descemet''s would be Kayser-Fleischer, a different structure.", "ow": ["The inner layer; the Fleischer iron ring is epithelial.", "Correct. The Fleischer ring is iron in the epithelium at the cone base.", "That is where the copper K-F ring sits, not the iron Fleischer ring.", "Not the epithelial location of the Fleischer ring."]}'),
  ('43a8b3f7-1o','{"options": ["2.0 mm", "3.0 mm", "3.5 mm", "4.2 mm"], "correct": 1, "decode": "Anterior chamber depth shallows with age from about 3.6 mm toward 3.0 mm as the lens thickens. A drop to 2.0 mm is too extreme; 3.5 to 4.2 barely changes.", "ow": ["Too shallow for normal aging.", "Correct. The chamber shallows toward about 3.0 mm with age.", "Barely changed from the starting value.", "Deeper, the wrong direction for aging."]}'),
  ('a1e95ace-25','{"options": ["5%", "10%", "25%", "50%"], "correct": 2, "decode": "The figure used here is that aqueous production falls by roughly 25% per decade after 30. The smaller percentages understate the quoted decline.", "ow": ["Understates the quoted decline.", "Understates the quoted decline.", "Correct. About a 25% per-decade decline is the value used here.", "Overstates the decline."]}'),
  ('260082d0-22','{"options": ["50-60%", "20-30%", "No measurable loss", "2-5%"], "correct": 1, "decode": "Retinal nerve fiber layer thins by about 20 to 30% over a normal lifetime, which is why age-adjusted OCT norms matter. It is neither zero nor half.", "ow": ["Overstates the normal lifetime loss.", "Correct. About 20 to 30% RNFL loss occurs over a normal lifetime.", "There is measurable age-related loss.", "Understates the normal loss."]}'),
  ('1638ba2f-1n','{"options": ["20", "50", "200", "500"], "correct": 1, "decode": "CMV retinitis becomes a real risk once CD4 falls below 50. Higher counts (200, 500) are less at risk; 20 is even lower but 50 is the quoted threshold.", "ow": ["Even lower, but 50 is the standard threshold.", "Correct. CMV retinitis risk rises below a CD4 of 50.", "Higher count, lower CMV risk.", "Well above the risk threshold."]}'),
  ('529c0601-1o','{"options": ["10", "30", "50", "100"], "correct": 2, "decode": "Giant cell arteritis is supported by an ESR above about 50 (often much higher). Ten and thirty are within normal; 100 is high but 50 is the working cutoff.", "ow": ["A normal ESR.", "Still within normal range.", "Correct. An ESR over about 50 supports giant cell arteritis.", "Very high, but 50 is the supporting threshold."]}'),
  ('55fa3ace-1o','{"options": ["2 weeks", "72 hours", "72 days", "6 months"], "correct": 1, "decode": "A young-diabetic (snowflake) cataract can mature in as little as about 72 hours. Weeks or months understate the classic rapid osmotic progression.", "ow": ["Slower than the classic rapid progression.", "Correct. A diabetic snowflake cataract can mature in about 72 hours.", "Far too slow.", "Far too slow for the acute diabetic cataract."]}'),
  ('cfdc4831-1q','{"options": ["6 months", "5 years", "2 years", "10 years"], "correct": 2, "decode": "Shaken baby syndrome is essentially confined to children under 2, whose neck control and bridging veins make them vulnerable. Older ages are outside the classic window.", "ow": ["Too narrow; it extends to about 2 years.", "Beyond the classic vulnerable age.", "Correct. Shaken baby syndrome is essentially under 2 years.", "Well outside the vulnerable age."]}'),
  ('ed69d155-25','{"options": ["Vossius ring", "Krukenberg spindle", "Vogt''s striae", "Mittendorf dot"], "correct": 0, "decode": "A pigment imprint on the ANTERIOR LENS capsule after blunt trauma is a Vossius ring. Krukenberg is on the cornea; Vogt''s striae are keratoconus; Mittendorf dot is congenital.", "ow": ["Correct. The Vossius ring is pigment imprinted on the anterior lens.", "A corneal endothelial pigment spindle, not on the lens.", "Keratoconus stress lines, not a pigment ring.", "A congenital hyaloid remnant, not traumatic."]}'),
  ('f3e12486-21','{"options": ["A D-shaped pupil", "A perfectly round pupil", "A peaked pupil", "A pinpoint pupil"], "correct": 0, "decode": "Separation of the iris root (iridodialysis) after blunt trauma makes a D-shaped pupil. A peaked pupil suggests a wound; round and pinpoint do not fit iris-root tears.", "ow": ["Correct. Iridodialysis gives a D-shaped pupil.", "Trauma distorts the pupil; it is not perfectly round.", "A peaked pupil points to a corneal or scleral wound, not iris-root separation.", "Miosis is not the iridodialysis shape."]}'),
  ('c220f5a7-16','{"options": ["24 hours", "It never resolves", "6 months", "2-6 weeks"], "correct": 3, "decode": "Commotio retinae typically clears in about 2 to 6 weeks. It is not permanent, not 24 hours, and not 6 months.", "ow": ["Too fast; it takes weeks.", "It usually does resolve.", "Longer than the usual course.", "Correct. Commotio retinae generally resolves in 2 to 6 weeks."]}'),
  ('02ce3b67-29','{"options": ["Late secondary glaucoma", "Corneal decompensation", "Optic neuritis", "Retinal detachment"], "correct": 0, "decode": "Angle recession needs long-term follow-up because it risks LATE secondary (angle-recession) glaucoma. Corneal decompensation, optic neuritis, and detachment are not its main long-term risk.", "ow": ["Correct. Angle recession risks late secondary glaucoma.", "Not the main long-term angle-recession risk.", "Unrelated to angle recession.", "Not the primary long-term concern here."]}'),
  ('d7686190-1d','{"options": ["Optic disc", "Macula", "Equator", "Ora serrata"], "correct": 3, "decode": "Traumatic retinal dialysis occurs at the ORA SERRATA, the weak peripheral attachment. Not the disc, macula, or equator.", "ow": ["The nerve exit, not the peripheral tear site.", "Central retina, not the dialysis site.", "Between the ora and posterior pole, not the dialysis site.", "Correct. Retinal dialysis occurs at the ora serrata."]}'),
  ('1b387f6b-1z','{"options": ["Retinal dialysis", "Vossius ring", "Choroidal rupture", "Commotio retinae"], "correct": 2, "decode": "A white crescent concentric with the disc after blunt trauma is a choroidal rupture (a break in Bruch''s membrane showing sclera). Dialysis, Vossius ring, and commotio look different.", "ow": ["A peripheral retinal tear, not a peripapillary crescent.", "A lens pigment ring, not a choroidal break.", "Correct. Choroidal rupture is a white crescent concentric with the disc.", "Retinal whitening, not a crescentic scleral break."]}'),
  ('f1bb94b4-1x','{"options": ["Sagittal sections only", "Axial sections", "T2-weighted sequences", "Coronal sections"], "correct": 3, "decode": "An orbital blow-out (floor) fracture is best shown on CT with CORONAL sections, which display the orbital floor directly. Axial and sagittal miss the floor; T2 MRI is not first-line for bone.", "ow": ["Sagittal alone poorly shows the floor.", "Axial cuts do not display the floor well.", "MRI sequences are not first-line for bony fractures.", "Correct. Coronal CT best displays the orbital floor."]}'),
  ('a8c607bd-1n','{"options": ["Cupping as the earliest sign", "Sudden pain with a fixed pupil", "Gradual painless peripheral loss", "A normal, briskly reactive pupil"], "correct": 1, "decode": "PACG (angle closure) classically presents with SUDDEN pain and a fixed mid-dilated pupil, unlike POAG''s silent gradual course. Early cupping and painless loss describe POAG.", "ow": ["Cupping over time is the POAG pattern.", "Correct. Angle closure presents with sudden pain and a fixed pupil.", "That is POAG, painless and gradual.", "A normal reactive pupil argues against an acute attack."]}'),
  ('e4bc41f5-1j','{"options": ["Prescribed artificial tears only", "Referred for urgent ocular evaluation", "Given new glasses immediately", "Told to rest for one week"], "correct": 1, "decode": "''Sudden painless loss of vision'' is an emergency umbrella (CRAO, detachment, vitreous hemorrhage), so the safe action is always urgent referral. Tears, glasses, and ''rest a week'' dangerously delay care.", "ow": ["Tears do nothing for sudden vision loss.", "Correct. Sudden painless loss needs urgent ocular evaluation.", "New glasses cannot fix a retinal or vascular emergency.", "Waiting a week risks permanent loss."]}'),
  ('bf3afe98-1r','{"options": ["Mild itching that eases with a little rest", "Flashes and a sudden increase in floaters", "Mild eye fatigue after prolonged screen use", "Occasional watery tearing in a cold wind"], "correct": 1, "decode": "Flashes plus a sudden shower of floaters is the classic retinal detachment warning. Itching, fatigue, and tearing are benign surface symptoms.", "ow": ["Benign surface itch, not a detachment warning.", "Correct. Flashes and new floaters warn of a retinal tear or detachment.", "Ordinary eye strain, not a warning sign.", "A benign reflex tearing, not a detachment sign."]}'),
  ('aac4a8b6-1y','{"options": ["Severe eye pain with blurred vision and halos", "Mild itching", "Improved vision at night", "Painless gradual vision improvement"], "correct": 0, "decode": "Acute angle closure shows severe pain, blurred vision, and colored halos from a pressure spike. Mild itching or vision that improves argue against it.", "ow": ["Correct. Severe pain, blurred vision, and halos are the angle-closure cluster.", "Itching is allergy, not angle closure.", "Angle closure worsens, not improves, vision.", "Painless improvement is the opposite of an attack."]}'),
  ('07d64963-2k','{"options": ["Give a stronger spectacle prescription and reassure the patient", "Perform appropriate ocular evaluation and consider urgent referral", "Dispense tinted cosmetic contact lenses to hide the redness", "Ignore the symptoms and schedule a routine recheck later"], "correct": 1, "decode": "A red painful eye with marked photophobia is potentially serious (keratitis, uveitis, angle closure), so the answer is proper evaluation and possible urgent referral, never a cosmetic or dismissive option.", "ow": ["A stronger prescription ignores a possibly serious cause.", "Correct. Evaluate properly and consider urgent referral.", "Cosmetic lenses hide, not treat, the problem.", "Ignoring red flags risks vision."]}'),
  ('78914b33-2f','{"options": ["Retinal detachment", "Presbyopia", "Simple astigmatism", "Dry eye"], "correct": 0, "decode": "A sudden ''curtain'' or shadow across the field is the classic retinal detachment description. Presbyopia, astigmatism, and dry eye are gradual, painless refractive or surface problems.", "ow": ["Correct. A curtain across the field suggests retinal detachment.", "A gradual near-focus loss, not a curtain.", "A steady refractive blur, not a curtain.", "A surface dryness, not a field defect."]}'),
  ('f0c97fda-18','{"options": ["Sudden flashes only", "Severe acute eye pain", "Gradual painless reduction in vision", "Sudden complete loss of vision"], "correct": 2, "decode": "Cataract is a slow, painless clouding, so ''gradual painless vision reduction'' fits. Flashes, acute pain, and sudden total loss point to other emergencies.", "ow": ["Flashes suggest retinal disease, not cataract.", "Cataract is painless.", "Correct. Gradual painless vision reduction is the cataract pattern.", "Sudden total loss is a vascular or retinal emergency, not cataract."]}'),
  ('0c29a412-1b','{"options": ["Gradual improvement in vision", "Mild itching", "Sudden increase in floaters and flashes", "Excessive blinking"], "correct": 2, "decode": "The classic detachment warning is a sudden increase in floaters and flashes. Improvement, itching, and blinking are not warning signs.", "ow": ["Vision worsens, not improves, in detachment.", "A benign surface symptom.", "Correct. Sudden floaters and flashes warn of detachment.", "Blinking is unrelated to detachment."]}'),
  ('2ef5634d-1h','{"options": ["Edema", "Hyperplasia", "Atrophy", "Necrosis"], "correct": 0, "decode": "Abnormal fluid accumulation in tissue is edema. Hyperplasia is more cells, atrophy is shrinkage, necrosis is death.", "ow": ["Correct. Edema is abnormal fluid in tissue.", "That is an increase in cell number.", "That is tissue shrinkage.", "That is cell death."]}'),
  ('7414509a-1e','{"options": ["Hyperplasia", "Hypertrophy", "Metaplasia", "Necrosis"], "correct": 3, "decode": "Cell death from pathological injury is necrosis. Hyperplasia and hypertrophy are growth; metaplasia is a change of cell type.", "ow": ["An increase in cell number, not death.", "An increase in cell size, not death.", "A change of cell type, not death.", "Correct. Necrosis is pathological cell death."]}'),
  ('d8d807bb-1h','{"options": ["Necrosis", "Atrophy", "Hypertrophy", "Hyperplasia"], "correct": 2, "decode": "An increase in cell SIZE is hypertrophy (trophy = size). Hyperplasia is number; atrophy is shrinkage; necrosis is death.", "ow": ["Cell death, not enlargement.", "Shrinkage, the opposite.", "Correct. Hypertrophy is an increase in individual cell size.", "An increase in cell number, not size."]}'),
  ('c7b0ac84-18','{"options": ["Hyperplasia", "Necrosis", "Atrophy", "Hypertrophy"], "correct": 0, "decode": "An increase in cell NUMBER is hyperplasia (plasia = number). Hypertrophy is size; atrophy is shrinkage; necrosis is death.", "ow": ["Correct. Hyperplasia is an increase in cell number.", "Cell death, not proliferation.", "Shrinkage, the opposite.", "An increase in cell size, not number."]}'),
  ('48b5b90f-2g','{"options": ["Corneal ulcer", "Pterygium", "Keratitis", "Pinguecula"], "correct": 3, "decode": "The one that stays on the conjunctiva and does NOT cross onto the cornea is the pinguecula. Pterygium crosses; ulcer and keratitis are corneal.", "ow": ["A corneal surface break, not a conjunctival deposit.", "This one DOES cross onto the cornea.", "Corneal inflammation, not a conjunctival deposit.", "Correct. Pinguecula stays on the conjunctiva off the cornea."]}'),
  ('fdf8318a-13','{"options": ["Retina", "Iris", "Cornea", "Sclera"], "correct": 2, "decode": "Kerat- means cornea, so keratitis is corneal inflammation. Retina, iris, and sclera have their own -itis terms.", "ow": ["Retinitis is the retina.", "Iritis is the iris.", "Correct. Keratitis is inflammation of the cornea.", "Scleritis is the sclera."]}'),
  ('d4311bd1-w','{"options": ["Painless drooping of the upper eyelid only", "Pain, photophobia, and reduced vision", "A sudden marked increase in the near vision", "Painless improvement of the near vision only"], "correct": 1, "decode": "A corneal ulcer is an open, sensitive surface defect, so it hurts, dislikes light, and blurs vision. Any painless or vision-improving option contradicts an inflamed cornea.", "ow": ["A ptosis is unrelated to a corneal ulcer.", "Correct. Pain, photophobia, and reduced vision fit a corneal ulcer.", "An ulcer does not improve near vision.", "Painless improvement is the opposite of an ulcer."]}'),
  ('235de6ac-v','{"options": ["Lens opacity", "Superficial episcleral inflammation", "Retinal inflammation", "Optic nerve inflammation"], "correct": 1, "decode": "Episcleritis is superficial episcleral inflammation, benign and usually painless. Lens, retina, and optic nerve are deeper, unrelated structures.", "ow": ["A lens change, not surface inflammation.", "Correct. Episcleritis is superficial episcleral inflammation.", "A deep retinal process, not the surface episclera.", "An optic nerve process, not the episclera."]}'),
  ('4f638c83-w','{"options": ["A sudden dark curtain across the vision", "Progressive painless reduction in vision", "Severe relentless itching of the eye only", "Sudden severe boring pain deep in the eye"], "correct": 1, "decode": "A cataract clouds the lens slowly and painlessly, so ''progressive painless vision reduction'' fits. Curtains, itching, and boring pain point elsewhere.", "ow": ["A curtain suggests retinal detachment.", "Correct. Progressive painless vision loss is the cataract pattern.", "Itching is allergy, not cataract.", "Boring pain suggests scleritis, not cataract."]}'),
  ('cebca41f-1t','{"options": ["Peripheral spoke-like cortical cataract", "Central dense nuclear cataract", "Posterior subcapsular cataract", "Anterior polar congenital cataract"], "correct": 2, "decode": "''Beneath the posterior capsule'' names the posterior subcapsular cataract by location. Nuclear is central, cortical is spokes, polar is congenital.", "ow": ["Spoke opacities in the cortex, not subcapsular.", "Central sclerosis, not subcapsular.", "Correct. Posterior subcapsular sits beneath the back capsule.", "A congenital polar opacity, not posterior subcapsular."]}'),
  ('6ffbc33c-2h','{"options": ["Cataract", "Conjunctivitis", "Presbyopia", "Retinal detachment"], "correct": 3, "decode": "A moving curtain across the field is highly suggestive of retinal detachment. Cataract, conjunctivitis, and presbyopia do not produce a curtain.", "ow": ["A slow painless clouding, not a curtain.", "A surface redness, not a field defect.", "A near-focus loss, not a curtain.", "Correct. A curtain across the field suggests retinal detachment."]}'),
  ('9126e61a-1n','{"options": ["Corneal epithelium", "Retinal blood vessels", "Eyelid muscles", "Lens fibers"], "correct": 1, "decode": "Diabetes damages the small retinal BLOOD VESSELS (microaneurysms, leakage, new vessels). The cornea, lid muscles, and lens fibers are not the primary target.", "ow": ["Not the target of diabetic retinopathy.", "Correct. Diabetic retinopathy is retinal blood-vessel damage.", "Not the target of diabetic retinopathy.", "Diabetic cataract is separate; retinopathy is vascular."]}'),
  ('5c29508c-3z','{"options": ["Allergic conjunctivitis", "Acute angle-closure glaucoma", "Pinguecula", "Simple myopia"], "correct": 1, "decode": "Severe pain, red eye, blurred vision, halos, headache, and nausea together are acute angle-closure glaucoma. Allergy, pinguecula, and myopia do not give this cluster.", "ow": ["Allergy itches; it does not give halos and nausea.", "Correct. The full cluster is acute angle-closure glaucoma.", "A painless surface bump, not this emergency.", "A refractive error, not a painful red-eye emergency."]}'),
  ('86e6a8e8-o','{"options": ["Double vision only", "Complete loss of vision", "Distorted vision", "Color blindness"], "correct": 2, "decode": "Metamorphopsia means distorted (warped) vision, a macular sign. It is not diplopia, total loss, or color blindness.", "ow": ["Double vision is diplopia, not distortion.", "Not total loss.", "Correct. Metamorphopsia is distorted vision.", "Not a color defect."]}'),
  ('a150adb3-1o','{"options": ["No redness", "Improved visual acuity", "Only mild itching", "Severe deep ocular pain"], "correct": 3, "decode": "Scleritis causes SEVERE deep boring pain, unlike the mild, often painless episcleritis. Options claiming no redness or better vision do not fit inflammation.", "ow": ["Scleritis is red, not without redness.", "Vision does not improve in scleritis.", "Mild itching fits allergy, not scleritis.", "Correct. Scleritis causes severe deep ocular pain."]}'),
  ('5c5f0ece-t','{"options": ["Optic nerve", "Iris", "Cornea", "Retina"], "correct": 1, "decode": "Irit- means iris, so iritis is iris inflammation (anterior uveitis). Optic nerve, cornea, and retina have their own terms.", "ow": ["Optic neuritis is the nerve.", "Correct. Iritis is inflammation of the iris.", "Keratitis is the cornea.", "Retinitis is the retina."]}'),
  ('683bc756-10','{"options": ["Spontaneous dislocation of the crystalline lens", "Marked optic disc cupping and pallor only", "Cells and flare in the anterior chamber", "Sudden rhegmatogenous retinal detachment"], "correct": 2, "decode": "Anterior uveitis leaks cells and protein into the aqueous, seen as cells and flare on the slit lamp. Lens dislocation, disc cupping, and detachment are other diseases.", "ow": ["A traumatic or Marfan sign, not uveitis.", "A glaucoma sign, not anterior uveitis.", "Correct. Cells and flare in the anterior chamber signal anterior uveitis.", "A retinal emergency, not anterior-chamber inflammation."]}'),
  ('4d975fb7-m','{"options": ["Opacity of the crystalline lens", "Increased corneal curvature", "Retinal inflammation", "Optic nerve swelling"], "correct": 0, "decode": "A cataract is by definition an opacity of the crystalline lens. Corneal steepening, retinal inflammation, and disc swelling are different conditions.", "ow": ["Correct. Cataract is opacity of the crystalline lens.", "That is a corneal, not lens, change.", "That is retinitis, not cataract.", "That is disc swelling, not cataract."]}'),
  ('bdb10902-z','{"options": ["The pharmacological treatment of ocular disease", "The design and use of surgical instruments", "Diseases and their effects on tissues and organs", "The normal anatomy of healthy body structures"], "correct": 2, "decode": "''Path'' means disease, so pathology is the study of disease and how it changes tissues and organs. Treatment, instruments, and normal anatomy are separate subjects.", "ow": ["Treatment is pharmacology, not pathology.", "Instruments are a technical topic, not pathology.", "Correct. Pathology studies disease and its tissue effects.", "Normal anatomy is not the study of disease."]}'),
  ('b0561c7c-1o','{"options": ["Bradycardia", "Redness", "Heat", "Swelling"], "correct": 0, "decode": "The classic signs of inflammation are redness, heat, swelling, and pain (rubor, calor, tumor, dolor). Bradycardia, a slow heart rate, is the odd one out.", "ow": ["Correct. Bradycardia is not a cardinal inflammation sign.", "Redness (rubor) is a classic sign.", "Heat (calor) is a classic sign.", "Swelling (tumor) is a classic sign."]}'),
  ('0846e31d-1a','{"options": ["Tumor", "Dolor", "Calor", "Rubor"], "correct": 3, "decode": "Rubor is Latin for redness. Dolor is pain, calor is heat, tumor is swelling. Translate each term.", "ow": ["Tumor means swelling.", "Dolor means pain.", "Calor means heat.", "Correct. Rubor means redness."]}'),
  ('c96ecfbf-1n','{"options": ["Tumor", "Calor", "Dolor", "Rubor"], "correct": 2, "decode": "Dolor is Latin for pain. Tumor is swelling, calor is heat, rubor is redness. Translate each term.", "ow": ["Tumor means swelling.", "Calor means heat.", "Correct. Dolor means pain.", "Rubor means redness."]}'),
  ('e558345f-1q','{"options": ["Eyelid edema only", "Corneal ulceration", "Lens opacity", "Neovascularization"], "correct": 3, "decode": "''Proliferative'' means new growth, so the hallmark of proliferative diabetic retinopathy is neovascularization. Lid edema, corneal ulcer, and lens opacity are unrelated.", "ow": ["Not a retinal feature.", "A corneal problem, not proliferative retinopathy.", "A lens change, not retinal new vessels.", "Correct. Neovascularization defines proliferative diabetic retinopathy."]}'),
  ('4aa64d27-1i','{"options": ["Macula", "Ciliary muscle", "Peripheral cornea", "Iris"], "correct": 0, "decode": "Age-related MACULAR degeneration attacks the macula (central vision). The ciliary muscle, peripheral cornea, and iris are not its target.", "ow": ["Correct. AMD primarily affects the macula.", "The focusing muscle, not the AMD target.", "A peripheral corneal structure, unrelated.", "Not the AMD target."]}'),
  ('5b549b24-17','{"options": ["Distortion of visual images", "Loss of peripheral vision", "Loss of color vision only", "Complete blindness"], "correct": 0, "decode": "Metamorphopsia is distortion of visual images (wavy lines), a macular sign. It is not peripheral loss, color loss, or blindness.", "ow": ["Correct. Metamorphopsia is distortion of images.", "Peripheral loss is a different defect.", "Not an isolated color problem.", "Not total blindness."]}'),
  ('13955643-1f','{"options": ["Simple myopia only", "Presbyopia", "Chalazion", "Vascular retinal disease"], "correct": 3, "decode": "Retinal hemorrhages need vessels, so they link to vascular retinal disease (diabetes, vein occlusion). Myopia, presbyopia, and chalazion do not bleed into the retina.", "ow": ["Simple myopia does not cause retinal hemorrhage.", "A focusing change, not a bleeding cause.", "A lid lump, unrelated to retinal bleeding.", "Correct. Retinal hemorrhages arise from vascular retinal disease."]}'),
  ('4e899582-1n','{"options": ["Protozoa", "Viruses", "Fungi", "Bacteria"], "correct": 3, "decode": "The adjective names the organism: bacterial infections are caused by bacteria. Viruses, fungi, and protozoa cause their own categories.", "ow": ["Protozoa cause protozoal infections.", "Viruses cause viral infections.", "Fungi cause fungal infections.", "Correct. Bacteria cause bacterial infections."]}'),
  ('c55e2d2c-14','{"options": ["A complete absence of any cellular growth", "A brief self-limited inflammatory reaction", "Invasive growth and potential metastasis", "Entirely normal, orderly tissue development"], "correct": 2, "decode": "A malignant neoplasm invades and can spread (metastasize). Benign, self-limited, or normal growth stays local.", "ow": ["Malignant tumors grow, not the reverse.", "A brief inflammatory reaction is not a malignancy.", "Correct. Invasive growth with metastatic potential defines malignancy.", "Orderly normal growth is benign, not malignant."]}'),
  ('7033572b-y','{"options": ["Retina", "Eyelid margins", "Cornea", "Choroid"], "correct": 1, "decode": "Blephar- means eyelid, so blepharitis is inflammation of the eyelid margins. Retina, cornea, and choroid are unrelated.", "ow": ["The retina has its own -itis.", "Correct. Blepharitis is eyelid margin inflammation.", "Keratitis is the cornea.", "The choroid is unrelated."]}'),
  ('9129e8c1-14','{"options": ["Lens opacity", "Optic nerve atrophy", "Painless retinal swelling", "Acute painful eyelid inflammation"], "correct": 3, "decode": "A hordeolum (stye) is an acute, painful, infected eyelid gland. Painless retinal swelling, lens opacity, and optic atrophy describe other problems.", "ow": ["A lens change, not a lid infection.", "An optic nerve problem, not a stye.", "Painless and retinal, the opposite of a stye.", "Correct. A hordeolum is acute painful eyelid inflammation."]}'),
  ('e6ba9eba-1p','{"options": ["Lacrimal gland", "Meibomian gland", "Ciliary muscle", "Sweat gland of the skin"], "correct": 1, "decode": "A chalazion is a blocked MEIBOMIAN (oil) gland. Not the lacrimal or sweat gland, and not a muscle.", "ow": ["A tear gland, not the oil gland.", "Correct. A chalazion is a blocked meibomian gland.", "A focusing muscle, unrelated.", "A skin sweat gland, not the meibomian gland."]}'),
  ('ad5e9146-1s','{"options": ["A hordeolum is usually deep and entirely painless", "A chalazion is almost always acutely infected", "Chalazion is usually chronic and painless", "A hordeolum typically affects only the retina"], "correct": 2, "decode": "Contrast the pair: chalazion is chronic and painless, hordeolum is acute and painful. Pick the statement that keeps that split correct.", "ow": ["A hordeolum is acute and painful, not painless.", "A chalazion is typically non-infected, not acutely infected.", "Correct. Chalazion is usually chronic and painless.", "A hordeolum affects the lid, not the retina."]}'),
  ('fc782111-c','{"options": ["Drooping of the eyelid", "Inward turning of the eyelid", "Outward turning of the eyelid", "Inability to close the eyelid"], "correct": 1, "decode": "Entropion is inward turning of the eyelid (en = in). Outward is ectropion; drooping is ptosis; failure to close is lagophthalmos.", "ow": ["Drooping is ptosis.", "Correct. Entropion is inward lid turning.", "Outward turning is ectropion.", "Failure to close is lagophthalmos."]}'),
  ('f76d6f0f-1s','{"options": ["Optic nerve", "Lens capsule", "Conjunctiva", "Corneal epithelium"], "correct": 0, "decode": "Glaucoma is defined by progressive OPTIC NERVE damage (cupping, field loss). The lens capsule, conjunctiva, and corneal epithelium are not what it destroys.", "ow": ["Correct. Glaucoma damages the optic nerve.", "Not the glaucoma target.", "Not the glaucoma target.", "Not the glaucoma target."]}'),
  ('f3045b47-10','{"options": ["Asymptomatic in its early stages", "Associated with severe corneal ulceration", "Always associated with acute redness", "Painful at the beginning"], "correct": 0, "decode": "Primary open-angle glaucoma is silent early, with no pain and slow peripheral loss. Pain, ulceration, and acute redness belong to angle closure or other diseases.", "ow": ["Correct. Open-angle glaucoma is asymptomatic early.", "Ulceration is not a glaucoma feature.", "Acute redness suggests angle closure, not open-angle.", "Open-angle is painless, not painful."]}'),
  ('bb219455-20','{"options": ["Painless, gradual improvement of the vision over weeks", "A small, firm, completely painless chalazion", "Severe eye pain, blurred vision, halos, and nausea", "Only mild transient itching of the eyelids"], "correct": 2, "decode": "Severe pain, blurred vision, halos, and nausea together are the acute angle-closure cluster. Painless improvement, a chalazion, or mild itching do not fit.", "ow": ["Angle closure worsens vision suddenly, not slowly improves.", "A painless lid lump, not an angle-closure attack.", "Correct. Pain, blurred vision, halos, and nausea signal angle closure.", "Mild itching is allergy, not angle closure."]}'),
  ('171661b8-18','{"options": ["Cataract", "Dry eye", "Increased intraocular pressure only", "Increased intracranial pressure"], "correct": 3, "decode": "Papilledema is disc swelling from raised INTRAcranial pressure, transmitted along the nerve sheath, and is typically bilateral. It is not from eye pressure alone, cataract, or dry eye.", "ow": ["A lens change, not disc swelling.", "A surface disorder, not disc swelling.", "Intraocular pressure alone does not cause papilledema.", "Correct. Papilledema is from raised intracranial pressure."]}'),
  ('69f4eb28-11','{"options": ["Iris", "Cornea", "Optic nerve", "Lens"], "correct": 2, "decode": "Neuritis + optic means optic nerve inflammation. Iris, cornea, and lens are separate structures.", "ow": ["Iritis is the iris.", "Keratitis is the cornea.", "Correct. Optic neuritis is inflammation of the optic nerve.", "The lens is not inflamed here."]}'),
  ('b1e25296-c','{"options": ["Inward turning of the eyelid", "Eyelid tumor", "Outward turning of the eyelid", "Eyelid infection"], "correct": 2, "decode": "Ectropion is outward turning of the eyelid (ec = out). Inward is entropion; infection and tumor are different lid problems.", "ow": ["Inward turning is entropion.", "A tumor is a different lid problem.", "Correct. Ectropion is outward lid turning.", "Infection is a different lid problem."]}'),
  ('84fd0e93-g','{"options": ["Eyelid infection", "Eyelid inflammation", "Drooping of the upper eyelid", "Inward turning of the eyelid"], "correct": 2, "decode": "Ptosis is drooping of the upper eyelid. It is not infection, inflammation, or inward turning.", "ow": ["Infection is a different lid problem.", "Inflammation is a different lid problem.", "Correct. Ptosis is drooping of the upper eyelid.", "Inward turning is entropion."]}'),
  ('fb3fce0c-1z','{"options": ["Fixed mid-dilated pupil", "Sudden curtain-like vision loss", "Intense itching", "Severe deep ocular pain"], "correct": 2, "decode": "Allergic conjunctivitis is histamine-driven, so intense itching is its hallmark. A fixed pupil, curtain vision loss, and deep pain signal more serious disease.", "ow": ["A fixed mid-dilated pupil suggests angle closure, not allergy.", "A curtain suggests retinal detachment.", "Correct. Intense itching is the allergy hallmark.", "Deep pain suggests scleritis or uveitis, not allergy."]}'),
  ('4de471f0-e','{"options": ["A focal demyelinating lesion of the optic nerve", "A localized opacity of the crystalline lens", "A fibrovascular growth extending onto the cornea", "A malignant tumor arising within the retina"], "correct": 2, "decode": "A pterygium is a wing-shaped fibrovascular conjunctival growth creeping onto the cornea. It is not an optic nerve, lens, or retinal lesion.", "ow": ["An optic nerve lesion is unrelated.", "A lens opacity is a cataract, not a pterygium.", "Correct. A pterygium is a fibrovascular growth onto the cornea.", "A retinal tumor is unrelated."]}'),
  ('9ae5ea10-18','{"options": ["Isolated swelling of the upper eyelid only", "Noticeably improved color vision and sharper acuity", "Reduced color vision and decreased visual acuity", "A marked increase in reflex tear production"], "correct": 2, "decode": "Optic neuritis damages the nerve carrying color and detail, so color vision and acuity drop and vision dims. Improved vision, lid swelling, or more tearing do not fit.", "ow": ["An isolated lid problem, not nerve disease.", "Vision worsens, not improves, in optic neuritis.", "Correct. Reduced color vision and acuity fit optic neuritis.", "Not a feature of optic nerve inflammation."]}'),
  ('940f3cc5-x','{"options": ["Optic disc pallor associated with loss of optic nerve fibers", "A dense central opacity of the crystalline lens only", "Diffuse corneal edema with epithelial microcysts only", "An acute bacterial conjunctival infection with discharge"], "correct": 0, "decode": "Optic atrophy is death of nerve fibers, so the disc looks pale (pallor) with vision loss. Corneal edema, lens opacity, and conjunctival infection are front-of-eye problems.", "ow": ["Correct. Optic disc pallor with loss of nerve fibers is optic atrophy.", "A lens change, not disc pallor.", "A corneal problem, not the disc.", "A surface infection, not optic atrophy."]}'),
  ('ad22b479-41','{"options": ["Corneal ulcer / keratitis", "Uncorrected presbyopia at near", "An age-related nuclear cataract", "A conjunctival pinguecula"], "correct": 0, "decode": "Painful red eye + photophobia + an epithelial defect that STAINS is a corneal ulcer or keratitis. Presbyopia, cataract, and pinguecula are painless and do not stain.", "ow": ["Correct. A staining painful epithelial defect is a corneal ulcer or keratitis.", "A painless near-focus problem, no staining.", "A painless lens opacity, no staining.", "A painless conjunctival deposit, no epithelial defect."]}'),
  ('255515dd-3x','{"options": ["Prescribe reading glasses", "Reassure the patient and schedule routine follow-up", "Arrange urgent ophthalmic evaluation", "Recommend artificial tears only"], "correct": 2, "decode": "Flashes + new floaters + a dark curtain is a retinal detachment emergency; the safe action is urgent referral. Glasses, routine follow-up, or tears would dangerously delay care.", "ow": ["Reading glasses cannot fix a detachment.", "Routine follow-up is unsafe for a detachment.", "Correct. Flashes, floaters, and a curtain need urgent ophthalmic evaluation.", "Tears do not address a retinal emergency."]}'),
  ('b053b9eb-1c','{"options": ["Proparacaine", "Tropicamide", "Phenylephrine 2.5%", "Cyclopentolate"], "correct": 2, "decode": "PHENYLEPHRINE (an α1 agonist on the dilator) mydriates WITHOUT cycloplegia because the ciliary muscle has no α1 receptors.", "ow": ["Proparacaine is an anesthetic, not a mydriatic.", "Tropicamide is an M3 blocker, so it also cyclopleges.", "Correct. Phenylephrine dilates without touching accommodation.", "Cyclopentolate is a strong cycloplegic, not accommodation-sparing."]}'),
  ('34aee1f0-16','{"options": ["It inhibits acetylcholinesterase", "It blocks M3 only on the sphincter", "It relaxes the ciliary muscle directly", "α1 agonist; ciliary muscle has no α1"], "correct": 3, "decode": "Phenylephrine acts on sympathetic α1 (dilator); the ciliary muscle is purely M3, so accommodation is spared.", "ow": ["It does not inhibit acetylcholinesterase.", "Blocking M3 on the sphincter describes an antimuscarinic, not phenylephrine.", "It does not directly relax the ciliary muscle.", "Correct. α1 agonist on the dilator; ciliary muscle has no α1."]}'),
  ('96241892-18','{"options": ["Cyclopentolate 1%", "Phenylephrine 10%", "Tropicamide 0.5%", "Atropine 1%"], "correct": 2, "decode": "In pregnancy the preferred dilator is TROPICAMIDE 0.5%: shortest duration and least systemic exposure (all DPAs are Category C).", "ow": ["Cyclopentolate 1% has longer duration and more systemic exposure.", "Phenylephrine 10% carries cardiovascular risk.", "Correct. Tropicamide 0.5% is preferred in pregnancy.", "Atropine 1% is long-acting and not used routinely."]}'),
  ('0537bbed-2k','{"options": ["Reduce systemic drug absorption", "Speed onset", "Reduce stinging", "Stop the drug working on the eye"], "correct": 0, "decode": "Nasolacrimal occlusion blocks drainage down the nasolacrimal duct, REDUCING systemic drug absorption.", "ow": ["Correct. NLO limits systemic absorption.", "It does not speed onset.", "It does not primarily reduce stinging.", "It keeps the drug on the eye rather than stopping its ocular effect."]}'),
  ('e839e974-29','{"options": ["Fluorescein", "Proparacaine", "Phenylephrine", "Tropicamide"], "correct": 1, "decode": "PROPARACAINE is office-only: chronic use abolishes corneal sensation and masks damage (neurotrophic keratopathy).", "ow": ["Fluorescein is a dye, safe to use and not sensation-abolishing.", "Correct. Proparacaine masks corneal damage; never for home use.", "Phenylephrine is a mydriatic, not an anesthetic.", "Tropicamide is a mydriatic, not an anesthetic."]}'),
  ('f08196a1-1k','{"options": ["Soft contact lenses", "Rigid gas-permeable lenses", "An eye patch", "Spectacles"], "correct": 0, "decode": "Fluorescein permanently stains SOFT (hydrogel) lenses, so remove them first.", "ow": ["Correct. Fluorescein stains soft lenses.", "RGP lenses are not hydrogel and are not permanently stained.", "An eye patch is not stained by fluorescein.", "Spectacles are unaffected by fluorescein."]}'),
  ('8183bef0-1k','{"options": ["Narrow / angle-closure glaucoma", "Dry eye", "Hypertension", "Open-angle glaucoma"], "correct": 0, "decode": "All mydriatics share one absolute contraindication: NARROW / ANGLE-CLOSURE glaucoma (dilation can trigger acute closure).", "ow": ["Correct. Avoid mydriatics in narrow/angle-closure glaucoma.", "Dry eye is not an absolute contraindication.", "Hypertension is not the absolute mydriatic contraindication.", "Open-angle glaucoma is not an absolute contraindication to dilation."]}'),
  ('bd5e1a89-2b','{"options": ["Tropicamide", "Cyclopentolate", "Proparacaine", "Phenylephrine"], "correct": 1, "decode": "CYCLOPENTOLATE is the strongest routine cycloplegic for pediatric refraction (atropine is stronger but not a routine DPA).", "ow": ["Tropicamide is a weaker cycloplegic than cyclopentolate.", "Correct. Cyclopentolate is the strongest routine cycloplegic.", "Proparacaine is an anesthetic, not a cycloplegic.", "Phenylephrine has no cycloplegic effect."]}'),
  ('fb20e0b2-1e','{"options": ["Constricting conjunctival vessels", "Blocking M3 so the sphincter relaxes", "Stimulating α1 on the dilator muscle", "Inhibiting acetylcholinesterase"], "correct": 1, "decode": "Tropicamide and cyclopentolate BLOCK M3 so the sphincter relaxes; the unopposed dilator opens the pupil (and the ciliary muscle relaxes = cycloplegia).", "ow": ["They do not constrict conjunctival vessels.", "Correct. M3 block relaxes the sphincter, dilating the pupil.", "α1 stimulation on the dilator is phenylephrine''s mechanism, not theirs.", "They do not inhibit acetylcholinesterase."]}'),
  ('518b394f-l','{"options": ["Blocking sodium channels", "Fluorescing under blue light", "Blocking M3 receptors", "Stimulating α1 receptors"], "correct": 0, "decode": "Proparacaine BLOCKS SODIUM CHANNELS (ester anesthetic), giving rapid, short anesthesia.", "ow": ["Correct. Proparacaine blocks Na+ channels.", "Fluorescing under blue light is fluorescein, not proparacaine.", "M3 block is an antimuscarinic mechanism, not proparacaine.", "α1 stimulation is phenylephrine''s mechanism."]}'),
  ('91b26006-19','{"options": ["Infrared", "Cobalt blue", "Red-free light", "White light"], "correct": 1, "decode": "Fluorescein absorbs blue (~465 nm) and emits green, so it fluoresces best under COBALT BLUE.", "ow": ["Infrared does not excite fluorescein.", "Correct. Cobalt blue (~465 nm) excites fluorescein.", "Red-free light is for viewing vessels/nerve fiber layer, not fluorescein excitation.", "White light does not maximize fluorescence."]}'),
  ('7b3978ad-14','{"options": ["3", "5", "7", "10"], "correct": 1, "decode": "RA 8050 approves 5 DPAs: phenylephrine, tropicamide, cyclopentolate, proparacaine, fluorescein.", "ow": ["3 undercounts the approved DPAs.", "Correct. Five approved DPAs.", "7 overcounts them.", "10 overcounts them."]}'),
  ('e72a2358-1r','{"options": ["Photokeratitis", "Bradycardia", "Dry eye", "CNS toxicity"], "correct": 3, "decode": "Cyclopentolate 2% in a young child risks CNS TOXICITY (immature liver, CNS penetration); use 0.5 to 1% with NLO.", "ow": ["Photokeratitis is a UV injury, not a cyclopentolate effect.", "Bradycardia is not the classic cyclopentolate toxicity.", "Dry eye is not the concern here.", "Correct. Cyclopentolate 2% in kids risks CNS toxicity."]}'),
  ('1b2baf80-1o','{"options": ["3–4 months", "1 month", "2 years", "9 months"], "correct": 0, "decode": "An infant''s eyes should be consistently straight by 3 to 4 months; deviation beyond this warrants evaluation.", "ow": ["Correct. Straight by 3 to 4 months.", "1 month is too early to require stable alignment.", "2 years is far too late for the expected milestone.", "9 months is later than the expected milestone."]}'),
  ('9c840101-1j','{"options": ["Preferential looking", "HOTV", "Ishihara", "Snellen chart"], "correct": 0, "decode": "Non-verbal infants are tested with PREFERENTIAL LOOKING (Teller cards): gaze preference for a grating.", "ow": ["Correct. Preferential looking suits non-verbal infants.", "HOTV needs a cooperative preschooler.", "Ishihara tests color, not infant acuity.", "A Snellen chart needs letter naming."]}'),
  ('46b526b3-1k','{"options": ["Snellen letter chart", "HOTV or Lea Symbols", "Pelli-Robson chart", "Teller acuity cards"], "correct": 1, "decode": "Cooperative 3 to 5 year olds use matching/picture tests: HOTV or LEA SYMBOLS.", "ow": ["A Snellen letter chart needs reading ability.", "Correct. HOTV or Lea Symbols suit preschoolers.", "Pelli-Robson tests contrast sensitivity, not preschool acuity.", "Teller cards are for pre-verbal infants."]}'),
  ('89cf2148-18','{"options": ["Deprivation", "Anisometropic", "Meridional", "Strabismic"], "correct": 0, "decode": "DEPRIVATION amblyopia (cataract, ptosis) has the WORST prognosis and must be treated within the critical period.", "ow": ["Correct. Deprivation amblyopia has the worst prognosis.", "Anisometropic amblyopia has a better prognosis.", "Meridional amblyopia is milder.", "Strabismic amblyopia is more treatable than deprivation."]}'),
  ('99ce2bab-15','{"options": ["Full spectacle correction", "Early strabismus surgery", "Atropine penalization", "Immediate part-time patching"], "correct": 0, "decode": "The first step in amblyopia is FULL SPECTACLE CORRECTION; patching is added only if VA does not normalize with glasses.", "ow": ["Correct. Refract and give full correction first.", "Surgery is not the first amblyopia step.", "Atropine penalization is a second-line alternative, not the first step.", "Patching is added only after glasses fail."]}'),
  ('dc1e4518-1o','{"options": ["Symmetric, centered Hirschberg reflexes", "An RAPD", "A positive cover test", "Asymmetric Hirschberg reflexes"], "correct": 0, "decode": "Pseudostrabismus shows SYMMETRIC, CENTERED Hirschberg reflexes, confirming no true deviation.", "ow": ["Correct. Symmetric corneal reflexes confirm pseudostrabismus.", "An RAPD is an afferent defect, not pseudostrabismus.", "A positive cover test would indicate a true deviation.", "Asymmetric reflexes indicate a true deviation, not pseudostrabismus."]}'),
  ('c6a8c390-1e','{"options": ["Patching the sound eye", "Base-out prism at near", "Early strabismus surgery", "Full hyperopic correction"], "correct": 3, "decode": "Accommodative esotropia is first managed with FULL HYPEROPIC (cycloplegic plus) correction, removing the accommodative drive.", "ow": ["Patching treats amblyopia, not the accommodative eso itself first.", "Base-out prism is not the first management.", "Surgery is reserved for residual deviation after full plus.", "Correct. Full hyperopic correction first."]}'),
  ('1d91a785-1x','{"options": ["Open lifelong, never closes", "Peaks 1–3, closes at 7–8", "Peaks 5–7, closes at 15", "Peaks at 2, closes at 4"], "correct": 1, "decode": "The amblyopia critical period PEAKS at 1 to 3 years and largely closes by 7 to 8.", "ow": ["It does close; it is not open lifelong.", "Correct. Peaks 1 to 3, closes 7 to 8.", "It closes earlier than 15.", "It peaks later than 2 and closes later than 4."]}'),
  ('444bd0c0-2p','{"options": ["Anisometropic amblyopia; correct first", "Deprivation amblyopia; operate", "Strabismic amblyopia; patch now", "Pseudoamblyopia; simply reassure"], "correct": 0, "decode": "A large hyperopic difference with reduced VA in the worse eye is ANISOMETROPIC amblyopia; CORRECT FIRST, add patching if needed.", "ow": ["Correct. Anisometropic amblyopia; correct first.", "Deprivation implies a media opacity, not a refractive difference.", "There is no manifest deviation described, so strabismic is less likely; correct first anyway.", "The reduced VA is real amblyopia, not pseudoamblyopia."]}'),
  ('294f4fc6-u','{"options": ["Only after strabismus surgery", "Only if glasses alone fail", "It is never indicated", "Always as the very first step"], "correct": 1, "decode": "Patching is added only IF GLASSES ALONE FAIL to normalize VA (after ~12 to 16 weeks).", "ow": ["Patching is not tied to prior surgery.", "Correct. Patch only if glasses alone fail.", "Patching is indicated when needed, not never.", "Full correction, not patching, is the first step."]}'),
  ('f26621a3-25','{"options": ["Age 20", "Age 12", "Age 5", "Age 40"], "correct": 1, "decode": "Amblyopia improvement is still possible up to about age 12 (less effective after 7).", "ow": ["Age 20 is beyond the useful treatment window.", "Correct. Some gain remains possible to ~12.", "Age 5 understates the window; gains continue past this.", "Age 40 is far beyond the treatable window."]}'),
  ('6a3319ff-1f','{"options": ["Deprivation amblyopia", "Infantile esotropia", "Pseudostrabismus", "Accommodative esotropia"], "correct": 2, "decode": "PSEUDOSTRABISMUS needs no treatment, only reassurance; it resolves with facial growth.", "ow": ["Deprivation amblyopia requires active treatment.", "Infantile esotropia requires management.", "Correct. Pseudostrabismus needs only reassurance.", "Accommodative esotropia requires correction."]}'),
  ('cfabe467-1r','{"options": ["85% dry / 15% wet", "15% dry / 85% wet", "50% / 50%", "All dry"], "correct": 0, "decode": "AMD is about 85% DRY (atrophic) and 15% WET.", "ow": ["Correct. 85% dry, 15% wet.", "This reverses the proportions.", "It is not an even split.", "Wet AMD also exists, so ''all dry'' is wrong."]}'),
  ('74633e97-1n','{"options": ["Neither", "Both equally", "Wet", "Dry"], "correct": 2, "decode": "WET AMD (choroidal neovascularization), though less common, causes the MAJORITY of severe vision loss.", "ow": ["One type does dominate severe loss, so ''neither'' is wrong.", "They do not contribute equally to severe loss.", "Correct. Wet AMD causes most severe vision loss.", "Dry AMD is common but causes slow, less severe loss."]}'),
  ('d782157a-i','{"options": ["Reduce progression to advanced AMD", "Treat and clear cataract", "Cure established wet AMD", "Reverse existing AMD damage"], "correct": 0, "decode": "AREDS2 supplements REDUCE PROGRESSION to advanced AMD (~25%); they do not treat or reverse disease.", "ow": ["Correct. AREDS2 reduces progression risk.", "They do not treat or clear cataract.", "They do not cure wet AMD.", "They do not reverse existing damage."]}'),
  ('1dc10b31-2e','{"options": ["Grade 4", "Grade 1", "Grade 2", "Grade 3"], "correct": 2, "decode": "AV NICKING is Keith-Wagener-Barker GRADE 2.", "ow": ["Grade 4 is papilledema.", "Grade 1 is arteriolar narrowing.", "Correct. AV nicking is grade 2.", "Grade 3 is hemorrhages and exudates."]}'),
  ('78e325ab-1a','{"options": ["Copper wiring", "AV nicking", "Flame hemorrhages only", "Papilledema"], "correct": 3, "decode": "Grade 4 hypertensive retinopathy is defined by PAPILLEDEMA (malignant hypertension, an emergency).", "ow": ["Copper wiring is a lower-grade change.", "AV nicking is grade 2.", "Flame hemorrhages alone are grade 3.", "Correct. Papilledema marks grade 4."]}'),
  ('cc764f1e-1r','{"options": ["Vitreous hemorrhage", "Proliferative DR neovascularization", "Diabetic macular edema", "Cataract"], "correct": 2, "decode": "DIABETIC MACULAR EDEMA is the most common cause of vision loss in diabetic retinopathy (any DR stage).", "ow": ["Vitreous hemorrhage occurs in proliferative disease but is not the commonest cause.", "PDR neovascularization is not the commonest cause of vision loss.", "Correct. Diabetic macular edema is the most common cause.", "Cataract is not the DR-specific cause."]}'),
  ('aa29548a-n','{"options": ["Cycloplegics", "AREDS2 only", "Laser iridotomy", "Intravitreal anti-VEGF"], "correct": 3, "decode": "Wet AMD is treated with INTRAVITREAL ANTI-VEGF (bevacizumab, ranibizumab, aflibercept).", "ow": ["Cycloplegics do not treat AMD.", "AREDS2 slows progression but does not treat active wet AMD.", "Laser iridotomy is for angle-closure glaucoma.", "Correct. Anti-VEGF is first-line for wet AMD."]}'),
  ('9874d915-23','{"options": ["Calcified", "Soft, large, confluent", "Hard, small, discrete", "None"], "correct": 1, "decode": "SOFT, LARGE, CONFLUENT drusen carry the highest risk of progression to advanced AMD.", "ow": ["Calcified drusen are not the highest-risk type here.", "Correct. Soft, large, confluent drusen carry the highest risk.", "Hard, small, discrete drusen are low risk.", "There is a highest-risk type, so ''none'' is wrong."]}'),
  ('13696f13-29','{"options": ["1 mm of the disc", "The whole posterior pole", "2 disc diameters", "500 µm of the fovea"], "correct": 3, "decode": "CSME is retinal thickening (or hard exudates with thickening) within 500 µm of the FOVEA.", "ow": ["1 mm of the disc is not the CSME criterion.", "The whole posterior pole is too broad.", "2 disc diameters is not the CSME threshold.", "Correct. Within 500 µm of the fovea."]}'),
  ('e9d1ae80-2p','{"options": ["Dry AMD", "Wet AMD", "Cataract", "Glaucoma"], "correct": 1, "decode": "Sudden metamorphopsia with subretinal fluid and hemorrhage in an elderly patient is WET AMD until proven otherwise.", "ow": ["Dry AMD progresses gradually, without acute subretinal blood.", "Correct. Acute distortion plus subretinal blood is wet AMD.", "Cataract does not cause acute metamorphopsia with subretinal blood.", "Glaucoma does not cause central metamorphopsia."]}'),
  ('5ab006e8-1i','{"options": ["3:1", "1:4", "2:3", "1:1"], "correct": 2, "decode": "The normal retinal A:V caliber ratio is about 2:3 (arteries narrower than veins).", "ow": ["3:1 would make arteries much wider than veins.", "1:4 is too extreme.", "Correct. Normal A:V is ~2:3.", "1:1 would make them equal."]}'),
  ('195f06e5-1u','{"options": ["ISNT rule", "ABCD rule", "20-20-20 rule", "4-2-1 rule"], "correct": 3, "decode": "Severe NPDR is identified by the 4-2-1 RULE: hemorrhages in 4 quadrants, OR venous beading in 2, OR IRMA in 1.", "ow": ["The ISNT rule is for the optic disc rim, not NPDR staging.", "The ABCD rule is for melanoma/nevi.", "The 20-20-20 rule is for computer vision syndrome.", "Correct. Severe NPDR uses the 4-2-1 rule."]}'),
  ('a3a10bf0-24','{"options": ["Ocular myasthenia gravis", "Ophthalmoplegic migraine", "Diabetic microvascular palsy", "A communicating artery aneurysm"], "correct": 3, "decode": "A PUPIL-INVOLVING CN3 palsy suggests a COMMUNICATING ARTERY ANEURYSM (pupillomotor fibers run on the outside of CN3).", "ow": ["Ocular myasthenia spares the pupil.", "Ophthalmoplegic migraine is a diagnosis of exclusion, not the emergency here.", "A diabetic microvascular palsy is classically pupil-SPARING.", "Correct. Pupil-involving CN3 = compressive aneurysm."]}'),
  ('adf7b2f4-1o','{"options": ["It only ever occurs in the pons", "It is congenital in all cases", "It does not cause diplopia", "Raised ICP compresses its long course"], "correct": 3, "decode": "CN6 palsy is a ''false localizing sign'' because RAISED ICP compresses its long intracranial course anywhere.", "ow": ["It is not confined to pontine lesions.", "It is not congenital in all cases.", "It does cause diplopia.", "Correct. Raised ICP stretches its long course, so it poorly localizes."]}'),
  ('5d759796-1p','{"options": ["Rotary in all gaze positions", "Horizontal, dampens on convergence", "Present only on upgaze", "Vertical in all gaze positions"], "correct": 1, "decode": "Infantile (congenital) nystagmus is HORIZONTAL in all gaze and DAMPENS on convergence.", "ow": ["It is horizontal, not rotary in all positions.", "Correct. Horizontal, dampens on convergence.", "It is present in all gaze, not only upgaze.", "Vertical nystagmus is always acquired, not INS."]}'),
  ('13d09eaa-l','{"options": ["Always congenital", "Always acquired", "Normal in infants", "A sign of refractive error"], "correct": 1, "decode": "VERTICAL nystagmus is ALWAYS ACQUIRED and warrants neurological workup.", "ow": ["It is acquired, not congenital.", "Correct. Vertical nystagmus is always acquired.", "It is not a normal infant finding.", "It is not a sign of refractive error."]}'),
  ('4633eeb7-1r','{"options": ["Using strong cycloplegia", "Dimming the room lights", "Fogging with a +5.00 lens", "Patching one eye fully"], "correct": 2, "decode": "Latent nystagmus is handled during monocular VA testing by FOGGING with a +5.00 lens (occlusion triggers it).", "ow": ["Strong cycloplegia does not prevent latent nystagmus.", "Dimming the lights does not control it.", "Correct. Fog with +5.00 to keep both eyes open.", "Patching triggers the latent nystagmus."]}'),
  ('2680c247-1l','{"options": ["Perinatal hypoxia-ischemia", "Glaucoma", "Refractive error", "Cataract"], "correct": 0, "decode": "Cortical visual impairment is most commonly caused by PERINATAL HYPOXIA-ISCHEMIA; the eyes are structurally normal.", "ow": ["Correct. CVI follows perinatal hypoxic-ischemic injury.", "Glaucoma is an ocular, not cortical, cause.", "Refractive error does not cause CVI.", "Cataract is an ocular media problem, not CVI."]}'),
  ('df61cedb-w','{"options": ["Cataract", "Optic atrophy", "Structurally normal eyes", "Retinal detachment"], "correct": 2, "decode": "In CVI the eye examination shows STRUCTURALLY NORMAL eyes (the problem is cortical).", "ow": ["Cataract is not a CVI finding.", "Optic atrophy is not the CVI picture.", "Correct. CVI eyes are structurally normal.", "Retinal detachment is not a CVI finding."]}'),
  ('a539f618-1v','{"options": ["On upgaze", "On lateral gaze only", "On downgaze", "At distance only"], "correct": 2, "decode": "A CN4 (superior oblique) palsy causes vertical diplopia WORST ON DOWNGAZE (and reading).", "ow": ["It is worst on downgaze, not upgaze.", "It is not limited to lateral gaze.", "Correct. Worst on downgaze.", "It is not a distance-only phenomenon."]}'),
  ('26f371df-1d','{"options": ["Away from the affected eye", "No abnormal head posture", "Chin up, face turned", "Toward the affected eye"], "correct": 0, "decode": "In CN4 palsy the head tilts AWAY from the affected eye (and chin down) to reduce the vertical deviation.", "ow": ["Correct. Head tilt away from the affected side.", "There is a compensatory posture, so ''none'' is wrong.", "Chin up worsens, not relieves, the deviation.", "Tilting toward the affected eye worsens the diplopia."]}'),
  ('dded33a4-1w','{"options": ["Maddox rod test", "Parks-Bielschowsky test", "Hirschberg reflex test", "Worth 4-dot test"], "correct": 1, "decode": "The PARKS-BIELSCHOWSKY 3-step test localizes a cyclovertical muscle palsy (commonly CN4/SO).", "ow": ["The Maddox rod measures the deviation, not the 3-step localization.", "Correct. Parks-Bielschowsky is the cyclovertical 3-step test.", "Hirschberg estimates deviation by reflex, not the 3-step.", "Worth 4-dot tests fusion/suppression."]}'),
  ('fd3bffb1-1l','{"options": ["Null point", "Fast phase", "Convergence", "Slow phase"], "correct": 1, "decode": "Jerk nystagmus is named for the direction of its FAST PHASE.", "ow": ["The null point is where nystagmus is least, not how it is named.", "Correct. Jerk nystagmus is named for the fast phase.", "Convergence is not how it is named.", "The slow phase is the drift, not the naming direction."]}'),
  ('4a7e5c1a-37','{"options": ["Cortical visual impairment", "Latent nystagmus", "Infantile esotropia", "Congenital cataract"], "correct": 0, "decode": "PVL on MRI, normal-looking eyes, and poor visual responses = CORTICAL VISUAL IMPAIRMENT.", "ow": ["Correct. Neurological insult plus normal eyes plus poor vision is CVI.", "Latent nystagmus does not fit PVL with poor responses.", "Infantile esotropia is a motor deviation, not this picture.", "Congenital cataract would show a media opacity, not normal eyes."]}'),
  ('c6a4864c-1m','{"options": ["Identifying the chemical, then irrigating", "Instilling proparacaine and referring without irrigation", "Immediate irrigation with water/saline for 20–30 minutes", "Applying a bandage contact lens"], "correct": 2, "decode": "A chemical splash is managed by IMMEDIATE IRRIGATION with water/saline for 20 to 30 minutes; history follows.", "ow": ["Identify the chemical AFTER starting irrigation, not before.", "Do not delay irrigation to instill anesthetic and refer.", "Correct. Irrigate immediately for 20 to 30 minutes.", "A bandage lens is not the first action."]}'),
  ('50636e1a-1g','{"options": ["20 hours, 20 breaks, 20 days", "20 lux, 20 inches, 20 minutes", "20 blinks every 20 seconds", "Every 20 min, 20 feet, 20 sec"], "correct": 3, "decode": "The CVS ''20-20-20 rule'': every 20 minutes, look ~20 feet away for 20 seconds to relax accommodation.", "ow": ["''20 hours, 20 breaks, 20 days'' is not the rule.", "''20 lux, 20 inches, 20 minutes'' is not the rule.", "''20 blinks every 20 seconds'' is not the rule.", "Correct. Every 20 min, 20 feet, 20 sec."]}'),
  ('584226fc-1l','{"options": ["105 days", "120 days", "78 days", "60 days"], "correct": 0, "decode": "Under RA 11210 (2019), the Expanded Maternity Leave Law, maternity leave is 105 days.", "ow": ["Correct. RA 11210 gives 105 days.", "120 days is not the RA 11210 figure.", "78 days was the old pre-2019 allowance.", "60 days is not the current entitlement."]}'),
  ('21062e3d-w','{"options": ["14 days", "7 working days", "30 days", "3 days"], "correct": 1, "decode": "Paternity leave under RA 8187 is 7 working days.", "ow": ["14 days is not the RA 8187 figure.", "Correct. 7 working days.", "30 days is not the RA 8187 figure.", "3 days is not the RA 8187 figure."]}'),
  ('14babdbb-1j','{"options": ["High-index glass", "Polycarbonate", "Crown glass", "CR-39"], "correct": 1, "decode": "POLYCARBONATE is the most impact-resistant material, the choice for protective (safety) eyewear.", "ow": ["High-index glass is not the safety choice.", "Correct. Polycarbonate is the safety-eyewear material.", "Crown glass is brittle.", "CR-39 is less impact resistant than polycarbonate."]}'),
  ('87980a04-19','{"options": ["Retinal burns", "Photokeratitis from UV", "Cataract from infrared", "Glaucoma"], "correct": 1, "decode": "Arc welding UV exposure classically causes PHOTOKERATITIS.", "ow": ["Retinal burns are from intense visible/laser sources, not the classic welding injury.", "Correct. UV causes photokeratitis (welder''s flash).", "Cataract from infrared is the glassblower''s injury, not welding UV.", "Glaucoma is unrelated to welding exposure."]}'),
  ('eed69f68-1x','{"options": ["Evaporative dry eye", "Loss of color vision", "Thermal IR cataract", "Acute photokeratitis"], "correct": 2, "decode": "Infrared occupational exposure (glassblowing) classically causes a THERMAL IR CATARACT (posterior subcapsular).", "ow": ["Evaporative dry eye is not the classic IR injury.", "Loss of color vision is not the IR effect.", "Correct. IR causes thermal damage and IR cataract.", "Acute photokeratitis is a UV, not IR, injury."]}'),
  ('8a0520c4-2k','{"options": ["PRC", "DTI", "DOLE", "DOH"], "correct": 2, "decode": "The Occupational Safety and Health Standards (OSHS) are administered by DOLE.", "ow": ["The PRC handles professional licensure, not OSHS.", "The DTI handles trade and industry, not OSHS.", "Correct. OSHS falls under DOLE.", "The DOH handles health, not workplace safety standards."]}'),
  ('1371693a-1l','{"options": ["Never", "In addition to sealed splash goggles", "Only if goggles are unavailable", "Instead of goggles"], "correct": 1, "decode": "For a chemical splash hazard, a face shield is used IN ADDITION TO sealed splash goggles (it does not seal the eyes).", "ow": ["It is used, not never.", "Correct. Face shield plus sealed splash goggles.", "It is not only a fallback for missing goggles.", "It is used with goggles, not instead of them."]}'),
  ('981b8996-1s','{"options": ["Anti-reflection coated lenses", "The 20-20-20 rule", "Daily home cycloplegic drops", "Task-specific near correction"], "correct": 2, "decode": "DAILY HOME CYCLOPLEGIC DROPS are NOT appropriate for CVS (cycloplegics are diagnostic agents only).", "ow": ["Anti-reflection lenses are appropriate for CVS.", "The 20-20-20 rule is appropriate.", "Correct. Daily home cycloplegics are never appropriate.", "Task-specific near correction is appropriate."]}'),
  ('d8bd00ec-13','{"options": ["GSIS = government; SSS = private", "Both private", "Both government", "GSIS = private; SSS = government"], "correct": 0, "decode": "GSIS covers GOVERNMENT workers; SSS covers the PRIVATE sector.", "ow": ["Correct. GSIS government; SSS private.", "They do not both cover the private sector.", "They do not both cover government.", "This reverses GSIS and SSS."]}'),
  ('7abf4dbd-1z','{"options": ["Accommodative facility only", "Visual fields and color vision", "Tonometry only", "Stereoacuity only"], "correct": 1, "decode": "A professional driver''s occupational eye exam must include VISUAL FIELDS and COLOR VISION (for signals).", "ow": ["Accommodative facility alone is not the driver-specific requirement.", "Correct. Drivers need visual fields and color vision.", "Tonometry alone is not the driver-specific requirement.", "Stereoacuity alone is not the driver-specific requirement."]}'),
  ('ced56b88-1p','{"options": ["Gray", "Blue", "Dark green", "Yellow"], "correct": 3, "decode": "YELLOW tint best improves visibility in fog, haze, and low light by cutting blue scatter.", "ow": ["Gray is neutral density and does not lift contrast.", "Blue does not enhance haze contrast.", "Dark green does not lift low-light contrast like yellow.", "Correct. Yellow enhances contrast in fog/haze/low light."]}'),
  ('fa36f98f-1o','{"options": ["Gray", "Brown or amber", "Clear", "Blue"], "correct": 1, "decode": "BROWN or AMBER tints (with a red element) best enhance depth perception for golf/tennis.", "ow": ["Gray is neutral density and does not enhance depth.", "Correct. Brown/amber enhance contrast and depth.", "Clear adds no contrast benefit.", "Blue does not enhance depth judgment."]}'),
  ('5900e11b-w','{"options": ["A contrast-enhancing filter", "A blue blocker", "A neutral density filter", "A polarizer"], "correct": 2, "decode": "A GRAY tint is a NEUTRAL DENSITY filter: it dims without changing color balance or improving contrast.", "ow": ["It does not enhance contrast.", "It is not a blue blocker.", "Correct. Gray is a neutral density filter.", "It is not a polarizer."]}'),
  ('01aaef10-2d','{"options": ["Contrast sensitivity", "Dynamic visual acuity", "Color vision", "Stereopsis"], "correct": 1, "decode": "Trouble tracking a fast ball despite 20/20 static VA indicates a DYNAMIC VISUAL ACUITY deficit.", "ow": ["Contrast sensitivity is a separate function, not the tracking issue.", "Correct. Moving-target trouble points to dynamic VA.", "Color vision is unrelated to tracking a ball.", "Stereopsis is depth, not moving-target resolution."]}'),
  ('939620ab-1b','{"options": ["Ishihara plates", "Tachistoscope or Marsden ball", "Pelli-Robson chart", "Stereo Fly"], "correct": 1, "decode": "Dynamic visual acuity is assessed with a TACHISTOSCOPE or MARSDEN BALL.", "ow": ["Ishihara plates test color, not dynamic VA.", "Correct. Tachistoscope or Marsden ball assesses dynamic VA.", "Pelli-Robson tests contrast sensitivity.", "The Stereo Fly tests stereopsis."]}'),
  ('20f28b3e-17','{"options": ["Accommodative facility", "Color discrimination", "Peripheral visual fields", "Eye-hand reaction time"], "correct": 3, "decode": "The Wayne Saccadic Fixator trains EYE-HAND REACTION TIME (and peripheral awareness).", "ow": ["It does not train accommodative facility.", "It does not train color discrimination.", "It does not train peripheral fields per se.", "Correct. It trains eye-hand coordination and reaction speed."]}'),
  ('b9544b79-1m','{"options": ["Snellen chart", "Pelli-Robson chart", "Hirschberg", "Worth 4-dot"], "correct": 1, "decode": "Contrast sensitivity is measured with the PELLI-ROBSON chart.", "ow": ["The Snellen chart measures acuity, not contrast.", "Correct. Pelli-Robson measures contrast sensitivity.", "Hirschberg estimates ocular deviation.", "Worth 4-dot tests fusion/suppression."]}'),
  ('7a6c7423-1t','{"options": ["Cycling", "Racquet sports", "All sports", "Swimming"], "correct": 1, "decode": "The ASTM F803 protective-eyewear standard applies to RACQUET SPORTS.", "ow": ["Cycling eyewear falls under other standards.", "Correct. F803 governs racquet-sport protectors.", "It is not an all-sports standard.", "Swimming goggles fall under other standards."]}'),
  ('d30e41b6-1n','{"options": ["They give impact protection", "They give UV protection only", "Yes, they fully protect", "Neither; eyewear is needed"], "correct": 3, "decode": "Contact lenses provide NEITHER impact nor UV protection sufficient for sport; protective eyewear is still needed.", "ow": ["They do not give impact protection.", "They do not substitute for UV-protective eyewear in sport.", "They do not fully protect the eye.", "Correct. CLs give no protection; eyewear is still needed."]}'),
  ('dc3a38b6-1m','{"options": ["Ultraviolet protection", "Refractive accuracy", "Dynamic VA and depth", "Contact lens fit"], "correct": 2, "decode": "A static 20/20 does NOT guarantee good DYNAMIC VA and DEPTH (they are independent of static VA).", "ow": ["UV protection is unrelated to static VA.", "Refractive accuracy is separate but not the point about sports performance.", "Correct. 20/20 static does not guarantee dynamic VA or depth.", "Contact lens fit is unrelated to static VA."]}'),
  ('859f51c9-1l','{"options": ["High-index glass", "Glass", "Polycarbonate", "CR-39"], "correct": 2, "decode": "POLYCARBONATE is the best protective lens material for athletes (impact resistance).", "ow": ["High-index glass is not the sports-protection choice.", "Glass is brittle and unsafe for sport.", "Correct. Polycarbonate is the sports-protection standard.", "CR-39 is less impact resistant."]}'),
  ('e9273081-17','{"options": ["Pursuit and tracking", "Color discrimination", "Peripheral visual fields", "Intraocular pressure"], "correct": 0, "decode": "The Marsden ball trains and tests PURSUIT and TRACKING (dynamic VA).", "ow": ["Correct. The Marsden ball trains pursuit tracking.", "It does not test color discrimination.", "It does not test peripheral fields.", "It does not measure intraocular pressure."]}'),
  ('179577ec-2e','{"options": ["20/40", "20/70", "20/200", "20/400"], "correct": 1, "decode": "WHO LOW VISION is best-corrected acuity in the better eye worse than 20/70.", "ow": ["20/40 is better than the low-vision threshold.", "Correct. Low vision is worse than 20/70.", "20/200 is the blindness threshold, not low vision.", "20/400 is deeper than the low-vision cutoff."]}'),
  ('6dc34830-25','{"options": ["20/200 or worse", "20/100 or worse", "20/70 or worse", "20/400 or worse"], "correct": 0, "decode": "WHO BLINDNESS is best-corrected acuity in the better eye of 20/200 or worse.", "ow": ["Correct. Blindness is 20/200 or worse.", "20/100 is worse than low vision but not the blindness cutoff.", "20/70 is the low-vision threshold.", "20/400 is deeper than the blindness threshold, which starts at 20/200."]}'),
  ('dfac8f50-1p','{"options": ["4 D = 1×", "10 D = 1×", "1 D = 1×", "2 D = 1×"], "correct": 0, "decode": "The magnification reference standard is 4 D = 1×, so equivalent add = M × 4.", "ow": ["Correct. 4 D = 1×.", "10 D = 1× is not the reference.", "1 D = 1× is not the reference.", "2 D = 1× is not the reference."]}'),
  ('f1c43e83-13','{"options": ["4 / Present VA", "Required VA / Present VA", "Present VA / Required VA", "Present VA × Required VA"], "correct": 1, "decode": "Formula: required magnification M = required VA / present VA.", "ow": ["4 / present VA is not the magnification formula.", "Correct. M = required VA / present VA.", "This inverts the ratio.", "Multiplying the two acuities is not the formula."]}'),
  ('b6d9c161-21','{"options": ["3×, +12 D", "2×, +12 D", "4×, +16 D", "2×, +8 D"], "correct": 2, "decode": "Formula: M = required VA / present VA; equivalent add = M × 4. Steps: M = N32 / N8 = 32/8 = 4×; add = 4 × 4 = +16 D (working distance 100/16 ≈ 6.25 cm).", "ow": ["3×, +12 D uses the wrong ratio.", "2×, +12 D uses the wrong ratio.", "Correct. 32/8 = 4×, and 4 × 4 = +16 D.", "2×, +8 D uses the wrong ratio."]}'),
  ('b95a47b6-13','{"options": ["Pinhole VA", "Uncorrected VA", "Near point only", "Best-corrected VA"], "correct": 3, "decode": "Magnification is calculated from BEST-CORRECTED VA (refract first).", "ow": ["Pinhole VA is not the basis.", "Uncorrected VA overestimates the need.", "Near point alone is not the basis.", "Correct. Use best-corrected VA."]}'),
  ('e57c0b91-14','{"options": ["Treat only those above 20/200", "Maximize function for the task", "Restore 20/20 acuity", "Replace glasses with a magnifier"], "correct": 1, "decode": "The goal of low vision rehabilitation is to MAXIMIZE FUNCTION for the task, not restore 20/20.", "ow": ["Care is not limited to those above 20/200.", "Correct. Maximize functional use of remaining vision.", "Restoring 20/20 is not the goal.", "It is not simply swapping glasses for a magnifier."]}'),
  ('bd9bdc92-19','{"options": ["Only AMD", "Color deficiency", "Peripheral field loss", "Any central scotoma"], "correct": 3, "decode": "Eccentric viewing training is appropriate for ANY CENTRAL SCOTOMA (using a healthier retinal area).", "ow": ["It is not limited to AMD.", "It does not address color deficiency.", "It addresses central, not peripheral, field loss.", "Correct. It helps any central scotoma."]}'),
  ('774eebd6-28','{"options": ["Pocket loupe", "Telescope", "Hand-held magnifier", "Stand magnifier"], "correct": 3, "decode": "For a hand tremor needing sustained reading, the best magnifier is a STAND MAGNIFIER (fixed on the page).", "ow": ["A pocket loupe still requires a steady hand.", "A telescope is for distance, not sustained reading.", "A hand-held magnifier is unstable with tremor.", "Correct. A stand magnifier avoids tremor instability."]}'),
  ('4daaac8f-16','{"options": ["Distance tasks", "Color enhancement", "Peripheral field expansion", "Near reading"], "correct": 0, "decode": "Telescopes in low vision are primarily for DISTANCE tasks.", "ow": ["Correct. Telescopes serve distance tasks.", "They do not enhance color.", "They magnify, they do not expand the peripheral field.", "Near reading is served by adds/magnifiers, not telescopes first."]}'),
  ('931ffab5-1b','{"options": ["Trachoma", "Diabetic retinopathy", "Cataract", "Glaucoma"], "correct": 2, "decode": "CATARACT is the most common cause of blindness worldwide (and >80% of blindness is avoidable).", "ow": ["Trachoma is a major but not the leading global cause.", "Diabetic retinopathy is not the leading global cause.", "Correct. Cataract is the leading global blindness cause.", "Glaucoma is a leading cause of irreversible, not overall, blindness."]}'),
  ('a134be86-1g','{"options": ["+5 D", "+10 D", "+20 D", "+25 D"], "correct": 2, "decode": "Formula: equivalent add = M × 4. Steps: 5 × 4 = +20 D (working distance ≈ 5 cm).", "ow": ["+5 D would be 1.25×, not 5×.", "+10 D would be ~2.5×.", "Correct. 5 × 4 = +20 D.", "+25 D would be ~6.25×."]}'),
  ('5f07029e-2d','{"options": ["20%", "50%", "80%", "100%"], "correct": 2, "decode": "About 80% of global blindness is avoidable (led by cataract and uncorrected refractive error).", "ow": ["20% badly understates it.", "50% understates it.", "Correct. About 80% of blindness is avoidable.", "It is not 100%; some causes are not preventable."]}'),
  ('2d5f297f-n','{"options": ["After enucleation", "For contact lens fitting", "Over an existing but shrunken globe", "To replace a conformer permanently"], "correct": 2, "decode": "A SCLERAL SHELL fits OVER an existing but SHRUNKEN globe.", "ow": ["After enucleation the globe is gone; a custom prosthesis is used instead.", "It is not a contact lens for refractive fitting.", "Correct. A scleral shell fits over a shrunken globe.", "It is not a permanent conformer replacement."]}'),
  ('6ac9cf7e-2n','{"options": ["Custom prosthesis", "Bandage lens", "Scleral shell", "Conformer"], "correct": 3, "decode": "Immediately after eye removal, a clear placeholder preventing socket contraction is a CONFORMER.", "ow": ["The custom prosthesis is fitted later, at ~6 to 8 weeks.", "A bandage lens is a corneal device, not a socket placeholder.", "A scleral shell is for a shrunken present globe.", "Correct. A conformer is the temporary socket placeholder."]}'),
  ('91d5bcd8-1m','{"options": ["A conformer left in place", "A custom PMMA prosthesis", "A scleral contact lens", "A stock shell off the shelf"], "correct": 1, "decode": "The standard of care for a definitive ocular prosthesis is a CUSTOM PMMA prosthesis (by an ocularist).", "ow": ["A conformer is temporary, not definitive.", "Correct. Custom PMMA prosthesis is definitive.", "A scleral contact lens is not the definitive prosthesis.", "A stock shell causes chronic irritation, not the standard of care."]}'),
  ('3da6c2b4-1u','{"options": ["5 years", "6–12 months", "10 years", "Week"], "correct": 1, "decode": "An ocular prosthesis should be professionally polished every 6 to 12 months.", "ow": ["5 years is far too infrequent for polishing.", "Correct. Polish every 6 to 12 months.", "10 years is far too infrequent.", "Weekly polishing is unnecessary."]}'),
  ('d8e3cda4-1c','{"options": ["5–7 years", "1 year", "15 years", "Never"], "correct": 0, "decode": "An ocular prosthesis is typically replaced every 5 to 7 years (children more often).", "ow": ["Correct. Replace every 5 to 7 years.", "1 year is too frequent for adults.", "15 years is too long.", "It does need periodic replacement, so ''never'' is wrong."]}'),
  ('de23cbd1-1r','{"options": ["Use as normal sunglasses", "Retinitis pigmentosa, maculopathy", "Mild photophobia alone", "Albinism and nothing else"], "correct": 1, "decode": "CPF 527 (orange) is indicated for RETINITIS PIGMENTOSA and MACULOPATHY (contrast, glare).", "ow": ["It is more than a normal sunglass tint.", "Correct. CPF 527 suits RP and macular disease.", "It is not just for mild photophobia alone.", "It is not limited to albinism only."]}'),
  ('3bda4a6d-2f','{"options": ["Deep orange or red", "Blue tint", "Gray neutral density", "Light yellow"], "correct": 0, "decode": "For achromatopsia with severe photophobia, the best filter is DEEP ORANGE or RED (longpass).", "ow": ["Correct. Deep red/orange cuts the wavelengths that overwhelm rods.", "A blue tint would worsen glare.", "Gray neutral density gives no targeted relief.", "Light yellow is insufficient for achromatopsia."]}'),
  ('54fbc374-1a','{"options": ["Clear lenses only", "Photochromic for driving", "Yellow only", "Deep absorptive tint with UV 400"], "correct": 3, "decode": "Albinism eyewear is a DEEP ABSORPTIVE TINT with UV 400 (very light-sensitive, no pigment).", "ow": ["Clear lenses give no glare relief.", "Photochromics for driving fail behind a windshield.", "Yellow alone is insufficient.", "Correct. Deep absorptive tint with UV 400."]}'),
  ('c29d8c78-14','{"options": ["Alcohol", "Tap water", "Sterile saline", "Hydrogen peroxide"], "correct": 2, "decode": "An ocular prosthesis should be soaked in STERILE SALINE (tap water carries Acanthamoeba risk).", "ow": ["Alcohol can damage the prosthesis.", "Tap water carries infection risk.", "Correct. Soak in sterile saline.", "Hydrogen peroxide is not the recommended soak."]}'),
  ('88f9d79f-30','{"options": ["Antibiotics and reassurance", "Refer for a custom prosthesis", "Switch to a scleral shell", "Stop wearing the prosthesis"], "correct": 1, "decode": "Chronic irritation from a poorly fitting stock shell (6 months post-op) is corrected by REFERRING for a CUSTOM prosthesis.", "ow": ["Antibiotics and reassurance do not fix the fit problem.", "Correct. Refer for a custom PMMA prosthesis.", "A scleral shell is for a shrunken globe, not this socket.", "Stopping wear risks a contracted socket."]}'),
  ('d431e677-1v','{"options": ["6–8 weeks", "1 year", "6 months", "The day of surgery"], "correct": 0, "decode": "The custom PMMA prosthesis after eye removal is typically fitted at 6 to 8 weeks (conformer holds the socket meanwhile).", "ow": ["Correct. Fitted at 6 to 8 weeks.", "1 year is far too late.", "6 months is later than the usual fitting.", "Not the day of surgery; healing must occur first."]}'),
  ('dd557325-2l','{"options": ["3", "5", "7", "10"], "correct": 1, "decode": "As originally written in RA 8050, the number of DPAs is 5 (cyclopentolate was added later in the 2008 IRR, making six current).", "ow": ["3 undercounts the original list.", "Correct. The original statute lists 5 DPAs.", "7 overcounts them.", "10 overcounts them."]}'),
  ('f219916d-1b','{"options": ["2 minutes", "5 minutes", "10 seconds", "30 seconds"], "correct": 0, "decode": "Nasolacrimal occlusion should be maintained for 2 minutes to cut systemic absorption.", "ow": ["Correct. NLO for 2 minutes.", "5 minutes is longer than the standard.", "10 seconds is too brief.", "30 seconds is too brief."]}'),
  ('b9427e17-1d','{"options": ["A narrow or occludable angle", "Cataract", "Diabetes mellitus", "Dry eye"], "correct": 0, "decode": "The absolute contraindication to any mydriatic is a NARROW or OCCLUDABLE ANGLE (risk of acute angle-closure).", "ow": ["Correct. A narrow/occludable angle is the absolute contraindication.", "Cataract is not a contraindication to dilation.", "Diabetes is not a mydriatic contraindication.", "Dry eye is not an absolute contraindication."]}'),
  ('5c9a9247-1c','{"options": ["Artificial tears", "Fluorescein", "Tropicamide", "Proparacaine"], "correct": 3, "decode": "PROPARACAINE must never be dispensed for home use (repeated anesthetic causes a neurotrophic ulcer).", "ow": ["Artificial tears are safe for home use.", "Fluorescein is a diagnostic dye, used in office.", "Tropicamide is a mydriatic, not the home-use hazard here.", "Correct. Never send anesthetics home."]}'),
  ('e89122d5-1i','{"options": ["A prosthetic shell", "Soft contact lenses", "RGP lenses", "Spectacles"], "correct": 1, "decode": "Fluorescein must not be instilled with SOFT contact lenses in (it permanently stains hydrogel).", "ow": ["A prosthetic shell is not stained the way hydrogel is.", "Correct. Remove soft lenses before fluorescein.", "RGP lenses are not hydrogel and are not permanently stained.", "Spectacles are unaffected."]}'),
  ('1b6eac85-1f','{"options": ["6 months", "6 weeks", "12 months", "3–4 months"], "correct": 3, "decode": "An infant''s eyes should be consistently straight by 3 to 4 months.", "ow": ["6 months is later than the milestone.", "6 weeks is too early to require stable alignment.", "12 months is far too late.", "Correct. Straight by 3 to 4 months."]}'),
  ('7cf11a73-1i','{"options": ["Preferential looking", "HOTV matching", "Snellen letters", "The Pelli-Robson chart"], "correct": 0, "decode": "A pre-verbal infant is tested with PREFERENTIAL LOOKING (Teller acuity cards).", "ow": ["Correct. Preferential looking suits pre-verbal infants.", "HOTV matching needs a cooperative preschooler.", "Snellen letters need reading.", "Pelli-Robson tests contrast, not infant acuity."]}'),
  ('5be2bf92-1m','{"options": ["Meridional", "Strabismic", "Deprivation", "Anisometropic"], "correct": 2, "decode": "DEPRIVATION amblyopia (dense cataract, complete ptosis) carries the worst prognosis.", "ow": ["Meridional amblyopia is milder.", "Strabismic amblyopia is more treatable.", "Correct. Deprivation amblyopia is the densest, least reversible.", "Anisometropic amblyopia has a better prognosis."]}'),
  ('7ed97f38-18','{"options": ["An asymmetric nasal reflex", "An asymmetric temporal reflex", "Symmetric reflexes", "No reflex at all"], "correct": 2, "decode": "On Hirschberg, pseudostrabismus shows SYMMETRIC reflexes (no true deviation).", "ow": ["An asymmetric nasal reflex suggests a true deviation.", "An asymmetric temporal reflex suggests a true deviation.", "Correct. Symmetric reflexes confirm pseudostrabismus.", "A reflex is present; it is symmetric, not absent."]}'),
  ('999b0ecc-25','{"options": ["60% dry / 40% wet", "95% dry / 5% wet", "50% dry / 50% wet", "85% dry / 15% wet"], "correct": 3, "decode": "AMD splits about 85% DRY and 15% WET.", "ow": ["60/40 is not the accepted split.", "95/5 overstates the dry fraction.", "It is not an even split.", "Correct. 85% dry, 15% wet."]}'),
  ('8f17ac12-27','{"options": ["5%", "25%", "50%", "75%"], "correct": 1, "decode": "AREDS2 reduces progression to advanced AMD by about 25% in intermediate dry AMD.", "ow": ["5% understates the effect.", "Correct. About 25% risk reduction.", "50% overstates it.", "75% overstates it."]}'),
  ('949e7f74-1b','{"options": ["3:2", "1:1", "1:2", "2:3"], "correct": 3, "decode": "The normal retinal arteriole-to-venule (AV) ratio is 2:3.", "ow": ["3:2 would make arterioles wider than venules.", "1:1 would make them equal.", "1:2 is the narrowed (hypertensive) ratio, not normal.", "Correct. Normal AV ratio is 2:3."]}'),
  ('06894d85-1p','{"options": ["Diabetic macular edema", "Tractional detachment", "Vitreous hemorrhage", "Neovascular glaucoma"], "correct": 0, "decode": "DIABETIC MACULAR EDEMA is the commonest cause of vision loss in diabetic retinopathy (any stage).", "ow": ["Correct. DME is the commonest cause.", "Tractional detachment is a late proliferative complication, not the commonest cause.", "Vitreous hemorrhage is not the commonest cause.", "Neovascular glaucoma is a late complication, not the commonest cause."]}'),
  ('136245ae-1l','{"options": ["Hard drusen", "Soft, large confluent drusen", "Calcified drusen", "Basal laminar drusen"], "correct": 1, "decode": "SOFT, LARGE, CONFLUENT drusen carry the highest risk of progression.", "ow": ["Small hard drusen are common with age and low risk.", "Correct. Soft, large, confluent drusen are high risk.", "Calcified drusen are not the highest-risk type here.", "Basal laminar drusen are not the highest-risk type here."]}'),
  ('29b69918-2w','{"options": ["Annulus of Zinn", "Cavernous sinus", "Superior orbital fissure", "Clivus"], "correct": 3, "decode": "CN6 is a false localizing sign because raised ICP compresses its long course over the CLIVUS.", "ow": ["The annulus of Zinn is the muscle origin, not the vulnerable clival course.", "The cavernous sinus is a segment but not the classic false-localizing site.", "The superior orbital fissure is distal, not the false-localizing site.", "Correct. Its long clival course makes it a false localizing sign."]}'),
  ('a551f2d2-1s','{"options": ["Retinopathy of prematurity", "Perinatal hypoxia-ischemia", "Optic nerve hypoplasia", "Congenital cataract"], "correct": 1, "decode": "The commonest cause of childhood cortical visual impairment is PERINATAL HYPOXIA-ISCHEMIA (eyes look normal).", "ow": ["Retinopathy of prematurity is an ocular, not cortical, cause.", "Correct. Perinatal hypoxia-ischemia is the commonest cause.", "Optic nerve hypoplasia is an ocular/optic cause, not CVI.", "Congenital cataract is a media problem, not CVI."]}'),
  ('55f4e9e1-1m','{"options": ["Pigmentary retinopathy", "Optic atrophy", "Structurally normal eyes", "Dense cataract"], "correct": 2, "decode": "In CVI the ocular examination shows STRUCTURALLY NORMAL eyes (pupils react).", "ow": ["Pigmentary retinopathy is not a CVI finding.", "Optic atrophy is not the CVI picture.", "Correct. CVI eyes are structurally normal.", "A dense cataract is a media opacity, not CVI."]}'),
  ('1f09b3f7-1d','{"options": ["20–30 minutes", "5 minutes", "60 seconds", "2–3 minutes"], "correct": 0, "decode": "Chemical burn irrigation should continue 20 to 30 minutes, rechecking pH until neutral.", "ow": ["Correct. Irrigate 20 to 30 minutes to neutral pH.", "5 minutes is far too short for a chemical burn.", "60 seconds is far too short.", "2 to 3 minutes is too short."]}'),
  ('92ffea75-x','{"options": ["78 days", "105 days", "60 days", "120 days"], "correct": 1, "decode": "Maternity leave under RA 11210 (Expanded Maternity Leave Law) is 105 days.", "ow": ["78 days was the old pre-2019 allowance.", "Correct. 105 days.", "60 days is not the current figure.", "120 days is not the RA 11210 figure."]}'),
  ('fe3d76d7-20','{"options": ["DOLE", "DOH", "DTI", "PRC"], "correct": 0, "decode": "The Occupational Safety and Health Standards fall under DOLE.", "ow": ["Correct. OSHS is under DOLE.", "The DOH handles health, not workplace safety standards.", "The DTI handles trade, not OSHS.", "The PRC handles licensure, not OSHS."]}'),
  ('dea5726b-1k','{"options": ["Yellow", "Grey", "Dark green", "Blue"], "correct": 0, "decode": "YELLOW is the best tint for improving visibility in fog or haze.", "ow": ["Correct. Yellow lifts contrast in fog/haze.", "Grey is neutral density and adds no contrast.", "Dark green does not lift haze contrast like yellow.", "Blue does not improve haze visibility."]}'),
  ('56d1ed95-1h','{"options": ["ANSI Z87.1", "ASTM F1587", "ASTM F803", "ISO 12312"], "correct": 2, "decode": "The protective-eyewear standard for racquet sports is ASTM F803.", "ow": ["ANSI Z87.1 is the general industrial standard.", "ASTM F1587 is not the racquet-sports standard cited here.", "Correct. ASTM F803 covers racquet sports.", "ISO 12312 covers sunglasses/eclipse filters."]}'),
  ('605e896c-1j','{"options": ["Snellen chart", "Titmus stereotest", "Pelli-Robson chart", "Ishihara plates"], "correct": 2, "decode": "Contrast sensitivity in an athlete is measured with the PELLI-ROBSON chart.", "ow": ["The Snellen chart measures acuity, not contrast.", "The Titmus stereotest measures stereopsis.", "Correct. Pelli-Robson measures contrast sensitivity.", "Ishihara plates test color vision."]}'),
  ('bef5226d-1q','{"options": ["< 20/40", "≤ 20/200", "< 20/70", "< 20/60"], "correct": 2, "decode": "WHO defines low vision as better-eye acuity worse than 20/70.", "ow": ["Worse than 20/40 is better than the low-vision threshold.", "20/200 or worse is the blindness range, not low vision.", "Correct. Low vision is worse than 20/70.", "Worse than 20/60 is not the WHO cutoff."]}'),
  ('1408654e-1o','{"options": ["1 D", "2 D", "4 D", "10 D"], "correct": 2, "decode": "The magnification reference takes 1× as 4 D (equivalent add = M × 4).", "ow": ["1 D = 1× is not the reference.", "2 D = 1× is not the reference.", "Correct. 4 D = 1×.", "10 D = 1× is not the reference."]}'),
  ('9a22f599-1s','{"options": ["Required VA + 4", "Required VA ÷ Present VA", "Present VA ÷ Required VA", "Required VA × Present VA"], "correct": 1, "decode": "Formula: magnification M = required VA / present VA.", "ow": ["Required VA + 4 is not the formula.", "Correct. M = required VA / present VA.", "This inverts the ratio.", "Multiplying the acuities is not the formula."]}'),
  ('4086d932-25','{"options": ["Stand magnifier", "Hand magnifier", "Pocket magnifier", "Telescope"], "correct": 0, "decode": "For sustained reading with a hand tremor, the best magnifier is a STAND MAGNIFIER (fixed focal distance on the page).", "ow": ["Correct. A stand magnifier suits tremor.", "A hand magnifier needs a steady grip.", "A pocket magnifier is unstable with tremor.", "A telescope is for distance, not reading."]}'),
  ('32fb7e8b-1e','{"options": ["Improve cosmesis immediately", "Prevent socket contraction", "Reduce infection risk", "Restore some vision"], "correct": 1, "decode": "A conformer after enucleation PREVENTS SOCKET CONTRACTION until the custom prosthesis is fitted.", "ow": ["Cosmesis comes from the definitive prosthesis, not the clear conformer.", "Correct. The conformer prevents socket contraction.", "It is not primarily an infection-reducing device.", "It does not restore vision."]}'),
  ('1e45e18d-1o','{"options": ["5–7 years", "6–12 months", "Month", "2 years"], "correct": 1, "decode": "An ocular prosthesis should be professionally polished every 6 to 12 months (replaced every 5 to 7 years).", "ow": ["5 to 7 years is the replacement interval, not the polishing interval.", "Correct. Polish every 6 to 12 months.", "Monthly polishing is unnecessary.", "2 years is too long between polishes."]}'),
  ('b07cfc99-12','{"options": ["Deep red or orange", "Light grey", "Clear UV 400", "Yellow-amber"], "correct": 0, "decode": "The tint of choice in achromatopsia is DEEP RED or ORANGE (CPF 550, Wratten #25/#29).", "ow": ["Correct. Deep red/orange suits achromatopsia.", "Light grey gives no targeted relief.", "Clear UV 400 does not cut the dazzling light.", "Yellow-amber is insufficient for achromatopsia."]}'),
  ('1e3cec58-1r','{"options": ["Keratoconus", "Cataract", "Optic neuritis", "Retinal detachment"], "correct": 1, "decode": "Besides photokeratitis, chronic UV-B exposure is associated with CATARACT (and pterygium).", "ow": ["Keratoconus is not a UV-B association.", "Correct. Chronic UV-B links to cataract.", "Optic neuritis is not a UV-B association.", "Retinal detachment is not a UV-B association."]}'),
  ('5b5f6ebb-1a','{"options": ["Speeds systemic absorption", "Shortens the ocular effect", "Blocks systemic drainage", "Stops the drug working"], "correct": 2, "decode": "Nasolacrimal occlusion BLOCKS SYSTEMIC DRAINAGE, keeping the drug on the eye and cutting systemic load.", "ow": ["It slows, not speeds, systemic absorption.", "It improves, not shortens, the ocular effect.", "Correct. NLO blocks systemic drainage.", "It does not stop the drug working on the eye."]}'),
  ('6e18b6a3-1t','{"options": ["Cycloplegia only", "Mydriasis and cycloplegia", "Neither of these effects", "Mydriasis only"], "correct": 1, "decode": "TROPICAMIDE (an M3 blocker) causes MYDRIASIS AND CYCLOPLEGIA; phenylephrine dilates without cycloplegia.", "ow": ["It causes both effects, not cycloplegia only.", "Correct. Tropicamide gives mydriasis and cycloplegia.", "It does cause both effects.", "Mydriasis-only describes phenylephrine, not tropicamide."]}'),
  ('e0b5b84b-1d','{"options": ["Category A, entirely safe", "Permitted after delivery only", "Absolutely contraindicated", "Category C, used if needed"], "correct": 3, "decode": "DPAs in pregnancy are CATEGORY C, used if genuinely needed (tropicamide with NLO preferred).", "ow": ["They are Category C, not Category A.", "They are not restricted to post-delivery only.", "They are not absolutely contraindicated; blanket avoidance is wrong.", "Correct. Category C, used if needed."]}'),
  ('398c6532-12','{"options": ["Prism spectacles at near", "Immediate part-time patching", "No treatment; it resolves", "Early surgical correction"], "correct": 2, "decode": "Pseudostrabismus requires NO TREATMENT; it resolves as the face grows (symmetric Hirschberg reflexes).", "ow": ["Prism spectacles are not indicated for pseudostrabismus.", "Patching is not indicated; there is no true deviation.", "Correct. No treatment; it resolves.", "Surgery is not indicated for pseudostrabismus."]}'),
  ('c330be3b-y','{"options": ["Effective only with surgery", "Completely futile after 7", "As effective as before age 7", "Reduced, but useful to ~12"], "correct": 3, "decode": "Amblyopia treatment after age 7 is REDUCED but still useful to about age 12.", "ow": ["It is not surgery-only after 7.", "It is not completely futile after 7.", "It is less, not equally, effective after 7.", "Correct. Reduced but useful to ~12."]}'),
  ('4fc37b06-28','{"options": ["1 to 2 weeks", "6 months minimum", "12 to 16 weeks", "48 hours"], "correct": 2, "decode": "After full spectacle correction for amblyopia, observe for 12 to 16 weeks before adding patching.", "ow": ["1 to 2 weeks is too short to judge glasses alone.", "6 months minimum overstates the wait before adding patching.", "Correct. Observe 12 to 16 weeks.", "48 hours is far too short."]}'),
  ('9bc164a0-1m','{"options": ["A residual remains on plus", "The deviation exceeds 10Δ", "The glasses are refused", "The child has turned five"], "correct": 0, "decode": "Surgery for accommodative esotropia is indicated only for a RESIDUAL deviation remaining on full plus.", "ow": ["Correct. Operate only on the non-accommodative residual.", "The absolute size alone (>10Δ) is not the criterion; the residual on plus is.", "Refusing glasses is not itself a surgical indication.", "Turning five is not a surgical criterion."]}'),
  ('ec5468b0-20','{"options": ["Geographic atrophy only", "Dry AMD, being the commonest", "Drusen alone", "Wet AMD, despite being the minority"], "correct": 3, "decode": "Most SEVERE AMD vision loss is caused by WET AMD, despite it being the minority.", "ow": ["Geographic atrophy is a dry endpoint, not the main cause of rapid severe loss.", "Dry AMD is commonest but causes slower loss.", "Drusen alone do not cause severe loss.", "Correct. Wet AMD causes most severe loss despite being the minority."]}'),
  ('91962896-1t','{"options": ["Grade 3", "Grade 1", "Grade 4", "Grade 2"], "correct": 3, "decode": "AV nicking corresponds to GRADE 2 hypertensive retinopathy.", "ow": ["Grade 3 is hemorrhages and exudates.", "Grade 1 is arteriolar narrowing.", "Grade 4 is papilledema.", "Correct. AV nicking is grade 2."]}'),
  ('284e88c2-19','{"options": ["Slowed progression to advanced", "A cure for wet AMD", "Effective in early AMD only", "A treatment for existing AMD"], "correct": 0, "decode": "AREDS2 supplements SLOW PROGRESSION to advanced AMD; they do not treat or reverse disease.", "ow": ["Correct. AREDS2 slows progression.", "They do not cure wet AMD.", "They have no proven role in early AMD.", "They do not treat existing AMD."]}'),
  ('1ff314eb-1r','{"options": ["It blocks the fixating eye", "Occlusion triggers the jerk", "It is uncomfortable for a child", "It causes deep suppression"], "correct": 1, "decode": "Patching is wrong for testing acuity in latent nystagmus because OCCLUSION TRIGGERS the jerk (falsely poor VA).", "ow": ["It is not simply about blocking the fixating eye; occlusion provokes the nystagmus.", "Correct. Occlusion triggers the latent nystagmus.", "Discomfort is not the reason.", "It does not cause deep suppression."]}'),
  ('307d4b5a-1g','{"options": ["Sluggish, with a thin retina", "Fixed, with disc pallor", "Both entirely normal", "Normal pupils but abnormal OCT"], "correct": 2, "decode": "In CVI the pupils and OCT are BOTH ENTIRELY NORMAL (a brain injury, not an ocular one).", "ow": ["Pupils are not sluggish and the retina is not thin in CVI.", "Pupils are not fixed and there is no disc pallor in CVI.", "Correct. Normal pupils and normal OCT.", "The OCT is normal, not abnormal, in CVI."]}'),
  ('fd6031d7-t','{"options": ["Enhancing depth perception", "Cutting all wavelengths equally", "Improving contrast markedly", "Sharpening moving targets"], "correct": 1, "decode": "A grey tint is NEUTRAL DENSITY: it cuts all wavelengths equally, so contrast is unchanged.", "ow": ["It does not enhance depth perception.", "Correct. Grey cuts all wavelengths equally.", "It does not improve contrast.", "It does not sharpen moving targets."]}'),
  ('ea644f68-1a','{"options": ["Racquet sports", "All sports equally", "Baseball batting helmets", "Ice hockey visors"], "correct": 0, "decode": "The ASTM F803 standard applies specifically to RACQUET SPORTS.", "ow": ["Correct. F803 covers racquet sports.", "It is not an all-sports standard.", "Batting helmets fall under other standards.", "Ice hockey visors fall under other standards."]}'),
  ('be827607-1q','{"options": ["Best-corrected acuity", "Uncorrected acuity", "Habitual acuity in old glasses", "Pinhole acuity"], "correct": 0, "decode": "Magnification must be calculated from BEST-CORRECTED acuity (refract first).", "ow": ["Correct. Use best-corrected acuity.", "Uncorrected acuity overestimates the need.", "Habitual acuity in old glasses is not the basis.", "Pinhole acuity is not the basis."]}'),
  ('281bd07c-1r','{"options": ["Peripheral awareness, via prisms", "Near, for reading", "Distance, via a telescope", "Intermediate, via a computer lens"], "correct": 1, "decode": "Most low vision patients need NEAR magnification (for reading) first.", "ow": ["Peripheral awareness via prisms is not the usual first need.", "Correct. Near reading magnification comes first.", "Distance via telescope is not the universal starting point.", "Intermediate/computer needs are not the usual first request."]}'),
  ('d3c84abb-11','{"options": ["A normal phakic eye", "A shrunken but present globe", "A socket after exenteration", "An empty socket after enucleation"], "correct": 1, "decode": "A scleral shell is used for a SHRUNKEN but PRESENT globe (phthisis, microphthalmos).", "ow": ["A normal phakic eye does not need a shell.", "Correct. A shell fits a shrunken present globe.", "After exenteration the socket is very different; a shell is not the device.", "After enucleation the globe is gone; a custom prosthesis is used."]}'),
  ('19aa6a9d-1x','{"options": ["2 weeks", "The same day", "6 months", "6 to 8 weeks"], "correct": 3, "decode": "The definitive custom prosthesis is fitted at about 6 to 8 weeks after enucleation (conformer holds the socket first).", "ow": ["2 weeks is too early; swelling has not settled.", "Not the same day; healing must occur first.", "6 months is later than the usual fitting.", "Correct. Fitted at 6 to 8 weeks."]}'),
  ('1bb70a00-1w','{"options": ["CPF 550", "CPF 527", "CPF 450", "A dark red Wratten #29"], "correct": 2, "decode": "For mild photophobia or early lens changes, the filter is CPF 450 (light yellow).", "ow": ["CPF 550 is a dark red for achromatopsia.", "CPF 527 is reserved for RP, macular disease, glaucoma.", "Correct. CPF 450 suits mild photophobia.", "A dark red Wratten #29 is for achromatopsia, not mild photophobia."]}'),
  ('0ebdd06a-2g','{"options": ["Cyclopentolate 1%", "Proparacaine 0.5%", "Tropicamide 0.5%", "Phenylephrine 10%"], "correct": 2, "decode": "For a dilated fundus exam in pregnancy, TROPICAMIDE 0.5% is most appropriate (shortest duration, least systemic exposure).", "ow": ["Cyclopentolate 1% has longer duration and more exposure.", "Proparacaine is an anesthetic, not a mydriatic.", "Correct. Tropicamide 0.5% is preferred in pregnancy.", "Phenylephrine 10% carries cardiovascular risk."]}'),
  ('829bdf7a-2l','{"options": ["It blocks acetylcholinesterase, preventing ACh from contracting the ciliary muscle", "It directly relaxes the ciliary muscle through a non-receptor mechanism", "It acts on M3 receptors selectively on the sphincter pupillae only", "It acts on α1 receptors on the dilator pupillae; the ciliary muscle has no α1 receptors"], "correct": 3, "decode": "Phenylephrine mydriates without cycloplegia because it acts on α1 on the DILATOR, and the ciliary muscle has NO α1 receptors.", "ow": ["It does not block acetylcholinesterase.", "It does not directly relax the ciliary muscle.", "M3-block on the sphincter describes an antimuscarinic, not phenylephrine.", "Correct. α1 on the dilator; ciliary muscle has no α1."]}'),
  ('30fd3181-5v','{"options": ["Strabismic amblyopia; patch the right eye now", "Pseudoamblyopia; reassure and retest in 1 year", "Anisometropic amblyopia; full correction, observe", "Deprivation amblyopia; remove the media opacity"], "correct": 2, "decode": "A 3.50 D hyperopic difference with reduced VA in the worse eye is ANISOMETROPIC amblyopia: FULL CORRECTION first, then observe.", "ow": ["No manifest deviation is described, so strabismic is less likely; correct first anyway.", "The reduced VA is real amblyopia, not pseudoamblyopia.", "Correct. Anisometropic amblyopia; full correction and observe.", "Deprivation implies a media opacity, not a refractive difference."]}'),
  ('20a861ee-4j','{"options": ["Strabismic amblyopia — patch the preferred eye", "Pseudostrabismus — reassure; no treatment needed", "Accommodative esotropia — prescribe full plus correction", "Infantile esotropia — refer for surgical alignment"], "correct": 1, "decode": "Crossed-looking eyes with SYMMETRIC Hirschberg reflexes = PSEUDOSTRABISMUS; reassure, no treatment.", "ow": ["Symmetric reflexes rule out true strabismus, so patching is wrong.", "Correct. Symmetric reflexes indicate pseudostrabismus.", "There is no accommodative eso; reflexes are symmetric.", "Symmetric reflexes rule out infantile esotropia."]}'),
  ('0becc890-73','{"options": ["Proliferative DR; pan-retinal photocoagulation", "Moderate NPDR; observe and recheck in 12 months", "Dry AMD with macular drusen; AREDS2 supplements", "Clinically significant macular edema; anti-VEGF"], "correct": 3, "decode": "Retinal thickening within 500 µm of the fovea plus hard exudates = CLINICALLY SIGNIFICANT MACULAR EDEMA; refer for ANTI-VEGF.", "ow": ["There is no neovascularization described, so it is not proliferative DR.", "This is not a watch-and-wait moderate NPDR; CSME needs referral.", "The diabetic hard-exudate pattern is not dry AMD drusen.", "Correct. CSME; refer for anti-VEGF."]}'),
  ('20583115-5n','{"options": ["Diabetic macular edema", "Dry AMD with geographic atrophy", "Hypertensive retinopathy grade 3", "Wet AMD with choroidal neovascularization"], "correct": 3, "decode": "Sudden metamorphopsia with SUBRETINAL FLUID and HEMORRHAGE at the macula = WET AMD with choroidal neovascularization; urgent anti-VEGF.", "ow": ["DME is diabetic and has a different fundus picture.", "Dry AMD with geographic atrophy progresses gradually, without acute subretinal blood.", "HTR grade 3 shows flame hemorrhages and cotton-wool spots, not subretinal hemorrhage.", "Correct. Wet AMD with choroidal neovascularization."]}'),
  ('1ee2eca0-81','{"options": ["Right CN4 palsy", "Left CN4 palsy", "Right CN3 palsy", "Right CN6 palsy"], "correct": 0, "decode": "Vertical diplopia worst on downgaze, right hypertropia, head tilt LEFT (away), positive Bielschowsky on RIGHT tilt = RIGHT CN4 (SO) palsy.", "ow": ["Correct. Right superior oblique (CN4) palsy.", "A left CN4 palsy would tilt away to the right and worsen on left tilt.", "A CN3 palsy gives ptosis and a down-and-out eye, not isolated vertical diplopia.", "A CN6 palsy gives horizontal diplopia, not vertical."]}'),
  ('fab609ee-7x','{"options": ["Cortical visual impairment", "Latent nystagmus", "Congenital cataract", "Infantile esotropia with amblyopia"], "correct": 0, "decode": "Neurological insult (PVL) with normal-appearing eyes and reduced preferential-looking VA = CORTICAL VISUAL IMPAIRMENT.", "ow": ["Correct. PVL plus normal eyes plus poor vision is CVI.", "Latent nystagmus does not fit this neuroimaging picture.", "A congenital cataract would show a media opacity, not normal eyes.", "Infantile esotropia is a motor deviation, not this behavioral visual picture."]}'),
  ('f96c28be-2g','{"options": ["Irrigate with clean water or saline for at least 20–30 minutes immediately", "Apply a bandage contact lens to protect the cornea", "Instill proparacaine and refer to the emergency room without irrigation", "Identify the chemical first, then call poison control before irrigating"], "correct": 0, "decode": "A chemical splash is managed by IMMEDIATE irrigation with water/saline for at least 20 to 30 minutes; identification follows.", "ow": ["Correct. Irrigate immediately for 20 to 30 minutes.", "A bandage lens is not the first action.", "Do not delay irrigation to instill anesthetic and refer.", "Do not delay irrigation to identify the chemical first."]}'),
  ('1a34bc57-52','{"options": ["Prescribing cycloplegic drops for daily use to relax the ciliary muscle", "Prescribing a slightly reduced near add for screen distance if presbyopic", "Prescribing anti-reflection coated lenses", "Advising the 20-20-20 rule"], "correct": 0, "decode": "Prescribing DAILY CYCLOPLEGIC DROPS is NOT part of CVS management (cycloplegics are diagnostic only).", "ow": ["Correct. Daily cycloplegic drops are never appropriate.", "A slightly reduced near add for screen distance is appropriate if presbyopic.", "Anti-reflection coated lenses are appropriate.", "The 20-20-20 rule is appropriate."]}'),
  ('ef27458b-4t','{"options": ["Stereopsis; Stereo Fly Test", "Dynamic visual acuity; Tachistoscope or Marsden Ball", "Color vision; Ishihara plates", "Contrast sensitivity; Pelli-Robson chart"], "correct": 1, "decode": "Trouble tracking a moving ball despite 20/20 static VA = DYNAMIC VISUAL ACUITY deficit; assess with a TACHISTOSCOPE or MARSDEN BALL.", "ow": ["Stereopsis and the Stereo Fly are not the moving-target issue.", "Correct. Dynamic VA, assessed by tachistoscope or Marsden ball.", "Color vision and Ishihara are unrelated to tracking.", "Contrast sensitivity and Pelli-Robson are not the moving-target issue."]}'),
  ('0d3df2dd-4d','{"options": ["Yellow", "Blue", "Gray", "Brown or amber"], "correct": 3, "decode": "For depth judgment in golf, BROWN or AMBER tints (with a red element) are best, in partly cloudy to sunny light.", "ow": ["Yellow is better for haze and low light, not depth in sun.", "Blue is cosmetic, not clinically superior for depth.", "Gray reduces intensity without improving contrast/depth.", "Correct. Brown/amber enhance depth perception."]}'),
  ('5eb8dac6-3s','{"options": ["3×; +12.00D add", "2×; +8.00D add", "2×; +12.00D add", "4×; +16.00D add"], "correct": 3, "decode": "Formula: M = required VA / present VA; equivalent add = M × 4. Steps: M = N32 / N8 = 32/8 = 4×; add = 4 × 4 = +16 D (working distance 100/16 = 6.25 cm).", "ow": ["3×, +12 D uses the wrong ratio.", "2×, +8 D uses the wrong ratio.", "2×, +12 D uses the wrong ratio.", "Correct. 32/8 = 4×, and 4 × 4 = +16 D."]}'),
  ('52975765-23','{"options": ["Restore best corrected VA to 20/20 with lenses", "Replace all spectacles with one magnifier system", "Train only patients with VA better than 20/200", "Maximize function for the patient''s daily tasks"], "correct": 3, "decode": "The goal of low vision rehabilitation is to MAXIMIZE FUNCTION for the patient''s daily tasks, not restore 20/20.", "ow": ["Restoring 20/20 is not the goal.", "It is not about replacing all spectacles with one magnifier.", "Care is not limited to those above 20/200.", "Correct. Maximize function for daily tasks."]}'),
  ('67c2d1a7-4x','{"options": ["Green tint for general outdoor use", "Deep orange or red tint", "Gray", "Light yellow"], "correct": 1, "decode": "For achromatopsia with severe photophobia, the best filter is DEEP ORANGE or RED (rods overwhelmed by short/mid wavelengths).", "ow": ["A green tint does not target the wavelengths that dazzle rods.", "Correct. Deep orange/red cuts short and mid wavelengths.", "Gray reduces all wavelengths without targeted relief.", "Light yellow (CPF 450) is insufficient."]}'),
  ('e01c770c-4i','{"options": ["Prescribe topical antibiotics and reassure", "Instruct the patient to stop wearing the prosthesis to allow the socket to heal", "Refer for a custom PMMA prosthesis fitted by a certified ocularist", "Switch to a scleral shell"], "correct": 2, "decode": "Chronic discharge/irritation from a poorly fitting STOCK prosthesis is corrected by REFERRING for a custom PMMA prosthesis.", "ow": ["Antibiotics and reassurance do not fix the fit problem.", "Stopping wear risks a contracted socket, not healing.", "Correct. Refer for a custom PMMA prosthesis.", "A scleral shell is for a shrunken globe, not this socket."]}'),
  ('9536c0dc-h','{"options": ["315–400 nm", "Blocks all UV below 400 nm", "< 527 nm", "280–315 nm"], "correct": 3, "decode": "The UV-B range is 280 to 315 nm.", "ow": ["315 to 400 nm is UV-A.", "''Blocks all UV below 400 nm'' is the UV-400 label, not the UV-B range.", "''< 527 nm'' is the CPF 527 cutoff.", "Correct. UV-B is 280 to 315 nm."]}'),
  ('685caa77-h','{"options": ["315–400 nm", "< 527 nm", "280–315 nm", "Blocks all UV below 400 nm"], "correct": 0, "decode": "The UV-A range is 315 to 400 nm.", "ow": ["Correct. UV-A is 315 to 400 nm.", "''< 527 nm'' is the CPF 527 cutoff.", "280 to 315 nm is UV-B.", "''Blocks all UV below 400 nm'' is the UV-400 label."]}'),
  ('13d916a7-j','{"options": ["280–315 nm", "< 527 nm", "315–400 nm", "< 400 nm"], "correct": 3, "decode": "The ''UV 400'' label means the lens blocks all UV below 400 nm.", "ow": ["280 to 315 nm is the UV-B range.", "''< 527 nm'' is the CPF 527 cutoff.", "315 to 400 nm is the UV-A range.", "Correct. UV 400 blocks all UV below 400 nm."]}'),
  ('ac987d28-l','{"options": ["< 527 nm", "Blocks all UV below 400 nm", "280–315 nm", "315–400 nm"], "correct": 0, "decode": "The CPF 527 cutoff is < 527 nm (orange).", "ow": ["Correct. CPF 527 cuts below 527 nm.", "''Blocks all UV below 400 nm'' is the UV-400 label.", "280 to 315 nm is the UV-B range.", "315 to 400 nm is the UV-A range."]}'),
  ('2c6c5c51-1t','{"options": ["Worse than 6/12 to 6/18", "Worse than 3/60", "Worse than 6/60 to 3/60", "Worse than 6/18 to 6/60"], "correct": 3, "decode": "Under ICD-11, MODERATE visual impairment is worse than 6/18 to 6/60 (20/70 to 20/200).", "ow": ["Worse than 6/12 to 6/18 is mild impairment.", "Worse than 3/60 is blindness.", "Worse than 6/60 to 3/60 is severe impairment.", "Correct. Moderate is worse than 6/18 to 6/60."]}'),
  ('dcc10d7d-1h','{"options": ["3/60", "6/120", "6/18", "6/60"], "correct": 0, "decode": "Under ICD-11, blindness begins at acuity worse than 3/60 (20/400).", "ow": ["Correct. Blindness is worse than 3/60.", "6/120 is not the ICD-11 blindness cutoff.", "6/18 is the mild-impairment boundary.", "6/60 is the severe-impairment boundary, not blindness."]}'),
  ('bc33137c-2r','{"options": ["Visual handicap", "Visual disability", "Visual impairment", "Visual disorder"], "correct": 0, "decode": "In the disorder-to-handicap chain, the psychosocial and economic consequences are the VISUAL HANDICAP.", "ow": ["Correct. Handicap is the psychosocial/economic fallout.", "Disability is a lost skill or ability, not the psychosocial fallout.", "Impairment is the functional loss, not the fallout.", "Disorder is the anatomical change, not the fallout."]}'),
  ('c0ff3073-29','{"options": ["Visual impairment", "Visual handicap", "Visual disorder", "Visual disability"], "correct": 2, "decode": "In the chain, an anatomical change in the visual organ is the VISUAL DISORDER.", "ow": ["Impairment is the functional loss, not the anatomical change.", "Handicap is the psychosocial/economic fallout.", "Correct. The disorder is the anatomical change.", "Disability is a lost skill or ability."]}'),
  ('f8967ba8-1c','{"options": ["About 8 billion", "About 500 million", "About 250 million", "At least 2.2 billion"], "correct": 3, "decode": "About 2.2 billion people worldwide have vision impairment (WHO), 1 billion of it preventable or unaddressed.", "ow": ["8 billion is roughly the whole population, not those with VI.", "500 million badly understates it.", "250 million understates it.", "Correct. At least 2.2 billion."]}'),
  ('6bff9019-2z','{"options": ["10 times", "2 times", "4 times", "No difference"], "correct": 2, "decode": "Vision impairment is roughly 4 times more prevalent in low- and middle-income than high-income regions.", "ow": ["10 times overstates the gap.", "2 times understates it.", "Correct. About 4 times higher.", "There is a large difference, not none."]}'),
  ('8daa7fff-1s','{"options": ["6 M", "30 M", "12 M", "60 M"], "correct": 3, "decode": "The M scale tracks the Snellen denominator. Steps: 20/200 → 200/20 × 6 = 60 M (20/20 = 6 M, 20/100 = 30 M).", "ow": ["6 M is 20/20, not 20/200.", "30 M is 20/100.", "12 M is 20/40.", "Correct. 20/200 = 60 M."]}'),
  ('fd3374f7-1b','{"options": ["Distance VA denominator ÷ 4", "Near VA denominator × 2.50", "Reciprocal of the distance acuity", "Product of distance and near VA"], "correct": 2, "decode": "Formula (Kestenbaum): near add = reciprocal of distance acuity. Steps: for 20/200, add = 200/20 = +10.00 D.", "ow": ["Distance VA denominator ÷ 4 is not Kestenbaum''s rule.", "Near VA denominator × 2.50 is not Kestenbaum.", "Correct. Add = reciprocal of distance acuity (20/200 → +10 D).", "The product of distance and near VA is not the rule."]}'),
  ('345e2c71-1p','{"options": ["The reciprocal of vision method", "Kestenbaum''s rule", "Starting from near visual acuity", "Halving the distance VA denominator"], "correct": 2, "decode": "Predicting a reading add is MOST ACCURATE when STARTING FROM MEASURED NEAR VA (uses the near threshold directly).", "ow": ["The reciprocal-of-vision method is an estimate from distance VA.", "Kestenbaum''s rule is an estimate from distance VA.", "Correct. Starting from measured near VA is most accurate.", "Halving the distance VA denominator is an estimate, not most accurate."]}'),
  ('72e95a9f-1p','{"options": ["No reserve is needed", "1 line smaller than threshold", "5 lines smaller than threshold", "3 lines smaller than threshold"], "correct": 3, "decode": "For fluent reading (~160 wpm) the acuity reserve needed is 3 lines smaller than threshold (spot 1, fluent 3, max 5).", "ow": ["Reserve is needed; prescribing at threshold leaves decoding-only reading.", "1 line is spot-reading reserve, not fluent.", "5 lines is maximum-reading reserve.", "Correct. Fluent reading needs 3 lines of reserve."]}'),
  ('6200d085-1q','{"options": ["Angular magnification", "Relative distance magnification", "Relative size magnification", "Projection magnification"], "correct": 2, "decode": "Formula (relative size magnification): enlarge the object itself, ratio = new/old size. Steps: 8 M / 2 M = 4×.", "ow": ["Angular magnification uses a lens, not object enlargement.", "Relative distance magnification moves the object closer.", "Correct. Enlarging 2 M to 8 M is relative size magnification (4×).", "Projection magnification is a different mechanism."]}'),
  ('4f728b52-1r','{"options": ["Projection magnification", "Angular magnification", "Relative size magnification", "Relative distance magnification"], "correct": 3, "decode": "Formula (relative distance magnification): ratio = old distance / new distance. Steps: 40 cm / 10 cm = 4× (costs accommodation or an add).", "ow": ["Projection magnification is a different mechanism.", "Angular magnification uses a lens.", "Relative size magnification enlarges the object itself.", "Correct. Moving 40 cm to 10 cm is relative distance magnification (4×)."]}'),
  ('9d7d2c4d-1v','{"options": ["+2.50 D", "+5.00 D", "+10.00 D", "+20.00 D"], "correct": 2, "decode": "On the 40 cm reference, 1× = +2.50 D, so equivalent add = M × 2.50. Steps: 4× = 4 × 2.50 = +10.00 D (on the 25 cm reference, 4× = +16 D).", "ow": ["+2.50 D is 1× on this reference, not 4×.", "+5.00 D is 2×.", "Correct. 4 × 2.50 = +10.00 D on the 40 cm reference.", "+20.00 D is 8× on this reference."]}'),
  ('ec03c54b-14','{"options": ["Stays the same", "Narrows", "Widens then narrows", "Widens"], "correct": 1, "decode": "As magnification rises, the field of view NARROWS (shorter focal length, smaller field).", "ow": ["It does not stay the same.", "Correct. Higher magnification narrows the field.", "It narrows steadily, not widens-then-narrows.", "It narrows, not widens."]}'),
  ('2e328da6-2i','{"options": ["A reverse telescope", "A closed-circuit television", "A stand magnifier", "A high-add bifocal"], "correct": 0, "decode": "A REVERSE TELESCOPE (minifying) widens the apparent field for severe field constriction.", "ow": ["Correct. A reverse telescope minifies to fit more into the field.", "A CCTV magnifies, worsening constriction.", "A stand magnifier magnifies, worsening constriction.", "A high-add bifocal magnifies, worsening constriction."]}'),
  ('01f71a7d-1t','{"options": ["Clearer, darker, nearer", "Stronger, longer, wider", "Bigger, bolder, brighter", "Sharper, smaller, closer"], "correct": 2, "decode": "The low vision prescribing goal is BIGGER, BOLDER, BRIGHTER (magnification, contrast, illumination).", "ow": ["''Clearer, darker, nearer'' is not the summary.", "''Stronger, longer, wider'' is not the summary.", "Correct. Bigger, bolder, brighter.", "''Sharper, smaller, closer'' is not the summary."]}'),
  ('1ca6a319-2o','{"options": ["Halogen", "Fluorescent", "Incandescent", "Natural daylight"], "correct": 0, "decode": "HALOGEN gives high-intensity, directional light with longer life than ordinary bulbs.", "ow": ["Correct. Halogen is high-intensity, directional, long life.", "Fluorescent is cheap but scatters light.", "Incandescent is directional and dimmable but runs hot with short life.", "Natural daylight is free but uncontrollable."]}'),
  ('2ecb8359-27','{"options": ["Low frequencies only", "High frequencies only", "All frequencies equally", "Middle frequencies"], "correct": 3, "decode": "Glaucoma reduces contrast sensitivity mainly at MIDDLE spatial frequencies.", "ow": ["Low frequencies only is not the glaucoma pattern.", "High frequencies only is the mild-refractive-error pattern.", "Diabetic retinopathy, not glaucoma, degrades all frequencies.", "Correct. Glaucoma hits middle spatial frequencies."]}'),
  ('96acc603-1j','{"options": ["Does not recover to the pre-surgery level", "Improves beyond baseline", "Is unaffected throughout", "Returns to the pre-surgery level"], "correct": 0, "decode": "After refractive surgery, contrast sensitivity typically DOES NOT recover to the pre-surgery level even when Snellen does.", "ow": ["Correct. CS does not fully return to pre-op level.", "It does not improve beyond baseline.", "It is affected, not unaffected.", "It does not fully return to the pre-surgery level."]}'),
  ('5a05cc69-1x','{"options": ["Arcuate scotoma then nasal step", "Central scotoma then metamorphopsia", "Ring scotoma then tunnel vision", "Bitemporal hemianopsia"], "correct": 2, "decode": "Retinitis pigmentosa produces a RING SCOTOMA that closes inward to TUNNEL VISION.", "ow": ["Arcuate scotoma then nasal step is the glaucoma sequence.", "Central scotoma then metamorphopsia is a macular pattern.", "Correct. RP: ring scotoma then tunnel vision.", "Bitemporal hemianopsia is a chiasmal defect."]}'),
  ('f42ac392-1d','{"options": ["Arcuate scotoma", "Homonymous hemianopsia", "Central scotoma", "Ring scotoma"], "correct": 2, "decode": "A macular hole produces a CENTRAL SCOTOMA.", "ow": ["An arcuate scotoma is a glaucomatous defect.", "Homonymous hemianopsia is a post-chiasmal defect.", "Correct. A macular hole gives a central scotoma.", "A ring scotoma is a mid-peripheral RP pattern."]}'),
  ('4453ed43-1r','{"options": ["Nuclear cataract", "Aphakia", "Retinoblastoma", "Normal variation"], "correct": 2, "decode": "A whitish pupil (LEUKOCORIA) in a child should raise suspicion of RETINOBLASTOMA (same-day referral).", "ow": ["A nuclear cataract looks brownish, not the urgent white of leukocoria.", "Aphakia does not produce leukocoria.", "Correct. Leukocoria suggests retinoblastoma until excluded.", "A whitish pupil is not a normal variation."]}'),
  ('e4a441c7-13','{"options": ["20/400", "20/200", "20/50", "20/800"], "correct": 3, "decode": "Visual acuity at birth is about 20/800 (blurry, light-responsive; ~20/400 by one month).", "ow": ["20/400 is roughly the one-month level, not birth.", "20/200 overstates newborn vision.", "20/50 is roughly the one-year level.", "Correct. Birth VA is about 20/800."]}'),
  ('d6bbe0de-1q','{"options": ["6 months", "5 years", "1 year", "3 years"], "correct": 3, "decode": "Visual acuity reaches adult level (~20/20) at about 3 years.", "ow": ["6 months is too early for adult acuity.", "5 years is later than foveal maturation completes acuity.", "1 year is about 20/50, not adult level.", "Correct. Adult VA is reached by about age 3."]}'),
  ('d1cf09ee-19','{"options": ["6 months", "2 months", "Birth", "30 weeks gestation"], "correct": 3, "decode": "The pupillary light reaction first appears at about 30 weeks gestation (before birth).", "ow": ["6 months is far too late; the reflex is present at birth.", "2 months is later than its prenatal appearance.", "It appears before birth, not at birth.", "Correct. Pupil light reaction by ~30 weeks gestation."]}'),
  ('38ee1fc9-12','{"options": ["2 years", "Birth", "1 month", "4 months"], "correct": 3, "decode": "Foveal maturation is complete at about 4 months (optic nerve myelination continues to age 2).", "ow": ["2 years is when myelination completes, not foveal maturation.", "It is not mature at birth.", "1 month is too early for foveal maturation.", "Correct. Foveal maturation by about 4 months."]}'),
  ('1370dbf3-1p','{"options": ["The ocular blood vessels", "The crystalline lens", "The corneal stroma", "The neural retina"], "correct": 0, "decode": "The OCULAR BLOOD VESSELS develop LAST, at about the 8th month (late vascular development underlies ROP).", "ow": ["Correct. Blood vessels develop last (8th month).", "The lens begins earlier (7th month).", "The corneal stroma develops earlier (~4th month).", "The neural retina develops earlier (~6th month)."]}'),
  ('039b90cf-18','{"options": ["Persistent fetal vasculature", "Coats'' disease", "Retinopathy of prematurity", "Congenital cataract"], "correct": 2, "decode": "Retrolental fibroplasia is the older term for RETINOPATHY OF PREMATURITY.", "ow": ["Persistent fetal vasculature is a different entity.", "Coats'' disease is a separate telangiectatic disease.", "Correct. RLF is the old name for ROP.", "Congenital cataract is a media opacity, not RLF."]}'),
  ('435e9988-22','{"options": ["Hearing", "Feeding", "Bladder control", "Reading and writing"], "correct": 3, "decode": "A persistent ATNR (fencing) reflex beyond 6 to 7 months classically disrupts READING and WRITING.", "ow": ["It does not primarily disrupt hearing.", "It does not primarily disrupt feeding.", "It does not affect bladder control.", "Correct. Persistent ATNR disrupts reading and writing."]}'),
  ('0e9f661d-2b','{"options": ["The rooting reflex", "The Landau reflex", "The Moro reflex", "The Galant reflex"], "correct": 2, "decode": "The MORO (startle) reflex is tested to screen hearing and, if persistent, is linked to ADHD.", "ow": ["The rooting reflex is a feeding reflex, not a hearing screen.", "The Landau reflex concerns motor development, not hearing.", "Correct. The Moro reflex screens hearing; persistence links to ADHD.", "The Galant reflex is a spinal/trunk reflex, not a hearing screen."]}'),
  ('4310a774-2g','{"options": ["4 years", "2 years", "1 year", "6 months"], "correct": 1, "decode": "The Babinski reflex should integrate by about 2 years; beyond that it is pathological (UMN lesion).", "ow": ["4 years is too late; it integrates earlier.", "Correct. Babinski integrates by about 2 years.", "1 year is too early for full integration.", "6 months is too early."]}'),
  ('8f02599b-1u','{"options": ["28 weeks", "37 weeks", "36 weeks", "32 weeks"], "correct": 3, "decode": "The suck reflex is characteristically ABSENT in babies born before about 32 weeks gestation.", "ow": ["28 weeks is earlier than the usual suck-reflex threshold.", "37 weeks is term; suck is present.", "36 weeks is near term; suck is present.", "Correct. Suck is absent below about 32 weeks."]}'),
  ('d383d6ad-1j','{"options": ["A motor development problem", "A hearing deficit", "Normal integration", "A visual field defect"], "correct": 0, "decode": "An ABSENT Landau reflex between 1 and 3 years indicates a MOTOR DEVELOPMENT problem (Landau is the exception: absence, not persistence, is the red flag).", "ow": ["Correct. Absent Landau signals a motor development issue.", "It is not a hearing deficit indicator.", "Absence is abnormal, not normal integration.", "It does not indicate a visual field defect."]}'),
  ('937f4083-2g','{"options": ["10%", "50%", "Virtually all", "25%"], "correct": 1, "decode": "After 20 years of Type 1 diabetes, roughly 50% have PROLIFERATIVE retinopathy (duration is the dominant risk factor).", "ow": ["10% badly understates it at 20 years.", "Correct. About 50% have PDR past 20 years.", "''Virtually all'' overstates the proliferative fraction.", "25% is roughly the proliferative fraction past 15 years, not 20."]}'),
  ('26d44228-20','{"options": ["Virtually all", "About 20%", "50%", "0%"], "correct": 1, "decode": "About 20% of Type 2 patients already have retinopathy AT DIAGNOSIS (silent prior years), so dilate immediately.", "ow": ["''Virtually all'' overstates it at diagnosis.", "Correct. About 20% have DR at diagnosis.", "50% overstates it at diagnosis.", "It is not 0%; the disease ran silently beforehand."]}'),
  ('c92d961d-27','{"options": ["10%", "30%", "60%", "95%"], "correct": 2, "decode": "After 10 years of Type 1 diabetes, roughly 60% show some retinopathy (rising to virtually all past 15).", "ow": ["10% badly understates it at 10 years.", "30% understates it.", "Correct. About 60% have some DR past 10 years.", "95% is closer to the past-15-year figure, not 10."]}'),
  ('230461dc-q','{"options": ["What the body does to the drug", "What the drug does to the body", "Receptor binding", "Only drug side effects"], "correct": 0, "decode": "Kinetics vs dynamics is a word pair. Kine- (movement) is what the BODY does to the drug (ADME). If the option is about the drug''s effect ON the body, that is dynamics, the opposite.", "ow": ["Correct. Pharmacokinetics = absorption, distribution, metabolism, excretion.", "That is pharmacodynamics, the mirror term.", "A piece of dynamics (how the drug acts), not kinetics.", "Too narrow; kinetics covers the whole ADME journey."]}'),
  ('a031e005-1s','{"options": ["Kidney; glomerulus", "Lung; surfactant", "Liver; cytochrome P-450", "Spleen; macrophages"], "correct": 2, "decode": "Two-part answer, so both halves must be right. Metabolism = liver, and the liver''s engine is cytochrome P-450. Any option pairing the wrong organ or a non-P-450 enzyme fails.", "ow": ["The kidney excretes, it does not metabolize; wrong half.", "Surfactant has nothing to do with drug metabolism.", "Correct. The liver metabolizes via the P-450 system.", "The spleen filters cells, it does not biotransform drugs."]}'),
  ('e3b2402f-1a','{"options": ["High bioavailability", "High potency", "High efficacy", "Tolerance"], "correct": 1, "decode": "Potency and efficacy are the classic pair. Potency = how LITTLE you need (dose). Efficacy = the biggest effect possible. ''Low dose'' is a potency statement.", "ow": ["That is fraction absorbed, a kinetic term, not the dose-response property.", "Correct. Potency is defined by how small a dose produces the effect.", "Efficacy is the maximum effect, not the dose needed.", "A falling response with repeated dosing, unrelated to dose potency."]}'),
  ('aec763f7-1v','{"options": ["Sublingual", "Intravenous", "Oral", "Rectal"], "correct": 1, "decode": "''100% bioavailability'' means the drug skips absorption entirely, so pick the route that goes straight into blood: IV. Any route that must cross a membrane loses some fraction.", "ow": ["Good absorption and bypasses first-pass, but still an absorption step, so under 100%.", "Correct. Placed directly in the circulation, no absorption step.", "Absorption plus first-pass loss, the lowest bioavailability.", "Only partial absorption, not complete."]}'),
  ('9cb74000-1n','{"options": ["Plasma protein binding", "The natural log of 2", "A safety margin", "The speed of light"], "correct": 1, "decode": "0.693 appears wherever something HALVES, because it is ln 2. Half-life is a halving, so t-half = 0.693/k. Recognize the number, not the biology.", "ow": ["Unrelated; binding is a percentage, not a log constant.", "Correct. ln 2 = 0.693, the halving constant.", "That is the therapeutic index, a different idea.", "A distractor with no pharmacologic meaning."]}'),
  ('c5dcf52c-12','{"options": ["Potency / efficacy", "LD50 / ED50", "Vd × Ke", "ED50 / LD50"], "correct": 1, "decode": "The therapeutic index is a SAFETY ratio, so a bigger number must mean safer: the lethal dose goes on top, LD50/ED50. The flipped ED50/LD50 is the trap.", "ow": ["Not a safety ratio at all.", "Correct. Toxic dose over effective dose; larger = safer.", "That is clearance, a kinetic formula.", "Inverted, so it would make safe drugs look dangerous."]}'),
  ('f506c508-1y','{"options": ["Binds a different receptor", "Forms an irreversible covalent bond", "Is reversible and overcome by more agonist", "Forms an inactive compound"], "correct": 2, "decode": "''Competitive'' = competing at the SAME site, so more agonist outcompetes it (reversible). ''Non-competitive'' bonds covalently and cannot be beaten by more agonist. Match the word to reversibility.", "ow": ["Then it would not compete at the same site.", "That describes the non-competitive antagonist.", "Correct. Weak reversible binding, beaten by extra agonist.", "That is chemical antagonism, a different mechanism."]}'),
  ('3031e885-21','{"options": ["Additive effect", "Synergism", "Potentiation", "Antagonism"], "correct": 2, "decode": "Do the arithmetic. Potentiation = 0 + 1 > 1 (an inactive drug amplifies an active one). Additive = 1 + 1. Synergism = 1 + 1 > 2. ''No effect of its own'' forces potentiation.", "ow": ["Both drugs are active and simply sum.", "Both are active and the combination exceeds the sum.", "Correct. An inactive drug magnifies an active one (0+1>1).", "One drug reduces the other, the opposite."]}'),
  ('318b3b91-15','{"options": ["Charged and ionized", "Polar and water-soluble", "Uncharged, lipid-soluble", "Bound to plasma protein"], "correct": 2, "decode": "Membranes are fatty, so the absorbable form is the uncharged, lipid-soluble one. Any option with ''charged/ionized/polar/water-soluble'' is the opposite of absorbable.", "ow": ["Ionized forms cannot cross lipid membranes.", "Water-loving means membrane-repelled.", "Correct. Neutral, fat-soluble drug crosses easily.", "Bound drug is trapped in plasma, not free to cross."]}'),
  ('74dc3d28-1b','{"options": ["Volume of distribution", "Half-life", "Bioavailability", "Clearance"], "correct": 0, "decode": "A recall pick: the reviewer names volume of distribution as the key PK parameter (how much drug sits in tissue vs plasma). The others are real PK terms but derived from it.", "ow": ["Correct. Estimates tissue vs plasma partitioning.", "Important, but derived from Vd and clearance.", "Fraction reaching circulation, not the headline parameter here.", "Rate of removal, also derived from Vd."]}'),
  ('73d0f942-1x','{"options": ["Atropine", "Timolol", "Penicillin", "Pilocarpine"], "correct": 0, "decode": "The options span classes, so the discriminator is the oddly specific clause: ''excreted unchanged, toxicity test.'' That fingerprint is bolted to atropine. Penicillin is the trap (also renally handled) but is not the toxicity-test drug.", "ow": ["Correct. Excreted unchanged in urine; the basis of its toxicity test.", "Hepatically metabolized; no such urine toxicity test.", "Renally excreted (the trap) but not the toxicity-test drug.", "A short-acting muscarinic agonist; not the fingerprint here."]}'),
  ('59ac05b5-1t','{"options": ["Take", "Dispense", "Cure", "Write"], "correct": 0, "decode": "Rx is the superscription from Latin recipe = ''take (thou).'' Translate the root and ignore the modern-sounding options.", "ow": ["Correct. From recipe, ''take.''", "That is a label instruction, not the Rx symbol''s meaning.", "Not the literal root.", "Not the meaning of recipe."]}'),
  ('6afbabe0-2g','{"options": ["Schedule V", "Schedule III", "Schedule I", "Schedule IV"], "correct": 2, "decode": "Schedules run I to V and abuse potential FALLS as the number rises. ''No accepted medical use'' is the most restrictive, so it is Schedule I (heroin, LSD).", "ow": ["Lowest abuse potential, freely medical.", "Moderate abuse, accepted medical use.", "Correct. Highest abuse and no accepted medical use.", "Low abuse, accepted medical use."]}'),
  ('47facfdd-1r','{"options": ["Oxidation", "Methylation", "Glucuronidation", "Conjugation"], "correct": 0, "decode": "Phase I ''unmasks'' a polar group, most often by OXIDATION (P-450). Phase II is conjugation. If the reaction adds a big group, it is Phase II, so oxidation is the Phase I answer.", "ow": ["Correct. The commonest Phase I reaction, via P-450.", "A Phase II conjugation.", "The classic Phase II conjugation.", "Defines Phase II, not Phase I."]}'),
  ('f346ab3e-1s','{"options": ["Potentiation", "Hypersensitivity", "Tachyphylaxis", "Idiosyncrasy"], "correct": 2, "decode": "''Rapid'' + ''few doses'' is the tachyphylaxis fingerprint (tachy = fast). Ordinary tolerance builds slowly, so the speed word points to the ''tachy'' term.", "ow": ["A drug interaction, not tolerance.", "An immune over-reaction, not tolerance.", "Correct. Fast tolerance after only a few doses.", "A genetically odd response, not tolerance."]}'),
  ('0d45d0be-1c','{"options": ["Covalent", "Hydrogen", "Van der Waals", "Ionic"], "correct": 0, "decode": "Bond-strength ladder: covalent (strongest, irreversible) > ionic > hydrogen > Van der Waals (weakest, most common). ''Strongest/irreversible'' = covalent.", "ow": ["Correct. Strongest and effectively irreversible.", "Weak and reversible.", "Weakest of all, though the most common clinically.", "Stronger than hydrogen but not irreversible."]}'),
  ('c30e41ac-u','{"options": ["Vd / dose", "ED50/LD50", "Vd × Ke", "100/f"], "correct": 2, "decode": "Clearance = volume cleared per unit time = Vd × Ke (elimination constant). Recognize the formula; ED50/LD50 is the therapeutic-index decoy.", "ow": ["Not a clearance formula.", "That is inverse therapeutic index.", "Correct. Volume of distribution times elimination rate constant.", "Meaningless as a clearance expression."]}'),
  ('fc4b987a-1e','{"options": ["Oral", "Both undergo first pass", "Neither reaches blood", "Sublingual"], "correct": 3, "decode": "First-pass is the liver taxing orally absorbed drug. Routes draining into systemic veins BEFORE the liver escape it: sublingual, rectal (partly), parenteral. Oral suffers it, so the non-oral mucosal route is the answer.", "ow": ["The route that undergoes first-pass, not bypasses it.", "False; sublingual bypasses it.", "Both do reach blood.", "Correct. Drains to systemic veins, skipping the hepatic first-pass."]}'),
  ('7879630f-2i','{"options": ["Sphincter M3; dilator α1", "Sphincter α1; dilator M3", "Both M3", "Both α1"], "correct": 0, "decode": "Two-part receptor answer. The sphincter (constricts) is parasympathetic = M3; the dilator is sympathetic = α1. Any option that swaps them or makes both the same fails.", "ow": ["Correct. Parasympathetic M3 constricts, sympathetic α1 dilates.", "Reversed; α1 dilates and M3 constricts.", "The dilator is sympathetic (α1), not M3.", "The sphincter is parasympathetic (M3), not α1."]}'),
  ('7ce847d5-1v','{"options": ["1 dilates, 2 constricts", "Both constrict", "1 constricts/contracts, 2 dilates", "Both dilate"], "correct": 2, "decode": "The autonomic ''number rule'': receptor 1 constricts/contracts, receptor 2 dilates. α1 gives mydriasis (dilator contracts), β2 dilates. This one line sorts the whole table.", "ow": ["Backwards.", "The 2-receptors dilate.", "Correct. The number rule.", "The 1-receptors constrict/contract."]}'),
  ('ee03580e-p','{"options": ["Contracting the ciliary muscle", "Increasing uveoscleral outflow", "Decreasing aqueous production", "Blocking adenylate cyclase"], "correct": 0, "decode": "Label the drug first: pilocarpine is a miotic (M3 agonist, green cap). Miotics lower IOP by pulling the trabeculum open, so expect an OUTFLOW / muscle mechanism, never a ''decreasing production'' line (that belongs to beta blockers, CAIs, alpha-2s).", "ow": ["Correct. Ciliary contraction pulls the trabeculum open (trabecular outflow).", "That is the prostaglandin route, not the miotic''s trabecular one.", "Production-cutter language (beta blockers/CAIs/alpha-2), not a miotic.", "A beta-blocker mechanism, planted as a trap."]}'),
  ('001786a1-1h','{"options": ["Cyclopentolate", "Atropine", "Tropicamide", "Homatropine"], "correct": 1, "decode": "Cycloplegic strength ladder runs from atropine (strongest, up to 14 days) down to tropicamide (weakest, hours). ''Strongest and longest'' = atropine.", "ow": ["The routine mid-strength choice, not the strongest.", "Correct. Strongest and longest (up to 14 days).", "The weakest and shortest.", "Intermediate, weaker than atropine."]}'),
  ('71aa4620-27','{"options": ["Proparacaine", "Atropine", "Phenylephrine", "Cyclopentolate"], "correct": 3, "decode": "Step 1, kill wrong categories: ''cycloplegic'' rules out phenylephrine (mydriatic only) and proparacaine (a -caine anesthetic). Step 2, read the qualifier: ''routine, shorter than atropine'' pushes you off atropine to cyclopentolate. Answer the modifier, not just the class.", "ow": ["A -caine anesthetic, not a cycloplegic at all.", "Cycloplegic but the strongest and longest (up to 14 days), not routine.", "Mydriatic only (alpha-1); it does not cycloplege.", "Correct. Reliable cycloplegia, much shorter than atropine, so the routine pick."]}'),
  ('3a332e82-2b','{"options": ["2.5% phenylephrine", "4% cocaine", "0.1% pilocarpine", "1% pilocarpine"], "correct": 2, "decode": "''Supersensitivity'' plus a DILUTE concentration is the whole tell. A denervated sphincter over-responds, so it constricts to weak (0.1%) pilocarpine that would not move a normal pupil. Pair it with Horner''s, which dilates to 0.1% epinephrine.", "ow": ["A dilator, wrong direction; Adie''s needs a constrictor.", "That is the Horner''s test agent, not the Adie''s one.", "Correct. Weak dose constricts the supersensitive Adie''s sphincter.", "Too strong; it also moves a normal pupil, so it fails to discriminate."]}'),
  ('c1bdf579-29','{"options": ["Hydroxyamphetamine", "Pilocarpine", "Cocaine", "Atropine"], "correct": 2, "decode": "Cocaine blocks NE reuptake; a Horner''s eye has no NE to potentiate, so it FAILS to dilate (confirming). Hydroxyamphetamine comes second, to LOCALIZE the lesion.", "ow": ["That localizes the lesion, it does not confirm.", "Used for Adie''s, not Horner''s.", "Correct. Confirms Horner''s when the pupil fails to dilate.", "An antimuscarinic dilator, not the Horner''s test."]}'),
  ('2cc0b54c-23','{"options": ["Pilocarpine and carbachol", "Atropine and homatropine", "Echothiopate and DFP", "Timolol and betaxolol"], "correct": 2, "decode": "Iris cysts come from the strong, irreversible anticholinesterases (echothiopate, DFP), reversed by 2.5% phenylephrine. Reversible pilocarpine and the non-miotics are traps.", "ow": ["Reversible miotics; not the cyst-causing pair.", "Antimuscarinics (mydriatics), not miotics.", "Correct. Irreversible AChE inhibitors that cause iris cysts.", "Beta blockers, not miotics."]}'),
  ('ee5e1632-1o','{"options": ["Timolol", "Pilocarpine", "Physostigmine", "Atropine"], "correct": 3, "decode": "Organophosphates flood muscarinic receptors (cholinergic crisis), so you BLOCK them with atropine. Physostigmine (another AChE inhibitor) would worsen it, the trap.", "ow": ["A beta blocker, unrelated to cholinergic crisis.", "A cholinergic agonist; it would worsen the poisoning.", "Another AChE inhibitor, exactly the wrong direction.", "Correct. Antimuscarinic that reverses the cholinergic crisis."]}'),
  ('500aa7fd-1p','{"options": ["Carteolol", "Timolol", "Betaxolol", "Levobunolol"], "correct": 2, "decode": "When a stem bolts on a lung or heart comorbidity, it is asking for the SELECTIVE agent. Find the cardio-selective (beta-1) odd one out: betaxolol. Timolol, carteolol and levobunolol are all non-selective and hit airway beta-2.", "ow": ["Non-selective; hits airway beta-2, unsafe in asthma.", "Non-selective, the classic asthma/COPD contraindication.", "Correct. Cardio-selective (beta-1), spares the airways.", "Non-selective, same airway risk."]}'),
  ('a5bfeac8-1d','{"options": ["Opening the trabeculum mechanically", "Causing mydriasis", "Decreasing aqueous production", "Increasing aqueous production"], "correct": 2, "decode": "α2 agonists (brimonidine) mainly cut aqueous PRODUCTION (with a little outflow). ''Increasing production'' is the opposite trap; mechanical trabeculum-opening is the miotic route.", "ow": ["That is the miotic (pilocarpine) route.", "α2 does not lower IOP by dilating.", "Correct. The main α2 mechanism.", "The opposite; that would raise IOP."]}'),
  ('a7217e30-13','{"options": ["Dilate the pupil", "Reverse pharmacologic mydriasis", "Stain the cornea", "Anesthetize the cornea"], "correct": 1, "decode": "Both are α1 BLOCKERS, so they undo α1-driven dilation: they reverse pharmacologic mydriasis (constrict). ''Dilate'' is the opposite of an α1 blocker.", "ow": ["α1 blockers constrict, they do not dilate.", "Correct. α1 blockade brings a dilated pupil back down.", "That is a dye''s job, not an α1 blocker.", "That is a -caine, not these drugs."]}'),
  ('8b0c0478-q','{"options": ["Blocking acetylcholine release", "Blocking sodium channels", "Stimulating M3 receptors", "Increasing aqueous outflow"], "correct": 0, "decode": "Mechanism items are a matching game: attach each verb to its class, then pick the one that fits the named drug. Botulinum acts presynaptically, so ''blocks ACh release'' is the only fit.", "ow": ["Correct. Presynaptic ACh-release blockade paralyzes the muscle.", "That is a local anesthetic''s mechanism.", "That is pilocarpine (a muscarinic agonist), the opposite action.", "A glaucoma-drug effect, unrelated to botulinum."]}'),
  ('a1928086-1h','{"options": ["Tyrosine → DOPA", "Dopamine → NE", "DOPA → dopamine", "NE → epinephrine"], "correct": 0, "decode": "In any biosynthesis the rate-limiting step is the first committed one. For NE: tyrosine → DOPA (tyrosine hydroxylase). The later conversions are not the bottleneck.", "ow": ["Correct. Tyrosine hydroxylase, the rate-limiting first step.", "A later step, not rate-limiting.", "Downstream, not the bottleneck.", "The final adrenal step, not rate-limiting for NE."]}'),
  ('4d0609d2-1c','{"options": ["Prostaglandin", "Beta blocker", "Alpha-2 agonist", "AChE inhibitor"], "correct": 1, "decode": "Read this as spelling, not pharmacology. The stem hands you the suffix, so the answer is whatever class that suffix tags. Keep the table loaded: -olol beta blocker, -onidine alpha-2, -zoline alpha-1 decongestant, -stigmine AChE inhibitor, -prost prostaglandin. Suffix items are free points if you never overthink them.", "ow": ["Wrong suffix: prostaglandins end in -prost (latanoprost).", "Correct. -olol is the beta-blocker tag (timolol, betaxolol).", "That is the -onidine ending (brimonidine, apraclonidine).", "That is -stigmine (physostigmine, neostigmine)."]}'),
  ('68ffcbbe-1o','{"options": ["It inhibits acetylcholinesterase", "α1 agonist; ciliary muscle has no α1", "It acts as a local anesthetic", "It blocks M3 on the sphincter"], "correct": 1, "decode": "Phenylephrine hits α1 on the DILATOR (mydriasis), but the ciliary muscle is pure M3 with no α1, so accommodation is spared. Match the receptor to the muscle.", "ow": ["Wrong mechanism entirely.", "Correct. Dilates via α1, spares the M3-only ciliary muscle.", "Phenylephrine is not an anesthetic.", "That antimuscarinic action would also cause cycloplegia."]}'),
  ('2fa1948f-1q','{"options": ["Cyclopentolate", "Tropicamide", "Scopolamine", "Atropine"], "correct": 1, "decode": "''Routine mydriatic, weak cycloplegic, short, safe'' = tropicamide. Do not confuse with the routine CYCLOPLEGIC (cyclopentolate); read whether the stem wants dilation or cycloplegia.", "ow": ["The routine cycloplegic, stronger and longer.", "Correct. Short, safe routine mydriatic.", "A strong, long antimuscarinic, not routine dilation.", "Strongest and longest, reserved, not routine."]}'),
  ('df0be4e6-2m','{"options": ["Timolol", "Brimonidine", "Betaxolol", "Metoprolol"], "correct": 0, "decode": "Same asthma cue as the betaxolol item, but flipped: now it wants the NON-selective one, so betaxolol is the deliberate opposite-trap. Timolol is the default topical glaucoma beta blocker and is non-selective.", "ow": ["Correct. Non-selective topical beta blocker, contraindicated in asthma and IDDM.", "Not a beta blocker at all (alpha-2 agonist).", "A beta blocker but cardio-selective, the opposite-trap.", "Selective and systemic (cardiac), not the topical glaucoma answer."]}'),
  ('d78ce57f-26','{"options": ["Block M3", "Change norepinephrine levels", "Bind α1 directly", "Constrict the pupil"], "correct": 1, "decode": "''Indirect'' means they act on NE LEVELS, not on the receptor: cocaine blocks reuptake, hydroxyamphetamine releases NE. Any option about binding the receptor directly would be ''direct.''", "ow": ["A muscarinic action, not sympathomimetic.", "Correct. Indirect action via NE reuptake/release.", "That would make them direct, not indirect.", "They dilate, and that names an effect, not the mechanism."]}'),
  ('d1b2ab09-11','{"options": ["Stimulating α1 receptors", "Blocking M3 receptors", "Fluorescing in blue light", "Blocking sodium channels"], "correct": 3, "decode": "Anesthetics stop nerve conduction, and nerves fire through Na+ channels, so they BLOCK sodium channels. The receptor and ''fluorescing'' options belong to other drug types.", "ow": ["A sympathomimetic action, not anesthesia.", "An antimuscarinic action, not anesthesia.", "That is a dye property (fluorescein).", "Correct. Halts depolarization and pain conduction."]}'),
  ('fbc6ec8b-1d','{"options": ["One i = ester, two i''s = amide", "Esters always have two i''s", "All -caines are amides", "By the color of the bottle"], "correct": 0, "decode": "Spelling trick: count the ''i'' before -caine. One i = ester (cocaine, procaine, tetracaine, proparacaine); two i''s = amide (lidocaine, bupivacaine).", "ow": ["Correct. The i-count rule.", "Reversed; esters have one i.", "False; many -caines are esters.", "Not a real distinction."]}'),
  ('4180d2d4-1f','{"options": ["Tetracaine", "Cocaine", "Lidocaine", "Proparacaine 0.5%"], "correct": 3, "decode": "Everyday ocular anesthetic = proparacaine 0.5% (least stinging, fast). Cocaine softens the cornea, tetracaine stings more, lidocaine is mainly injectable.", "ow": ["Effective but stings more than proparacaine.", "Softens the epithelium; avoided for routine drops.", "Mainly an injectable, not the routine drop.", "Correct. The everyday topical anesthetic."]}'),
  ('6beb9609-11','{"options": ["It softens the corneal surface", "It does not numb at all", "It permanently stains cornea", "It is far too short-acting"], "correct": 0, "decode": "Cocaine loosens the corneal epithelium, so applanation reads falsely LOW. It numbs fine; the softened surface is the problem. It is reserved for the Horner''s test.", "ow": ["Correct. A loosened epithelium lowers the applanation reading.", "It does numb; that is not the issue.", "It does not stain.", "Duration is not the reason."]}'),
  ('43d9b3c8-1q','{"options": ["Inflammation speeds metabolism", "Acidic tissue ionizes the drug", "Infection destroys the drug", "Bacteria absorb the drug"], "correct": 1, "decode": "Anesthetics cross nerves in their NON-ionized form; infected tissue is acidic, which ionizes the drug and blocks it. The ''acid ionizes = no penetration'' rule.", "ow": ["Not the mechanism.", "Correct. The charged form cannot cross the nerve.", "Bacteria do not degrade the anesthetic.", "Not a real mechanism."]}'),
  ('9bae5dfa-v','{"options": ["Epithelial defects", "Devitalized cells and mucus", "Corneal endothelium", "Normal epithelium"], "correct": 0, "decode": "Fluorescein pools where the epithelium is BROKEN (defects) and glows green. Devitalized cells/mucus are the rose bengal/lissamine target; intact epithelium and endothelium do not take it up.", "ow": ["Correct. Fluorescein floods breaks in the epithelium.", "That is rose bengal / lissamine green.", "Fluorescein does not stain the endothelium.", "Intact epithelium repels the dye."]}'),
  ('e5da78f6-2d','{"options": ["Trypan blue", "Rose bengal", "Fluorexon", "Indocyanine green"], "correct": 1, "decode": "Rose bengal stains devitalized cells and goes BEFORE fluorescein, whose bright pooling would mask the subtler pattern. ICG and trypan blue are for other jobs.", "ow": ["A surgical capsule stain, not a dry-eye dye.", "Correct. Devitalized-cell stain, used before fluorescein.", "A high-molecular-weight fluorescein for soft lenses, not this.", "A choroidal angiography dye, not a surface stain."]}'),
  ('382bc281-1m','{"options": ["Choroidal neovascular membranes", "The tear film", "The anterior chamber angle", "The corneal epithelium"], "correct": 0, "decode": "ICG is protein-bound and infrared, so it penetrates the RPE to show the CHOROID and its neovascular membranes. Fluorescein shows the retina; ICG shows deeper.", "ow": ["Correct. ICG images the choroidal circulation.", "A surface structure, not an angiography target.", "That is gonioscopy, not ICG.", "Stained by fluorescein, not imaged by ICG."]}'),
  ('06e314df-2s','{"options": ["Seidel test", "TBUT", "Jones I test", "Schirmer test"], "correct": 0, "decode": "Dye streaming green from a wound against concentrated orange dye = Seidel (aqueous leak). TBUT, Jones, and Schirmer test tears or drainage, not wound leaks.", "ow": ["Correct. Leaking aqueous dilutes the dye to a green stream.", "Measures tear-film break-up time.", "Assesses lacrimal drainage.", "Measures tear production."]}'),
  ('b862ce77-q','{"options": ["Image the choroidal vessels", "Stain epithelial defects", "Stain devitalized cells", "Anesthetize the cornea"], "correct": 2, "decode": "Lissamine green stains devitalized cells and mucus, like rose bengal but less stinging. It does not image choroid, stain defects, or anesthetize.", "ow": ["That is ICG.", "That is fluorescein.", "Correct. The rose bengal-type target, more gently.", "That is a -caine."]}'),
  ('75ce6365-13','{"options": ["Both by liver", "Both by kidney", "Plasma pseudo-cholinesterase; liver", "Liver; plasma cholinesterase"], "correct": 2, "decode": "Two-part answer: Esters = plasma (pseudo)cholinesterase; Amides = liver. Any option with both the same, or the pair reversed, is wrong.", "ow": ["Only amides are hepatic; esters are plasma.", "Neither is metabolized by the kidney.", "Correct. Esters by plasma esterase, amides by liver.", "Reversed."]}'),
  ('f639abc1-11','{"options": ["Numb the corneal surface", "Reverse surgical mydriasis", "Stain the anterior capsule", "Image the retinal surface"], "correct": 2, "decode": "Anchor on what the agent IS: trypan blue is a dye, so its verb must be ''stain.'' That deletes ''numb'' (anesthetic) and ''reverse mydriasis'' (alpha-1 blocker). Surgery context (capsulorhexis) points anterior, not retina.", "ow": ["That is an anesthetic (-caine); trypan blue is a dye.", "That is an alpha-1 blocker''s job, not a dye''s.", "Correct. The dye stains the capsule for capsulorhexis.", "Retinal imaging uses fluorescein or ICG, not trypan blue."]}'),
  ('4f18ffac-1a','{"options": ["Causes mydriasis only", "Shortens the block time", "Neutralizes the drug", "Prolongs the block"], "correct": 3, "decode": "Epinephrine vasoCONSTRICTS, keeping the anesthetic in place longer, so it PROLONGS the block. ''Shortens'' is the opposite; bicarbonate speeds onset instead.", "ow": ["A side effect, not the reason for adding it.", "The opposite; it lengthens the block.", "It does not inactivate the anesthetic.", "Correct. Vasoconstriction keeps the drug local longer."]}'),
  ('152f0111-1o','{"options": ["Equal", "Half as potent", "10 times as potent", "100 times"], "correct": 2, "decode": "Tetracaine is about 10x cocaine''s potency (and longer acting) but stings more. Recall the tenfold figure; equal/half/100x are traps.", "ow": ["Tetracaine is far more potent than that.", "The wrong direction.", "Correct. About tenfold cocaine''s potency.", "An overshoot."]}'),
  ('ab550b21-18','{"options": ["Red-free green", "Infrared", "White", "Cobalt blue"], "correct": 3, "decode": "Fluorescein absorbs blue (~465 nm) and emits green, so defects glow under COBALT BLUE. Rose bengal uses white light; infrared is ICG.", "ow": ["Enhances vessels/rose bengal, not fluorescein excitation.", "That is ICG''s wavelength.", "Rose bengal viewing light, not fluorescein.", "Correct. Excites fluorescein to glow green."]}'),
  ('0064a732-2g','{"options": ["Proparacaine", "Benoxinate", "Tetracaine", "Cocaine"], "correct": 3, "decode": "Only cocaine is a natural anesthetic that also blocks NE reuptake (Horner''s test) and dilates. The pure -caines only anesthetize.", "ow": ["An anesthetic only, no Horner''s or mydriatic use.", "An anesthetic (with antibacterial property), not the Horner''s agent.", "An anesthetic only.", "Correct. Anesthetic, mydriatic, and the Horner''s test agent."]}'),
  ('fc9ddbaa-26','{"options": ["Carbonic anhydrase inhibitors", "Prostaglandin analogs", "Alpha-2 agonists", "Beta blockers"], "correct": 1, "decode": "Two phrases in the stem point the same way: ''first-line'' and ''uveoscleral outflow.'' Prostaglandins own both. The moment you see OUTFLOW wording, eliminate the three production-cutters (beta blockers, alpha-2s, CAIs), which lower IOP by making less fluid, not draining more.", "ow": ["Cuts production, not outflow, and is not first-line.", "Correct. First-line and the only class that raises uveoscleral outflow.", "Reduce production (with a little outflow); not the outflow answer.", "Reduce production; the classic ''outflow'' distractor to reject."]}'),
  ('67a820cd-1k','{"options": ["Miotics and osmotics", "Beta blockers, alpha-2s, CAIs", "Osmotic agents only", "Prostaglandins and miotics"], "correct": 1, "decode": "Sort glaucoma drugs into ''three down (production), two out (outflow).'' The three that cut production = beta blockers, alpha-2 agonists, CAIs. Any option with miotics/prostaglandins/osmotics is outflow or water-pull.", "ow": ["Miotics boost outflow; osmotics pull water, neither cuts production.", "Correct. The ''three down'' production-cutters.", "Osmotics dehydrate the vitreous, they do not cut production.", "Both are outflow drugs (the ''two out'')."]}'),
  ('47ec3bf2-1u','{"options": ["Penicillin allergy", "Diabetes", "Asthma", "Sulfa allergy"], "correct": 3, "decode": "Acetazolamide is a SULFONAMIDE, so the contraindication is a sulfa allergy. Penicillin/diabetes/asthma are the wrong allergy or the beta-blocker''s issue.", "ow": ["An unrelated drug family.", "Not the CAI contraindication.", "That is the beta-blocker concern.", "Correct. Acetazolamide is a sulfonamide."]}'),
  ('78cd562c-q','{"options": ["Opening the trabeculum mechanically", "Decreasing aqueous production", "Dilating the pupil", "Increasing uveoscleral outflow"], "correct": 1, "decode": "Beta blockers are a ''three down'' class: they cut aqueous PRODUCTION (block β2 on ciliary epithelium). Outflow or pupil options belong to other classes.", "ow": ["That is the miotic route.", "Correct. Beta blockade reduces secretion.", "Beta blockers do not dilate.", "That is the prostaglandin route."]}'),
  ('4cf9fd94-24','{"options": ["Glycerin", "Isosorbide", "Mannitol", "Urea"], "correct": 2, "decode": "IV mannitol is the go-to osmotic for acute angle-closure and is safe in renal disease. Glycerin raises blood sugar, isosorbide is oral, urea is dated.", "ow": ["Oral, but raises blood glucose.", "Oral, diabetes-safe, but not the acute IV choice.", "Correct. IV osmotic of choice, safe in renal disease.", "An older osmotic, largely replaced."]}'),
  ('fcdabfd2-y','{"options": ["Polymyxin B", "Gentamicin", "Penicillin", "Tetracycline"], "correct": 3, "decode": "Trachoma (and inclusion conjunctivitis) drug of choice = tetracycline (avoid in kids/pregnancy). The others are not the chlamydial choice.", "ow": ["A gram-negative surface agent, not for trachoma.", "An aminoglycoside, not the trachoma DOC.", "Ineffective against chlamydial trachoma.", "Correct. The drug of choice for trachoma."]}'),
  ('29332796-1y','{"options": ["Ototoxic and nephrotoxic", "Cardiotoxic", "Hepatotoxic", "Neurotoxic to the optic nerve"], "correct": 0, "decode": "Aminoglycosides (gentamicin, tobramycin) are classically OTO- and NEPHROTOXIC with prolonged use. Match the class to ear plus kidney toxicity.", "ow": ["Correct. The classic aminoglycoside toxicities.", "Not the aminoglycoside pattern.", "Not the aminoglycoside pattern.", "That is ethambutol, not aminoglycosides."]}'),
  ('512e3574-1d','{"options": ["Adenylate cyclase", "Carbonic anhydrase", "Phospholipase A2", "Cyclooxygenase only"], "correct": 2, "decode": "Steroids act UPSTREAM at phospholipase A2, blocking both prostaglandins and leukotrienes. NSAIDs act downstream at COX only. ''Upstream/both pathways'' = phospholipase A2.", "ow": ["That is beta-blocker territory.", "That is the CAI target.", "Correct. The upstream steroid target.", "That is the NSAID target."]}'),
  ('27f444fb-1p','{"options": ["Nystagmus and diplopia", "Miosis and induced myopia", "Dry eye and lid ptosis", "Glaucoma and PSC cataract"], "correct": 3, "decode": "Long-term steroids = steroid-response GLAUCOMA plus POSTERIOR SUBCAPSULAR cataract. Memorize the pair; the other options are unrelated.", "ow": ["Not steroid effects.", "Not the steroid pair.", "Not the classic steroid duo.", "Correct. The two hallmark steroid complications."]}'),
  ('4e604fbc-1e','{"options": ["Fluorometholone", "Betamethasone", "Dexamethasone", "Prednisolone"], "correct": 0, "decode": "Fluorometholone (FML) raises IOP the least, so it is safest in a steroid responder. The stronger steroids raise IOP more.", "ow": ["Correct. Least IOP rise, safest in responders.", "A potent steroid, more IOP rise.", "A potent steroid, more IOP rise.", "Raises IOP more than FML."]}'),
  ('a830e058-26','{"options": ["Acyclovir", "Amphotericin B IV", "Natamycin", "Tetracycline"], "correct": 2, "decode": "Filamentary fungi (Fusarium, Aspergillus) = topical NATAMYCIN (a polyene). Amphotericin is systemic/yeasts, acyclovir is antiviral, tetracycline is antibacterial.", "ow": ["An antiviral, not antifungal.", "Systemic use / yeasts, not the topical filamentary choice.", "Correct. Topical polyene for filamentary fungal keratitis.", "An antibacterial, not antifungal."]}'),
  ('b0a40ef8-1e','{"options": ["Ciprofloxacin", "Chloramphenicol", "Bacitracin", "Erythromycin"], "correct": 1, "decode": "Aplastic anemia is chloramphenicol''s signature toxicity. The quinolone, bacitracin and erythromycin do not carry that risk.", "ow": ["A fluoroquinolone; not the aplastic-anemia drug.", "Correct. Rare but classic aplastic anemia risk.", "A topical gram-positive agent, no such risk.", "A macrolide, not linked to aplastic anemia."]}'),
  ('ac12e53a-1j','{"options": ["Anti-VEGF", "Topical steroids", "Laser peripheral iridotomy", "Antibiotics"], "correct": 2, "decode": "Angle-closure is a surgical emergency: lower IOP medically, then DEFINITIVELY relieve pupillary block with laser peripheral iridotomy. Steroids/anti-VEGF/antibiotics do not open the angle.", "ow": ["For neovascular disease, not angle-closure.", "Reduce inflammation, do not relieve the block.", "Correct. The definitive treatment.", "No role in angle-closure."]}'),
  ('514e5636-1o','{"options": ["Gentamicin and tobramycin", "Latanoprost", "Natamycin and amphotericin", "Trifluridine and acyclovir"], "correct": 3, "decode": "HSV epithelial keratitis = antivirals (trifluridine, acyclovir, vidarabine). Aminoglycosides/natamycin are antibacterial/antifungal; latanoprost is a glaucoma drug.", "ow": ["Antibacterials, not antivirals.", "A glaucoma prostaglandin, not an antiviral.", "Antifungals.", "Correct. Antivirals for herpetic epithelial keratitis."]}'),
  ('e36dd934-1d','{"options": ["Bacterial conjunctivitis", "Open-angle glaucoma", "Vernal conjunctivitis", "Filamentary fungal keratitis"], "correct": 2, "decode": "Cromolyn is a mast-cell stabilizer, so it treats ALLERGIC (vernal/atopic) conjunctivitis. Not bacterial infection, glaucoma, or fungal keratitis.", "ow": ["Needs an antibiotic, not a stabilizer.", "An unrelated mechanism.", "Correct. An allergic condition; mast-cell stabilizer helps.", "Needs an antifungal."]}'),
  ('d3e2c2b3-23','{"options": ["Aminoglycosides", "Quinolones", "Penicillins", "Sulfonamides"], "correct": 1, "decode": "DNA gyrase = quinolones (nucleic acid synthesis). Penicillins hit cell wall, aminoglycosides/tetracyclines hit protein synthesis, sulfonamides hit folate.", "ow": ["Block protein synthesis (30S), not DNA gyrase.", "Correct. Inhibit DNA gyrase/topoisomerase.", "Inhibit cell-wall synthesis.", "Block folic acid synthesis."]}'),
  ('4eaacc51-1l','{"options": ["Cortisone < prednisolone < dexamethasone", "Fluorometholone < cortisone", "All equal", "Dexamethasone < prednisolone < cortisone"], "correct": 0, "decode": "Potency ladder: cortisone (weak) < prednisolone (~10x) < dexamethasone (strong). Pick the option that runs low-to-high in that order.", "ow": ["Correct. Weak to strong.", "Incomplete and out of order.", "Steroids differ widely in potency.", "Reversed (strong to weak)."]}'),
  ('ef51e5e4-1s','{"options": ["Cherry-red spot", "Bull''s-eye maculopathy", "Cotton-wool spots", "Disc neovascularization"], "correct": 1, "decode": "Drug-toxicity retina items are one-to-one pairs, so memorize the signature and output it: chloroquine/hydroxychloroquine equals bull''s-eye maculopathy. The distractors are other stories dropped in to test recall.", "ow": ["Sign of CRAO or a storage disease, not chloroquine.", "Correct. The chloroquine/hydroxychloroquine signature.", "Ischemic nerve-fiber infarcts (diabetes, hypertension).", "A sign of ischemic retinopathy, unrelated to the drug."]}'),
  ('00aa2d5e-22','{"options": ["Cyanopsia", "Xanthopsia", "Erythropsia", "Chloropsia"], "correct": 1, "decode": "This is vocabulary, not pharmacology. ''-opsia'' means colored vision; decode the color root: xanth- yellow, cyan- blue, erythr- red, chlor- green. ''Yellow'' maps straight to xanthopsia, sitting right in the option list.", "ow": ["Cyan- means blue vision, not yellow.", "Correct. Xanth- is yellow; the digitalis sign.", "Erythr- means red vision.", "Chlor- means green vision."]}'),
  ('3ccbc31d-1k','{"options": ["Rhegmatogenous detachment", "Optic neuritis, red-green defect", "Posterior subcapsular cataract", "Acute angle-closure"], "correct": 1, "decode": "Anti-TB drugs (ethambutol, isoniazid) hit the OPTIC NERVE: optic neuritis with a red-green defect. Monitor color vision. The cataract/detachment/angle options are other drug stories.", "ow": ["Not an anti-TB effect.", "Correct. Ethambutol/INH optic neuropathy.", "That is a steroid effect.", "That is anticholinergics/topiramate, not anti-TB."]}'),
  ('80e0995a-1r','{"options": ["Nuclear cataract only", "A macular cherry-red spot", "A bull''s-eye maculopathy", "Cornea verticillata, halos"], "correct": 3, "decode": "The stem gives the SITE: ''corneal.'' Scan for the corneal option and ignore retinal decoys. Only ''cornea verticillata, halos'' is corneal; bull''s-eye (chloroquine) and cherry-red spot (CRAO) are retina, planted to test tissue-matching.", "ow": ["Not the amiodarone pattern; its deposits are corneal.", "A retinal sign (CRAO), planted to test site-matching.", "That is chloroquine, the classic retinal decoy.", "Correct. Whorl keratopathy plus colored halos."]}'),
  ('2c3abdf9-1k','{"options": ["Snowflake cataract", "No cataract", "Stellate ANTERIOR subcapsular cataract", "Posterior subcapsular cataract"], "correct": 2, "decode": "Phenothiazines (thioridazine, chlorpromazine) = ANTERIOR stellate subcapsular deposits (plus pigmentary retinopathy). Steroids own the POSTERIOR one, the trap.", "ow": ["That is diabetic cataract.", "Phenothiazines do cause lens deposits.", "Correct. The phenothiazine pattern.", "That is steroids, not phenothiazines."]}'),
  ('ce1245fe-1h','{"options": ["Phenylephrine 10%", "Cyclopentolate 2%", "Atropine", "Tropicamide"], "correct": 3, "decode": "All dilators are Category C, so pick the SHORTEST-exposure one: tropicamide (with punctal occlusion). Phenylephrine 10% and atropine carry more load.", "ow": ["High cardiovascular load; avoided in pregnancy.", "Longer and stronger; more systemic exposure.", "Very long-acting; the most exposure.", "Correct. Shortest-acting, least exposure."]}'),
  ('f0f3b9db-23','{"options": ["An immature liver lets it build", "It is an anesthetic overdose", "It precipitated angle-closure", "It is an allergic reaction"], "correct": 0, "decode": "A child''s IMMATURE LIVER cannot clear the drug, so anticholinergic CNS toxicity builds. Use 0.5-1% with lacrimal occlusion. It is not an anesthetic, allergy, or angle-closure.", "ow": ["Correct. Poor hepatic clearance leads to CNS toxicity.", "Cyclopentolate is not an anesthetic.", "Not the cause of the CNS symptoms.", "This is dose toxicity, not allergy."]}'),
  ('6ea1c9a5-18','{"options": ["Topical beta blockers", "Systemic aminoglycosides", "Sulfonamides and acetazolamide", "Topical prostaglandins"], "correct": 2, "decode": "Transient (acute) myopia comes from ciliary-body swelling: sulfonamides, acetazolamide, topiramate, steroids. Beta blockers, aminoglycosides and prostaglandins are not the cause.", "ow": ["Not a cause of transient myopia.", "Oto/nephrotoxic, not myopia-inducing.", "Correct. Ciliary swelling causes transient myopia.", "Cause pigmentation, not myopia."]}'),
  ('31f3f348-2f','{"options": ["Systemic aminoglycosides", "Anticholinergics and TCAs", "Beta blockers and CAIs", "Topical prostaglandins"], "correct": 1, "decode": "Dilating drugs can push a narrow angle shut: anticholinergics, antihistamines and TCAs. The IOP-lowering classes (beta blockers, CAIs) do the opposite.", "ow": ["Do not dilate; no angle-closure risk.", "Correct. Their mydriasis can trigger angle-closure.", "These LOWER IOP, not close the angle.", "Do not dilate or close the angle."]}'),
  ('1aaf4aa3-z','{"options": ["A red-green color defect", "Posterior subcapsular cataract", "A bull''s-eye maculopathy", "Pseudotumor cerebri"], "correct": 3, "decode": "Hypervitaminosis A (also OCPs, tetracycline) causes PSEUDOTUMOR CEREBRI (papilledema). The color/cataract/maculopathy options are other drug toxicities.", "ow": ["That is ethambutol.", "That is steroids.", "That is chloroquine.", "Correct. Vitamin A excess raises intracranial pressure."]}'),
  ('6b77d87c-1u','{"options": ["Dry eye", "Cherry-red spot", "Cataract", "Retinal vascular occlusion"], "correct": 3, "decode": "OCPs are prothrombotic, so the risk is a RETINAL VASCULAR OCCLUSION (and pseudotumor cerebri). Dry eye/cataract/cherry-red are unrelated to their clotting effect.", "ow": ["Not the OCP vascular risk.", "A sign of an occlusion, not the named risk category.", "Not an OCP association.", "Correct. OCPs increase thrombotic risk."]}'),
  ('74c85ea3-19','{"options": ["Systemic antihistamines", "Sulfonamide antibiotics", "Steroids and anticholinergics", "Beta blockers and diuretics"], "correct": 3, "decode": "Lowering-IOP list: beta blockers, diuretics, CAIs, marijuana. Steroids and anticholinergics RAISE IOP; the antihistamine/sulfonamide options do not lower it.", "ow": ["Anticholinergic; can raise, not lower, IOP.", "Do not lower IOP.", "These RAISE IOP.", "Correct. Both lower IOP."]}'),
  ('e98c2c3a-1v','{"options": ["Steroids and oral NSAIDs", "Penicillin, gentamicin", "Chloroquine and amiodarone", "Beta blockers, diuretics"], "correct": 2, "decode": "Whorl keratopathy comes from amphiphilic drugs, mnemonic CATI: Chloroquine, Amiodarone, Tamoxifen, Indomethacin (also chlorpromazine). Pick the amphiphilic pair.", "ow": ["Not the whorl-keratopathy group.", "Antibiotics, not amphiphilic deposit drugs.", "Correct. Classic CATI whorl-keratopathy drugs.", "IOP drugs, not corneal-deposit drugs."]}'),
  ('f9436181-1e','{"options": ["Bull''s-eye macula", "Cherry-red spot", "Cotton-wool spots", "Crystalline retinopathy"], "correct": 3, "decode": "Tamoxifen = CRYSTALLINE retinopathy (and cornea verticillata). Bull''s-eye is chloroquine; cherry-red and cotton-wool are vascular. Match tamoxifen to crystals.", "ow": ["That is chloroquine.", "A CRAO/storage sign.", "Ischemic infarcts.", "Correct. The tamoxifen retinal signature."]}'),
  ('5d39f0f4-1x','{"options": ["Declining liver and kidney", "Larger resting pupils", "Faster hepatic metabolism", "Better gut absorption"], "correct": 0, "decode": "Aging = slower LIVER and KIDNEY clearance, so drugs accumulate (plus polypharmacy). Pupil size, faster metabolism and better absorption are wrong or backwards.", "ow": ["Correct. Slowed clearance causes accumulation.", "Elderly pupils are smaller, and irrelevant here.", "Metabolism slows with age, not speeds.", "Absorption does not improve with age."]}'),
  ('2ebf8782-1f','{"options": ["Acute angle-closure glaucoma", "A red-green color defect", "Dry eye and lens intolerance", "Posterior subcapsular cataract"], "correct": 2, "decode": "Isotretinoin dries mucous membranes: DRY EYE, contact lens intolerance, blepharoconjunctivitis. The angle-closure/color/cataract options are other drugs.", "ow": ["Not the isotretinoin pattern.", "That is ethambutol.", "Correct. Isotretinoin dries the ocular surface.", "That is steroids."]}'),
  ('4049d4b6-18','{"options": ["Cataract and glaucoma", "Xanthopsia and halos", "Aplastic anemia, neuritis", "A bull''s-eye maculopathy"], "correct": 2, "decode": "Chloramphenicol = APLASTIC ANEMIA and optic NEURITIS/atrophy. The cataract/xanthopsia/bull''s-eye options belong to other drugs.", "ow": ["That is steroids.", "That is digitalis/amiodarone.", "Correct. The two chloramphenicol toxicities.", "That is chloroquine."]}'),
  ('fb0e0746-19','{"options": ["Spleen", "Lung", "Kidney", "Liver"], "correct": 3, "decode": "Metabolism = liver (P-450); excretion = kidney. Keep the pair straight and the odd organs (spleen, lung) fall away.", "ow": ["Filters old blood cells, not drugs.", "Minor role only; not the principal site.", "That is the excretion organ, not metabolism.", "Correct. The main biotransformation organ."]}'),
  ('5b54106b-1a','{"options": ["0.693", "1.44", "2.303", "3.14"], "correct": 0, "decode": "The half-life halving constant is ln 2 = 0.693. Pick the number tied to halving; the others are unrelated math constants.", "ow": ["Correct. ln 2, used in t-half = 0.693/k.", "The mean-life factor (1/ln 2), not the half-life constant.", "Converts ln to log10, a different use.", "Pi; no pharmacokinetic role."]}'),
  ('91e40e6b-11','{"options": ["Oral", "Intravenous", "Topical", "Subcutaneous"], "correct": 1, "decode": "Only a route with no absorption step is 100%. IV goes straight into blood; oral/topical/subcutaneous all lose some crossing a barrier.", "ow": ["Absorption plus first-pass loss, the lowest bioavailability.", "Correct. Directly into circulation, 100%.", "Minimal systemic absorption.", "Absorbed from tissue, so under 100%."]}'),
  ('d119e867-1s','{"options": ["Ionic", "Van der Waals", "Covalent", "Hydrogen"], "correct": 2, "decode": "Same bond ladder: covalent is strongest and irreversible; Van der Waals is weakest (yet most common). ''Irreversible'' = covalent.", "ow": ["Moderate strength, reversible.", "Weakest, reversible.", "Correct. Strongest, effectively irreversible.", "Weak, reversible."]}'),
  ('5bfa76ad-14','{"options": ["No accepted medical use", "Low abuse potential", "Accepted use with severe restrictions", "High abuse risk but accepted medical use"], "correct": 0, "decode": "Schedule I is the top of the restriction ladder: high abuse AND no accepted medical use. Any option that grants medical use is not Schedule I.", "ow": ["Correct. Plus high abuse potential (heroin, LSD).", "That describes Schedule V.", "Schedule II wording.", "Schedule II, which does have medical use."]}'),
  ('02644aba-16','{"options": ["Recipe", "Prescription", "Prescribed treatment", "Registered examination"], "correct": 0, "decode": "Rx is literally the Latin recipe (''take''). Pick the root word, not the modern paraphrases.", "ow": ["Correct. Latin for ''take.''", "The document, not the symbol''s origin.", "A paraphrase, not the root.", "An unrelated invented phrase."]}'),
  ('19ea0e88-10','{"options": ["Scopolamine", "Tropicamide", "Cyclopentolate", "Atropine"], "correct": 2, "decode": "Routine CYCLOPLEGIC = cyclopentolate (reliable, shorter than atropine). Tropicamide is the routine mydriatic; atropine is reserved. Read cycloplegic vs mydriatic.", "ow": ["A strong, long antimuscarinic, not the routine choice.", "The routine mydriatic, too weak for reliable cycloplegia.", "Correct. The routine cycloplegic.", "Strongest and longest, reserved for dense cases."]}'),
  ('b678d8d0-29','{"options": ["14 days", "6 hours", "24 hours", "3 days"], "correct": 0, "decode": "Atropine is the longest antimuscarinic: cycloplegia up to 14 days. That extreme duration is why it is reserved, not routine.", "ow": ["Correct. Atropine cycloplegia can last up to two weeks.", "That is tropicamide''s range.", "Closer to cyclopentolate.", "Too short for atropine."]}'),
  ('87f35d4e-1i','{"options": ["Phenylephrine 10%", "Cocaine", "Hydroxyamphetamine", "Dilute pilocarpine"], "correct": 1, "decode": "Confirm Horner''s with cocaine (the pupil fails to dilate). Hydroxyamphetamine is the second-step LOCALIZER, the classic trap.", "ow": ["Used later for denervation/localization, not to confirm.", "Correct. Confirms Horner''s; the pupil fails to dilate.", "Localizes the lesion after confirmation.", "That is the Adie''s test."]}'),
  ('796a872f-1g','{"options": ["Phenylephrine", "Pilocarpine", "Timolol", "Atropine"], "correct": 0, "decode": "Echothiophate iris cysts are prevented and reversed by phenylephrine. Do not pick another cholinergic; you need the sympathomimetic.", "ow": ["Correct. Prevents and reverses the iris cysts.", "A cholinergic; it would not reverse them.", "A beta blocker, unrelated.", "An antimuscarinic; not the standard reversal agent."]}'),
  ('4ae38c73-19','{"options": ["Pilocarpine", "Atropine", "Physostigmine", "Naloxone"], "correct": 1, "decode": "Cholinergic crisis needs a muscarinic BLOCKER: atropine. Physostigmine and pilocarpine are cholinergic (wrong way); naloxone is for opioids.", "ow": ["Cholinergic; it worsens the crisis.", "Correct. The antimuscarinic antidote.", "Another AChE inhibitor, the wrong direction.", "An opioid antagonist, unrelated."]}'),
  ('73f3cf7c-1h','{"options": ["Pilocarpine", "Cocaine", "Atropine", "Edrophonium"], "correct": 3, "decode": "The MG test is edrophonium (Tensilon), a short-acting AChE inhibitor that briefly lifts the ptotic lid. The pupil/autonomic drugs are decoys.", "ow": ["A pupil drug, not the MG test.", "The Horner''s test.", "An antimuscarinic, the opposite of what MG needs.", "Correct. The Tensilon test for myasthenia gravis."]}'),
  ('83f0dbaa-1g','{"options": ["Cocaine 4%", "Proparacaine 0.5%", "Lidocaine 2%", "Tetracaine 1%"], "correct": 1, "decode": "Applanation tonometry anesthetic = proparacaine 0.5% (least stinging, fast). Cocaine softens the cornea; lidocaine/tetracaine are not the routine drop.", "ow": ["Softens the epithelium and lowers the reading.", "Correct. The everyday tonometry anesthetic.", "An injectable, not the routine drop.", "Effective but stings more."]}'),
  ('e4c03ea8-1n','{"options": ["Rose bengal", "Methylene blue", "Indocyanine green", "Trypan blue"], "correct": 0, "decode": "Rose bengal (devitalized-cell stain) goes BEFORE fluorescein, whose bright pooling would mask it. Methylene blue, ICG and trypan blue are for other uses.", "ow": ["Correct. Devitalized-cell stain, instilled before fluorescein.", "Not the standard dry-eye pre-stain.", "A choroidal angiography dye.", "A surgical capsule stain."]}'),
  ('016287a7-16','{"options": ["An aqueous wound leak", "Lacrimal obstruction", "Epithelial abrasion", "Endothelial cell loss"], "correct": 0, "decode": "Seidel = fluorescein revealing an AQUEOUS wound leak (green stream). It is about a leaking full-thickness wound, not drainage, abrasion, or endothelium.", "ow": ["Correct. Leaking aqueous dilutes the dye to a green stream.", "That is the Jones tests.", "Plain fluorescein staining shows this, not the Seidel sign.", "Assessed by specular microscopy, not Seidel."]}'),
  ('8f67f672-v','{"options": ["Endothelial function", "Aqueous production", "Corneal sensitivity", "Lacrimal drainage"], "correct": 3, "decode": "Jones I/II use fluorescein to test whether the nasolacrimal system DRAINS (and functional vs anatomical block). Not endothelium, aqueous, or sensitivity.", "ow": ["Assessed by specular microscopy.", "That is Schirmer for tears / other tests.", "That is esthesiometry.", "Correct. Jones I/II test tear-drainage patency."]}'),
  ('02b30d98-1e','{"options": ["Retinal nerve fiber layer", "Trabecular meshwork", "Corneal endothelium", "Choroidal circulation"], "correct": 3, "decode": "ICG fluoresces in the infrared, penetrating the RPE to show the CHOROID, which fluorescein cannot reach. Not the RNFL, angle, or endothelium.", "ow": ["Imaged by OCT, not ICG.", "Seen on gonioscopy.", "Specular microscopy, not ICG.", "Correct. ICG''s infrared light reaches the choroid."]}'),
  ('1f0b5445-1o','{"options": ["Carbonic anhydrase inhibitors", "Miotics", "Beta blockers", "Prostaglandin analogs"], "correct": 3, "decode": "First-line POAG = prostaglandin analogs (once daily, best IOP drop, few systemic effects) via uveoscleral outflow. CAIs, miotics, beta blockers are later lines.", "ow": ["Effective but not first-line.", "Older and side-effect prone, not first-line.", "A common second choice, not first-line now.", "Correct. First-line for POAG."]}'),
  ('e851009d-1c','{"options": ["Brimonidine", "Latanoprost", "Pilocarpine", "Timolol"], "correct": 2, "decode": "Two outflow routes: TRABECULAR = pilocarpine (miotic pulls the meshwork open); UVEOSCLERAL = prostaglandins. The stem says trabecular, so pilocarpine.", "ow": ["An alpha-2, cuts production.", "Increases UVEOSCLERAL outflow, not trabecular.", "Correct. Opens trabecular outflow via ciliary contraction.", "A beta blocker, cuts production."]}'),
  ('6500ad46-1e','{"options": ["Levobunolol", "Carteolol", "Betaxolol", "Timolol"], "correct": 2, "decode": "Asthma = cardio-selective betaxolol (spares airway β2). The non-selective ones (timolol, carteolol, levobunolol) risk bronchospasm.", "ow": ["Non-selective, airway risk.", "Non-selective (ISA), still airway risk.", "Correct. Cardio-selective, safer in asthma.", "Non-selective, the classic contraindication."]}'),
  ('3084107b-1r','{"options": ["Penicillin", "Aspirin", "Iodine", "Sulfa drugs"], "correct": 3, "decode": "Acetazolamide is a sulfonamide, so caution with a SULFA allergy. Penicillin/aspirin/iodine are the wrong allergy families.", "ow": ["A different drug family.", "Not the CAI cross-reaction.", "An unrelated allergy.", "Correct. Acetazolamide is a sulfonamide."]}'),
  ('f7324ef2-1q','{"options": ["Acetazolamide", "Mannitol", "Glycerin", "Pilocarpine"], "correct": 1, "decode": "IV osmotic in acute angle-closure = mannitol. Acetazolamide is a CAI (cuts production), glycerin is oral, pilocarpine is a miotic.", "ow": ["A CAI, not an osmotic.", "Correct. The IV osmotic for acute angle-closure.", "An oral osmotic, not the IV choice.", "A miotic, not an osmotic."]}'),
  ('74c33851-1l','{"options": ["Fluorometholone", "Prednisolone acetate", "Dexamethasone", "Betamethasone"], "correct": 0, "decode": "Least IOP rise = fluorometholone. The potent steroids (prednisolone acetate, dexamethasone, betamethasone) raise IOP more.", "ow": ["Correct. The smallest IOP rise.", "A potent steroid, more IOP rise.", "A potent steroid, more IOP rise.", "A potent steroid, more IOP rise."]}'),
  ('d5a8d1ec-1v','{"options": ["3 days", "24 hours", "2 weeks", "5 days"], "correct": 3, "decode": "Recall the number: aminoglycosides turn oto/nephrotoxic beyond about 5 days. The shorter/longer options are distractors.", "ow": ["Too soon for the classic cutoff.", "Far too short.", "Beyond the usual 5-day mark.", "Correct. The classic toxicity threshold."]}'),
  ('17907aea-1d','{"options": ["Ethambutol", "Amiodarone", "Chloroquine", "Digitalis"], "correct": 3, "decode": "Yellow vision (xanthopsia) = digitalis. Ethambutol is red-green, chloroquine is bull''s-eye, amiodarone is halos/verticillata. Match yellow to digitalis.", "ow": ["Causes a red-green defect, not yellow vision.", "Causes colored halos and verticillata.", "Causes bull''s-eye maculopathy.", "Correct. The classic cause of xanthopsia."]}'),
  ('b2dc22df-1e','{"options": ["Phenothiazines", "Chloroquine", "Corticosteroids", "Amiodarone"], "correct": 0, "decode": "ANTERIOR stellate (star) cataract = phenothiazines. Steroids give the POSTERIOR subcapsular; chloroquine/amiodarone hit cornea/retina. ''Anterior star'' = phenothiazine.", "ow": ["Correct. Anterior stellate subcapsular deposits.", "Causes bull''s-eye maculopathy and verticillata, not this cataract.", "Cause the posterior subcapsular cataract.", "Causes whorl keratopathy, not a stellate cataract."]}'),
  ('85dcd1fb-1r','{"options": ["Sulfonamide antibiotics", "Digitalis glycosides", "Topical beta blockers", "Tetracycline and OCPs"], "correct": 3, "decode": "Pseudotumor cerebri trio: vitamin A excess, tetracycline, OCPs. Of the options, tetracycline + OCPs fits; the others are unrelated toxicities.", "ow": ["Cause transient myopia, not pseudotumor.", "Cause xanthopsia.", "Lower IOP; unrelated to pseudotumor.", "Correct. Both are pseudotumor cerebri triggers."]}'),
  ('1f670041-17','{"options": ["0.1%", "4%", "2%", "0.5–1%"], "correct": 3, "decode": "Kids get the LOWER strength (0.5-1%) with lacrimal occlusion to avoid CNS toxicity. 2% and 4% are adult/too strong; 0.1% is too weak.", "ow": ["Too weak for cycloplegia.", "Not a standard strength; far too strong for a child.", "Adult strength; risks CNS toxicity in children.", "Correct. The safer pediatric range."]}'),
  ('9e132e5b-z','{"options": ["Digitalis", "Hydroxychloroquine", "Chloramphenicol", "Ethambutol"], "correct": 1, "decode": "Bull''s-eye maculopathy = (hydroxy)chloroquine. Digitalis is xanthopsia, chloramphenicol is aplastic anemia, ethambutol is red-green. Match bull''s-eye to the antimalarial.", "ow": ["Causes xanthopsia.", "Correct. The classic bull''s-eye drug.", "Causes aplastic anemia and neuritis.", "Causes a red-green optic neuropathy."]}'),
  ('11b1dcf6-1h','{"options": ["The maximum effect possible", "The speed of onset", "The duration of action", "How little drug is needed"], "correct": 3, "decode": "Potency = dose sensitivity (how little); efficacy = ceiling effect. The option about DOSE amount is potency; anything about maximum effect or timing is not.", "ow": ["That is efficacy.", "A kinetic property, not potency.", "Also kinetics, not potency.", "Correct. Potency is defined by the required dose."]}'),
  ('1f19d0d1-15','{"options": ["Adding more agonist", "Nothing; it is irreversible", "Waiting for receptor turnover", "Adding a second antagonist"], "correct": 0, "decode": "''Competitive'' means beatable by competition, so flooding with agonist wins. If the option says it cannot be overcome, that is the non-competitive (covalent) type.", "ow": ["Correct. Extra agonist outcompetes reversible binding.", "That is non-competitive antagonism.", "Needed for irreversible blockers, not competitive.", "That would block further, not reverse."]}'),
  ('3aaa964f-19','{"options": ["Purely water-soluble", "Both lipid- and water-soluble", "Fully ionized", "As lipid-soluble as possible"], "correct": 1, "decode": "The cornea is a fat-water-fat sandwich (lipid epithelium, watery stroma, lipid endothelium), so the drug must be BOTH lipid- and water-soluble (biphasic). ''Purely'' anything fails a layer.", "ow": ["Cannot cross the lipid epithelium.", "Correct. Biphasic solubility crosses all three layers.", "Ionized drug is blocked by the lipid layers.", "Then it stalls in the watery stroma."]}'),
  ('6ae2a7fa-17','{"options": ["Excreted in bile", "Metabolized by the liver first", "Excreted unchanged in urine", "Broken down by plasma esterases"], "correct": 2, "decode": "Atropine''s exam fingerprint is ''excreted unchanged in urine'' (basis of its toxicity test). Do not pick a liver or esterase route; those belong to other drugs.", "ow": ["Not atropine''s route.", "Only partly; the tested fact is urinary.", "Correct. The basis of its urine toxicity test.", "That is the ester anesthetics, not atropine."]}'),
  ('b11d011d-1a','{"options": ["Homatropine", "Tropicamide", "Cyclopentolate", "Atropine"], "correct": 1, "decode": "Bottom of the cycloplegic ladder = tropicamide (weak, 4 to 6 hours). This is the flip of the ''strongest = atropine'' item; read weakest vs strongest.", "ow": ["Intermediate strength.", "Correct. Weakest and shortest.", "Stronger and longer than tropicamide.", "The strongest and longest, the opposite end."]}'),
  ('b19d1982-1v','{"options": ["Fails to dilate", "Dilates equally with the fellow eye", "Constricts markedly", "Dilates more than the normal pupil"], "correct": 0, "decode": "In Horner''s there is no NE for cocaine to potentiate, so the affected pupil FAILS to dilate. A normal pupil dilates; the diseased one does not.", "ow": ["Correct. No NE to potentiate, so no dilation.", "That would be a normal result.", "Cocaine does not constrict.", "The opposite of Horner''s."]}'),
  ('46128b3d-1c','{"options": ["Has no effect on IOP", "Opens the trabecular meshwork", "Decreases aqueous secretion", "Increases aqueous secretion"], "correct": 3, "decode": "Number rule: β2 (a ''2'' receptor) increases aqueous secretion, which is why beta BLOCKERS lower IOP. Stimulating β2 does the opposite of a blocker.", "ow": ["β2 clearly modulates aqueous.", "That is the miotic/outflow route.", "That is what BLOCKING β2 does.", "Correct. β2 stimulation raises aqueous production."]}'),
  ('fde5092c-1d','{"options": ["Acute angle-closure glaucoma", "Primary open-angle glaucoma", "Malignant glaucoma", "Accommodative esotropia"], "correct": 2, "decode": "Pilocarpine helps angle-closure and open-angle, but in MALIGNANT (aqueous misdirection) glaucoma it worsens the forward lens-iris push. The odd glaucoma type is the answer.", "ow": ["Pilocarpine is used here.", "A traditional pilocarpine indication.", "Correct. Miotics worsen aqueous misdirection.", "Cholinergics can even help this."]}'),
  ('06d32410-1y','{"options": ["0.1%", "1%", "2%", "4%"], "correct": 0, "decode": "Adie''s is denervation supersensitivity, so a DILUTE 0.1% pilocarpine constricts it. Stronger concentrations would also move a normal pupil and give no discrimination.", "ow": ["Correct. Weak dose constricts the supersensitive Adie''s pupil.", "Too strong; it also moves a normal pupil.", "Far too strong to be diagnostic.", "A therapeutic/normal dose, not the Adie''s test."]}'),
  ('47a4e7e6-i','{"options": ["The corneal endothelium", "Devitalized cells", "Mucus strands", "Epithelial defects"], "correct": 3, "decode": "Fluorescein pools in epithelial BREAKS and glows green. Devitalized cells and mucus are rose bengal/lissamine; the endothelium is not stained.", "ow": ["Fluorescein does not reach or stain it.", "That is rose bengal / lissamine.", "Also a rose bengal-type target.", "Correct. Fluorescein floods epithelial breaks."]}'),
  ('08b30c5f-r','{"options": ["Cobalt blue light", "White light", "Red-free green light", "Infrared illumination"], "correct": 1, "decode": "Rose bengal is viewed under WHITE (or red-free) light, unlike fluorescein which needs cobalt blue. Match the dye to its light.", "ow": ["That is for fluorescein.", "Correct. Rose bengal is seen under white light.", "Can enhance it, but white is the standard answer.", "That is ICG."]}')
)
UPDATE question_reviews r
SET payload = r.payload || d.patch::jsonb
FROM d
WHERE r.question_id = d.qid;
